/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080624-6","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"区民委員会","time":"午前１０時０３分～午後２時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"の「結婚のサポートの事業内容について」","agenda":"の「結婚のサポートの事業内容について」","exchanges":[{"speaker":"稲川委員","kind":"確認","question":"確認の意味を含めていろいろお伺いをしたいのですが、まず、事業目的のところで、「結婚を支援することは、少子化対策」と書いてあるんですけれども、結婚イコール少子化対策になるかどうか、これはちょっと疑問が、個人的なのかもしれないんですけれども、要は、目的のところに少子化対策一つにしか絞られていないというのはちょっと疑問があるということと、あと、パートナーの紹介事業。","respondent":"小野区民課長","answer":"人と出会わないからという答えが約４０％、５０％近い回答がそういう形で来ておりまして、出会いというものがなかなか今の社会状況の中で難しくなっているということもあるというふうに認識をしております。","id":"exchange-001"},{"speaker":"稲川委員","kind":"質問","question":"報告が、２３日ですぐ議会中の委員会じゃないですか。それを取りまとめていただけるのかどうか。","respondent":"小野区民課長","answer":"できるだけそのように努力はしますけれども、日程の関係で十分というところまでいけるかどうか、その辺のところはご容赦をいただきたいと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの答弁の中で、今の社会状況の中で出会いの場が持てなくなっているというところで質問があったんですが、出会いの場が持てないという社会状況の中というのは、どういうふうに社会状況の変化を認識していて、結果、出会いの場がなくなっているのかなというお考えなのかなというのをお伺いしたいと思います。","respondent":"小野区民課長","answer":"以前であれば、まちの中で、あそこには年ごろの人がいるから、この人どうかしらというふうなお話を持ってこられるということだとか、あるいはお見合いだとか、そういうふうな、社会として婚姻を助けるような活動というのがかなりあったわけですけれども、だんだん。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"すみません、次の質問なんですが、１と２の事業なんですが、セミナーと相談事業、カウンセリングみたいな感じなんですけれども、ここに行政として、「品川区結婚サポート事業」ということで冠を打ってやるわけですけれども、どこまで区が事業の内容というか、かかわるのかなというか。それとどう違うのかなというのをお伺いしたいと思います。","respondent":"小野区民課長","answer":"セミナーについても、セミナーの中の企画であるとか、そういうものについては、これは民間のノウハウの中でやっていただくということが基本だと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"今回あえて結婚サポートということで始めるということなので、今まで民間、オーネットではやっていなかったような結婚セミナーとカウンセリングをやるのかなというところがわからないというか。前やっていたかどうかというのは、どう違うんだというのがちょっとよくわからないんです。","respondent":"小野区民課長","answer":"こういうふうなことをできるだけ敷居を低くして提供することによって、今までなかなか踏み出せなかったという方については、こういう結婚ということについて、自分で一歩踏み出していただく。そのためのバックアップをしたいというのが行政の考え方です。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"区として、３番目の事業の位置づけというんですか、どう考えているのかということをお伺いしたいのと、あと、広報などでこれからこういう事業を、確かに結婚ができなくて悩んでいる人は多いので、こういう事業自体は否定するものではありませんけれども、これから広報するわけですけれども、３番目のところは理解を得られるのかなというのが不安なんですけれども。","respondent":"小野区民課長","answer":"したがって、例えば今回予定をしていますチラシや何かを作成いたしますけれども、このチラシの中に３番目の事業の案内は入っておりません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。オーネットの側から言うと、すごく、お墨付きもあるし、品川区も安心のブランドも得て、非常にプラスになることが多いと思うんですけれども。オーネットにとってはすごくいいことであるというふうに思うんですけれども、民間のノウハウを活用して、品川区としてはその対価といいますか、何ていうんですか、そこまでして利益があるという考えで今回の事業を進めているということなんですか。","respondent":"小野区民課長","answer":"区の利益は、当然区民の方がこの事業によって結婚に一歩踏み出せる何かのきっかけをつかんで、そういう方向に行くという、これが区の利益です。区民の方がこれを使って、できれば結婚まで進んでほしいです。","id":"exchange-007"}]},{"id":"topic-02","title":"のウェルカムセンター原「地域活動・交流拠点」","agenda":"のウェルカムセンター原「地域活動・交流拠点」","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それと、名称のこととかは、まだ仮称ですけれども、どういった形になるのか、方向性を教えてください。","respondent":"中山地域活動課長","answer":"３０日ですので、運営協議会のほうでも準備に入って、協定のありようについて検討に入っておりますが、ウェルカムセンター原の交流施設運営協議会というほとんど仮称に近い名称になる予定です。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"１点なんですが、防災のほうでちょっと教えていただきたいんですが、災害時の防災機能の強化ということで、この地域の、このウェルカムセンター原と伊藤学園と、両方、防災機能が強化されると思うので、この地域全体としては防災機能がさらに上がると思うんです。備蓄なんかも増やしたりしますけれども、その辺のところを、強化する内容について教えていただきたいんですけれども。","respondent":"中山地域活動課長","answer":"基本的な、まず、整備での体制強化のところですけれども、図にありますように、改めて敷地内の防災倉庫をきちんと設ける予定です。今まで、図面の黄色で囲っている左のずっと下の部分に、「防災倉庫設備スペース」と書いた隣のところにあろうかと思います。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"心配なのが、一部の方に過重な負担がかかって、結果としてなかなか継続的に運営できなくなるんじゃないか、そういう事態がちょっと心配だなというのがあるんですけれども、それには事務局の態勢がかぎなんじゃないかなとは思っているんですが、すみません、ちょっと私も勉強不足で申しわけないんですが、検討部会からという検討部会というのは何なのかというのと、あと。","respondent":"中山地域活動課長","answer":"実際の運営もなるべく地元の方を中心にお願いしたいということでお話しする中で、お二人の方については専念できる、専従できるという形でお話をいただいておりますので、事務局のほうに従事していただくという形を考えておりますけれども、実際に例えば経理に関すること。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"１,７００万円余という、大体その内訳についてですか、もしわかれば。","respondent":"中山地域活動課長","answer":"残りの約８００万円程度になると思いますが、これが事務局あるいは、実際には有償のボランティアによる受付であるとか、事業の協力もお願いしようと考えていますので、そういうものも含めたいわゆる人件費的なものが約８００万円と、こういうふうになっております。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"端的にお答えいただきたいと思います。ハードとソフト、両方ごちゃ混ぜになりますが、グラウンドの使用時間、午前９時から午後７時ということで、当初幼保一体等の関係から、もうちょっと日程的には制限されるというふうに、予算特別委員会だったかな、お話を伺ったので、ここの詳しい意味を。同時に、グラウンドのサーフェイスというんでしょうか、どういう状態になるのかも一つお聞きしたいなと思います。","respondent":"中山地域活動課長、斉藤防災安全担当課長","answer":"平日については基本的には利用の予定が、今度、学校ではありませんので空いてきますから、この辺はまたルールを具体的に決めてというふうに考えておりますけれども、午前、午後、夕方はどうしても、本格的な照明ができないものですから。防災の関係について、私のほうから説明させていだたきます。今現在、こちら側の建物につきましては、地域防災計画におきまして学校避難所というふう位置づけになっております。約８００名からの避難所ということになっております。","id":"exchange-012"},{"speaker":"若林委員","kind":"確認","question":"漏れがあります。機能的に確認をさせてください。要するに、いわゆる通常の学校避難所と、強化を図るということなのでアップするのか、それとも。もう一つ、役員の人件費について、もう一言お願いします。","respondent":"斉藤防災安全担当課長、中山地域活動課長","answer":"さらには建物の耐震化ということになろうかと思います。役員会を開いたときの人件費というものについては予定してはおりません。基本的には無償というふうに考えております。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"それは土日は優先されるということなんですけれども、例えば平日空いているときとかにテニスがやりたいとかいう方が仮にいらっしゃるとした場合、ここはもともと学校だったので、そういう設備等はあったと思うんですが、そのような、例えばポールが立てられるよとか、そういうのは全部準備してあるよとか、ある程度住民の方々のニーズにこたえられるような。","respondent":"中山地域活動課長","answer":"それで、テニスなどをやる場合のポール等ですが、想定としては、体育館もそうですけれども、一定のスポーツ、今例示があったテニスなんかもできるようなポール、あるいはネット等の設備等についても考えていきたいと予定しております。","id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問","question":"そこの地域のほうが例えば優先になるよということになっているのか、それとも、ある面、全区的に視野を持っていくのかということになってくるんですけれども。今、時給の話があったんですけれども、いわゆる休みだとか、そういうことがどういうふうになっているのか。役員会は当然夜ということになると思うんですけれども、そういうときの事務局の方々の扱いというのはどういうふうになっているんでしょうか。","respondent":"中山地域活動課長","answer":"具体的な施設の使い方のルールですけれども、大井第三地域センター管内を特に優先という予定は今のところございませんが、やはり区民と区民以外の利用については料金等を分けていくという案を基本に考えているところです。","id":"exchange-015"},{"speaker":"宮崎副委員長","kind":"確認","question":"そういうところなんかも、会長のところの判断になってくるのかということを確認しておきたいのと、あと、大井第三地区のいわゆる優先的使用ということじゃないんだということなんだけれども、実態としてはそうなるんじゃないかという、そんな説明だったかと思うんですけれども、例えば広報紙の発行で、地域ニーズの調査というふうになっているんですけれども、そうすると、全区民を対象に考えるとなると。","respondent":"中山地域活動課長","answer":"確かに雇用形態としては会長の任用というふうになりますけれども、実務的に町会長がそういうことに対応するのは難しゅうありますので、ご質問にもありますように、実際には地域センターも含め、あるいは区のＯＢの職員も入れますから、区と地域団体との話の中で。","id":"exchange-016"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"初めてなので、とりあえずやってみて、私どももいろいろ見ていきたいなと思いますけれども。先ほども話したんですけれども、今町会の方々、非常に仕事が多くて大変だという声もありますので、ぜひ、そこら辺の声ですね、非常に配慮していただいて、無理のないようにしていただきたいなというふうに思います。これは要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"の「平成２０年度品川区民まつりの予定について」","agenda":"の「平成２０年度品川区民まつりの予定について」","exchanges":[{"speaker":"稲川委員","kind":"質問・要望","question":"この区民まつり、毎年毎年やられていて、非常に私、地域の結束力とかをつけるのにはすごいすばらしい、これはずっと続けていただきたいという思いの中で質問させていただきたいんですが、質問１点なんですけれども、これをやるに当たって、さっと見ると、荏原地区に関して、全体がそうなのかもしれないですけれども、以前、土日やっていたところがあると思うんです。なぜそうなったのか。","respondent":"中山地域活動課長","answer":"たまたま、昨年は、選挙の関係で、会場が急きょ変わったりしたようなところは、今までやっていなかったところということで、目の前のマンションの方から何事だというふうな苦情が運営委員のほうに寄せられているのを、私も、それはちょうど行ったときにあって。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"みんな、地域のため、子どもたちのためということで、その地域地域でこういった区民まつりをやるわけですから、苦情とか逆に来ちゃうと、そこの担当の人たちのモチベーションが下がるというわけじゃないですけれども、だんだん、だんだん勢いがなくなってきちゃうんじゃないかなというのを僕は危惧して、話はそれてしまうけれども、救急車が出るときの音もうるさいという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎クラブというところなんですけれども、冊子にもありますけれども、東京２１ｃクラブを参考にしたということなんですが、もう少し施設、事業のかかわりとかで、どういうものなのか、もう少し説明していただきたいのと、冊子の３ページのところで、「ものづくり産業の現状」というところで、「三極的構造が際立つ」ということで、中堅・大手の業務機能の集中、ファブレス企業の台頭、小規模下請工場群。","respondent":"金子産業振興課長","answer":"こういった形態につきましては今後も踏襲して、大手企業のご意見を伺いつつ、また中小企業のご意見等を伺いながら、どちらもそれぞれ発展していけるような、それで品川区のものづくり産業が発展していけるような、そういった方向で検討を進めたいと思っているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"２点目の件なんですが、現時点での中小企業に対する、ものづくり企業に対するこの事業のどういう支援につながるのかという、現時点の認識で構わないんですけれども、区としての考え方のようなものは。","respondent":"金子産業振興課長","answer":"先ほどちょっと申し上げましたとおり、まだまだ、具体的な計画というのはこれから詰めていくので、非常に茫漠としたものがありますけれども、少なくともさまざまな情報交換の交流の拠点という中に、例えば大手企業しか入れなくて。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問","question":"あるいは、そのつくったものを検査していく、そういう施設というのがどういうふうになるのかなと思うんですけれども、これは、必要性のところで、大手メーカーのというようなところからの質問になっているんですけれども、内容はこれからという話なんですけれども、そういう中小企業の試作品だとか、あるいは検査機器の設置なんかも当然考えていくということになっているんでしょうか。","respondent":"金子産業振興課長","answer":"今後の検討によるというふうには考えております。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"わかりました。そういうところ、逆に切っていくというふうにするのかどうかというのは、企業の生き方になっていくと思うんです。本来であるともっと企業自身がそういう開発だとか、研究、試作品というのは、もっとそういう視野を持っていただいて、もっと力を入れてやっていく必要があるんじゃないかと思うんですけれども、いわゆる自治体の絡みというんですか、どこら辺までやるのか。","respondent":"金子産業振興課長","answer":"例えば賃料をその地域の相場に対して１００％でいくのか、７０％でいくのか、そういったことも今後の検討になりますので、そういう意味では１００％支援しないというわけではありませんけれども、何らかの形で、支援施設もどこまで支援していくかというのは。","id":"exchange-023"}]},{"id":"topic-04","title":"の「八都県市地球温暖化防止キャンペーンについて」","agenda":"の「八都県市地球温暖化防止キャンペーンについて」","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"国のほうでは「クールアース・デー」というふうに、６月９日の福田総理の記者会見、それから１７日の対策推進本部で正式決定をしたという報道を見たんですが、国のクールアース・デーとこの八都県市のキャンペーンの関係性を教えていただきたいと思います。それ以外の施設についての周知徹底といいますか、キャンペーンの呼びかけ、協力行動としてどういうふうにされるのか、以上お聞きします。","respondent":"工藤環境課長","answer":"その部分で、うちもそれに連動しまして、臨海部の野球場、テニスコートという形で連動したわけです。来年度以降どういった形でやるのかというのは、今後検討させていただきたいというふうに考えております。","id":"exchange-024"},{"speaker":"若林委員","kind":"確認","question":"答えが出ていないんですが、総合庁舎、中小企業センター以外の、多分地域センターとかというのを全体的に教えてほしいのと、確認で、2)のほうは、今まで利用予約のない施設の９時以降とか８時以降というのは消灯していなかったんですかということを。","respondent":"工藤環境課長","answer":"来年度以降は、どういうふうな形になるのかというのは今後検討したいというふうに思っております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"区としても呼応していくということなんですが、これ、区民とか事業者への呼びかけの仕方、内容にもかかわってくるのかなと思うんですけれども、区としてはこのキャンペーンというのはどういうふうに、意義というか、もちろん純粋に、電気が消えれば電力が軽減され、ＣＯ２の排出が瞬間的には抑えられるというのはありますけれども、どういうふうに区としてはこの事業の意義をとらえて、呼応したというふうに。","respondent":"工藤環境課長","answer":"区としてのこの事業をどのように認識したかですけれども、このキャンペーン、やはりライトアップに慣れた私ども、区民、事業者、一人ひとりに対して、日ごろからいかに照明をしているかというものを実感していただくということと。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"事業者に対してこのキャンペーンというのはどのような効果をねらうというか、教えてください。","respondent":"工藤環境課長","answer":"事業者に対しましても、当然さまざまな部門で、事業部門、環境部門といろいろとあるわけですね。そういった中で、それぞれのやれる範囲でこういった部分を啓発するということで、十分効果があるものだというふうに思っております。","id":"exchange-027"},{"speaker":"若林委員","kind":"意見","question":"１件だけ。環境のうち、地球温暖化について、担当課長だったと思いますが、東京都でお話を聞く機会がありまして、北九州市の地球温暖化、環境も含めまして、先進的に取り組まれているというお話を聞きましたので、意見として出します。ある意味では東京都が一番今先行しているのかなと思いますが、具体的な事実として北九州市では取り組んでいるという具体的な事例がありましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"若林委員","kind":"意見","question":"改めて日程表を見まして、例年、私たち会派として、都市問題会議、研修に行っておりまして、できれば１日ぐらい平日が、月曜日があるとありがたいなということだけ申し上げておきたいと思います。正副のほうでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"安藤委員","kind":"意見","question":"別に、今の調査項目が、ばあっとみんな上がっているというのであれば、また話は別なんですけれども、先に２泊３日ありきというふうにとらえ、区民の皆さんからもそういうふうに見えるんじゃないかと思うので、そこは柔軟に、この時点でそれが先にあるんだというふうにはならないんじゃないかなというような意見を持っているんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"若林委員","kind":"提案","question":"私も、東京もある意味では先進的と申し上げたのは、今回のＣＯ２削減のいわゆる対策をこれから具体的に進めていきましょうということが、環境建設委員会のほうで全会一致で可決されたということを指したまでであって、具体的に事業者に対してとか、また行政として、もう既に取り組んでいるということを、北九州市に関して指摘しましたので、間違いのないようにということと、また、２泊３日については。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"本多委員","kind":"意見","question":"行政視察につきまして、正副案というものを尊重したいと思いまして、あえて先ほど出しませんでしたが、基本的には所管事務調査の項目が決まりましたので、そういったものを充実していくんだろうなと思って、あえて発言は控えていたんですが、そういったところを委員会として充実させていくべきだと思います。行き先の都市、自治体ですとか、その日数については、正副委員長にお任せしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"の「所管質問について」","agenda":"の「所管質問について」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"福祉の後退政策だと思うんですね。そういった意味で、区としての現状、さっき言ったような健保の扶養家族の方について、現状を把握する必要があるんじゃないかと。健保の扶養家族の健診を国保とかに委託することも可能とされていると伺ったんですけれども、そういったさっきの現状を把握した上で、そうした対応をとる考えというのはあるのかどうかというのをちょっと聞きたいなと思いました。","respondent":"本城国保年金課長","answer":"１つは、各医療保険者、健康保険等ですが、そちらが特定の医療機関を指定して、そこに委託して実施する方法もありますが、そうしますといろいろな医療機関に個々に契約しなければいけないということになりまして。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"集合契約という話が、そういう手法があるんだという話で、ちょっと難しい話だったんですが、どれぐらいにめどが。もう少し後というのは、どれぐらいにめどがつくのかなと考えているのかということと、あと、難しいかもしれないですけれども、実際、実態把握という点ではどうですかね。","respondent":"本城国保年金課長","answer":"今、ご質問いただいた件ですが、基本的には、国保の立場からのお答えになってしまいますけれども、前段のどれぐらいかかるかということについては、今私どもとしては東京都の保険者協議会というところで場を持ちまして、保険者間の最終的な集合契約の調整をしているということで。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"その前段で、扶養者に限ったことと今理解をしているんですが、健診の通知の仕方というのは、要するに扶養者本人に直接されるのか、世帯主、健保側の加入者を通じてお知らせが行くのかというか、そこら辺を教えていただきたいと思います。","respondent":"本城国保年金課長","answer":"扶養者の関係の通知の仕方ですが、それにつきましては、専ら各医療保険者のほうで対応しているということになりますので、それぞれ千幾かある医療保険者、それぞれということだと思います。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"医師会側のいわゆる人員的なもの、いわゆる国保の特定健診以外に、ほかの保険者の中の扶養者も新たに加わってくるということでしょうから、それだけ人数が増えるわけですね。そこら辺、どのぐらい予想されて、医師会にできなくなるような負担といいますか、ということの医師会側の反応があれば、教えてください。","respondent":"本城国保年金課長","answer":"今、医師会側と代表保険者側との詳細のやりとり自体、私ども直にかかわっていないものですから、詳細は把握しているところではございませんが、そういった事務的なものも、確かにプラスでは出てくるんですが、ただ。","id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"この問題になるといつも質問したくなるんですけれども、１つ、今の区民健診と内容は同じにしましたということなんですけれども、とりあえず内容が同じというのはそれでいいんですけれども、やはり内容の充実といいますか、そういう点でどういうふうに考えているのかというのを１つ伺いたいのと、もう一つは、やはり今回特定健診あるいは保険指導、受診率や実施率がこういうふうに決まって。","respondent":"本城国保年金課長","answer":"それと、あと、これから目標達成に向けての方策につきましては種々あるかとは思いますが、先日も話題になったかと思うんですが、まずは、今回始まりました特定健診の大切さについてＰＲしていくとともに、指導自体、充実していくということが肝要だと考えているところです。","id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"質問","question":"受診率のところで、先ほど社会保険の家族の問題の質問があったんですが、受診率のほうでは、母数に社会保険の家族、こちらのほうはどういうふうに。入っているんでしょうか、入っていないんでしょうか。","respondent":"本城国保年金課長","answer":"あくまでも国保のほうの換算でいえば、社保の被扶養者はまたそちら側の対象になりますので、国保のほうにはカウントされていません。","id":"exchange-038"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"社会保険のほう、家族が入ってくる、入ってこないというのもありますけれども、少なくとも今時点では、現在の、平成２０年度３５％実施が行くかどうかというところなので、１年ごと５％、１０％アップというのは非常に大きなハードルだというふうに思うので、そこのところは考えられる対応をしっかりやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうのがもしあれば求めたいというのと、あと、以上のような関係から、「建築紛争予防条例」による説明会を行いますということで、そういう答弁があったんですが、いつ開催される予定なのかというのを具体的に聞きたいのと、あと、対象となる、「建築紛争予防条例」による説明会ですと、建物の高さ掛ける２倍の半径なので、あまり対象者がいないんじゃないかというふうに思うんですけれども。","respondent":"秋山資源循環推進課長","answer":"生活環境に関する内容を説明ということですけれども、内容につきましては、大気、騒音、振動等について、一般廃棄物の処理施設の基準に基づいて説明をしようと、各種の項目について説明をするということになっております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後の件なんですが、私も、いや、これ、２つの施設がつくられる。寝屋川市ですか。もう一つは、４市が共同で運営する。都内の、都民の食の安全全体にもかかわってくるぐらいの勢いなんじゃないかなと思うんですけれども、そこ、不十分なままでゴーサインを出すのは非常によくないんじゃないかと思うので、少なくともそういったことをＪＲに求める必要があると思うんですが、いかがですか。","respondent":"秋山資源循環推進課長","answer":"先ほども申しましたけれども、今回の施設、「紛争予防条例」と、あと建築基準法の関係ということで、近隣住民、１００ｍ範囲の方に説明をするということで、法令ないしは条例の基準にのっとって説明会を行っておりますので、それ以外、それ以外と申しましょうか。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう姿勢だと、安全が保たれないんじゃないかなというふうにすごく思うんですけれども。別に品川区だけのことを考えていればいいというわけじゃ、もちろん考えではないでしょうし、もちろん、しかも、青果市場なわけですから、品川区民としたって、そこから物を買うわけですよね。だから、近隣にそういう施設がある中で、ＪＲにそういうことも求めないというのはちょっと理解できないんですけれども。","respondent":"秋山資源循環推進課長","answer":"それで、ＪＲに関しましても、全く説明会等何も説明をしなくてもいいというようなことをこちらが話したわけでもありませんし、今後も求めがあれば窓口をつくり、ＪＲのほうで適切に対応をとるようにということは、こちらのほうではお話しをしている。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"今、安藤委員のほうは、週刊誌の記事をもって、私、その内容、詳細わかりませんので、その部分については議論には加われないんですが、そこと同じだとか、同じでないとかいうところが、今、課長、理事者の中で答えられるのかどうかというのを一つ確認させていただきたいのと、さきの本質論である安全性ということについて、現状どういうふうに取り組まれているのかというのをまずはっきりさせないと。","respondent":"久保田環境清掃事業部長","answer":"それで、大田市場なんですけれども、大田市場については、あそこの場所から３５０ｍ離れているということで、その間に公園なんかも挟んでいますし、そういう点でいけば、かなり離れているので、直接的な影響はほとんどないだろうと私どもは判断していますので。","id":"exchange-043"},{"speaker":"若林委員","kind":"意見","question":"今のお話はよくわかりました。今の議論の中で払拭できていないのが、寝屋川市の問題です。委員の主張では同じなのだと。いずれにしても、八潮から大田市場の方々にという質疑がありましたので、安心感をもっていただいたほうがいいんじゃないかと思う。","respondent":"久保田環境清掃事業部長","answer":"したがって、これについては、当然今の、私どもが今ＪＲで予定しているああいう圧縮梱包の施設とは全く違うような環境条件が出ていますし、それについては、インターネットの情報だけで恐縮なんですけれども、安全は確保しているという施設長の主張ではあります。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"それを元にしているわけですから、それで、インターネットでも今情報がすぐわかるような状況なので、寝屋川市ですか、そこでこれだけの大きな問題になっているというのを踏まえて、なおかつ、ただの施設だったら、まあ、いいんですけれども、食料品の施設が近隣に、３５０ｍといったら全然、すぐ、近いと思いますけれどもね、私は。ですから、そこはよく調べる必要があるんじゃないかと。","respondent":"久保田環境清掃事業部長","answer":"先ほどから雑誌を元にしていろいろご主張があるんですけれども、私どももそれが正しいかどうかというのはなかなか確認できないので、発言を控えさせていただいているわけなんです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"今回のような容器包装をリサイクルする過程で、やはりプラスチック自体が不安定な物質が混ざっていて、しかもそこに添加剤もいっぱい入っているやつを圧縮する過程でいろいろな、未知数な部分、わからない、未解明な部分でいろいろ影響が、どんな影響が出るかわからないという面もあるわけで、だから、リサイクルはリデュース、リユース、リサイクルなわけであって、リサイクル万能というだけにとらえて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/487097?Template=document&Id=2522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":55985,"voices":139}},{"id":"h20-20080624-7","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"厚生委員会","time":"午前１０時０４分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"請願のところなんですけれども、昨日もかなり重い方の請願が出ていましたけれども、この方もかなり重度な方だと思うんですけれども、昨日、こういった重度で区内の方は７名いらっしゃるということだったんですけれども、その中に含まれていたお子さんはどういう状態なのか、把握をされていらっしゃるところなのか、個人的なことはいいんですが、それをまずお伺いします。","respondent":"高橋障害者福祉課長","answer":"昨日申し上げたのは、重度で人工呼吸器をつけている方ということなので、現在、この方についてはつけておりませんので、対象には入っておりません。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目なんですけれども、ご説明をいただいたところによると、在宅で常時、車いすの外出支援ということでは、これは成人の方という要件ととらえていいんでしょうか。その点と、あと車いす以外は全くこの要件に入っていないのか。この方の場合は別途ストレッチャーの使用に広げていただきたいということなので、その辺については、今までこういった例は全くないのかどうか、その辺を聞かせてください。","respondent":"高橋障害者福祉課長","answer":"車いすにもいろいろありますが、基本的には車いすとして、一般的に車いすと言われているものについては対象になっていますので、ストレッチャーと言われちゃうと、この部分については対象外になりますが、リクライニング式の車いすであれば車いすという扱いですので。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"この場合はベッドとはっきり書いてあるので、多分車いすの範疇では間に合わない方なのかなと思うんですけれども、先ほどはストレッチャーに関してはリフトつきの寝台タクシーのご利用をということだったんですけれども、なかなかそういうふうになってしまうと、例えば病院に行くときに利用しにくい、予約が取れなかったりとか、この辺で購入と改造の費用を。","respondent":"高橋障害者福祉課長","answer":"実際上、車を購入するとなりますと、一応車を購入し、それを１度陸運局に通して、その後、改造を通して、またそこのところで陸運局のところということで特殊車両として認められるので、相当の時間と手間がかかるのと、お金がかかるということなので、現在については。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"こういうお子さんは日ごろのお医者さんの管理のもとでないと予防注射なんかも受けられないと思うんですが、その辺はどうなんでしょうか。","respondent":"山岡健康課長","answer":"ただまれなケースで、例外的にそういう医療機関がないとは言えないと思いますけれども、そのケースについては、個別にご相談に応じるということになろうかと思います。めったにないケースだと思います。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"現状において行われているのか、あとインフルエンザなんかは６５歳以上の方だけなんですけれども、多分体の弱い方というのは、ちょっとした病気でも重篤になったりということにおいては、受けられる予防注射は事前に病気を予防するという意味ですごく大事だと思うので、こういった難病を抱えていらっしゃる方なんかは、一般のお子さんよりももっと枠を拡大して受けられる対象が広がってほしいなと思いますが。","respondent":"山岡健康課長","answer":"一律に考えるのは難しいかなと思っているところです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろな手当を先ほどご説明いただいたんですけれども、この辺で所得制限のことについてお伺いしたいんですが、先ほど区と都と国の制度の説明をしていただいたんですけれども、これは全部所得制限がついていたんでしたっけ。なので、制度はあるけれども受けられない人がいるという認識を持っているんですが、どの程度の方が先ほどの制度を受けられているのか、割合的にはどうなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"ほとんどのところが３６０万円、障害児福祉手当も３６０万円、区のほうの障害者福祉手当の３６０万円程度です。それから特別児童扶養手当については、扶養がなければ４５９万６,０００円、児童育成手当については３６０万円という形になっております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害の重い方のお世話というのは、家族の方に結構重くのしかかっていて、多分ここのご家庭も、１人でつきっきりで生活を支えていらっしゃると思うんですね。横浜市というところで他にもと書いてあるんですけれども、お伺いしたいんですが、この横浜市のこととか他都市のことで把握をしていらっしゃるところがありましたら、教えていただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"横浜市と書いておりますが、神奈川県ということで調べさせていただいたところ、横浜市の場合は年額６万円出ております。それと県のところでも年額６万円ということで、東京都が対象者の部分、それから金額の部分につきましても、かなりよろしいのではないかと考えています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味では、明らかに障害があって援助が必要なのに、手帳を得られなかったりとかいろいろなことでその先に進まなくて、受けられないまま亡くなってしまうケースもあると伺ったんですね。そういった面では、わかっている障害だったら速やかに手続をする必要があると思うんですけれども、その辺はいかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"手当のところですが、神奈川県よりかなりいいという金額ですが、これはあくまでも東京都が条例で行っているものなので、東京都の手帳のあるなしにかかわらずですので、申請を出して、東京都の心身障害者福祉センターが診断した上で交付しているものですので。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問","question":"請願の１１号のほう、車いすの自動車の関係で何点か伺いたいと思います。このケースの場合も踏まえ、現状の、確かに２台だったと思うんですが、頻度と台数を考えて、今、こういうケースの方が病院に通院等で利用する際にいっぱいであるとか、あるいはすぐ利用がほぼできるというか、その辺の見通しを伺わせてください。","respondent":"高橋障害者福祉課長","answer":"改造というのは、車いすが乗せられるように、自分の所有している車を改造するのに１５万円まで出していますので、３０万円と１５万円の金額の助成金となっておりますので、見積もりがそれより以下だったらどうだとかというようなことでは。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"幾つか質問させていただきたいと思います。先ほど飯沼委員のほうからもあったんですけれども、車いすがよくてストレッチャーはだめだという理由がどうしてもわからないんですね。質問からいきましょう。車いすの改造あるいは購入の助成、今、年間何件ぐらい利用がありますか。","respondent":"高橋障害者福祉課長","answer":"実際上の改造ですが、購入の補助金ですが、平成１７年度につきましては、両方で４件、平成１８年度につきましては２件、平成１９年度については１件を助成しております。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"私はこれは車いす同様、金額が車いすへの助成額と同じぐらいの割合で出せるかどうかは別として、やはりストレッチャーも外出援助の１つとして助成の対象に加えるのが、自然な発想ではないかと思います。２つ目なんですけれども、ちょっと確認させていただきたいんですけれども、区独自の助成であるおたふく風邪と水ぼうそう、これについては区外の指定機関でも助成が受けられるということでしょうか。","respondent":"山岡健康課長","answer":"これは品川区の独自の助成ですので、基本的には品川区内の医療機関でやっていただきます。ほかのところで受けた場合についての仕組みというのは、現状のところではございません。","id":"exchange-011"},{"speaker":"阿部委員","kind":"意見","question":"この公費の部分、つまりＢＣＧからポリオまでの予防接種というのは、まさにこれは国民全体、子どもたちが皆受けることで公衆衛生を維持している部分もありますので、これは区外の医療機関でも当然受けられるべきである。にもかかわらず、例えばこの方がそのことを知らないまま来られてしまったことに１つ大きな問題があると思います。つまりこの上４つについては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問・要望","question":"請願の４つが既に公費負担されるということを、この方が重度であることが区で把握する機会はいくらでもあったはずなのに、その情報が１度もこの方のところに届かなかったということなんですね。あるいは逆に区としては、重度のお子さんの場合にはどのようなサービスをし得るのか、まとめて保護者の方に説明する機会があるのかないのか、現状を教えていただきたいと思います。","respondent":"山岡健康課長","answer":"予防接種のご案内についてだけまずご答弁申し上げますと、それぞれの時期に、難病の方であろうとなかろうと、対象になるお子さんすべてに通知を差し上げているところです。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"確かにそうだと思います。重たい状況の子どもは必ずしもその時期までに注射が可能になるとは限りません。逆にどうしても区内で受けろというとそれは危険なことになってしまうわけで、主治医の判断で受けるというのが当然のことだと思いますが、それだと助成の利益が受けられないというのは、こういう特殊な状況にある子どもにとっては酷なことではないかと思いますが、その辺の考えはいかがですか。","respondent":"山岡健康課長","answer":"ございませんけれども、特殊事情がありますれば、ご相談いただければ、例えば何らかの方法で助成をするということは可能かと思われますので、一たん自費で受けていただいて、後で償還払いといったような方法もありますので、その辺はご相談いただければと考えております。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"であれば、重度の子どもたちがいるとわかった時点で、予防接種もこういう扱いができますよと区のほうから情報提供するような、これは予防接種だけじゃないと思います。重度の子なら仕組みに乗らない部分というのが幾つも項目があると思いますので、一覧表をつくっておけば、それで説明すれば１回ですべてのことが済むわけですから、そういったやり方もあるかと思います。一応一言お願いします。","respondent":"山岡健康課長","answer":"今のご意見を参考にしながら、個々の通知等については考えていきたいと考えています。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"５万円ですね。これはすぐにというわけにはいかないかもしれませんけれども、所得制限を区として見直しをする可能性があるのかどうかというのがまず１点です。自治体によっては１歳未満でも手帳を取れた例があると聞いておりますが、基本的には国の問題、都の問題であるということは認識しているんですけれども、区として、この年齢についてもう少し問題意識を持てないか、その辺のお考えをお伺いします。","respondent":"高橋障害者福祉課長","answer":"手帳を１歳未満でも取れた方もほかにはあると聞いているということなんですが、手帳そのものの申請につきましては、先ほども申し上げたとおり、区としてそれを受け付けないとかということではございませんので、申請があれば必ず東京都のほうに送付し。","id":"exchange-016"},{"speaker":"阿部委員","kind":"意見","question":"所得制限については撤廃しろというお話をしたのではなくて、もう少し上限を緩和できないかということでお話をさせていただきました。手帳については、区で判断できないというのは重々承知しておりますので、ただいろいろな機会のときに、都に問題意識を投げかけることはできないかという意味です。","respondent":"高橋障害者福祉課長","answer":"先ほどの所得制限の緩和につきましても、この基準を設けましていろいろなところを運営していますので、独自に緩和するということは現時点では考えることは難しいかと思います。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"この改造につきましても、車いすを常用で利用している方だけということなんですけれども、例えばこのリフト寝台つき福祉タクシーを通院で使うとか、またたまにはどこか違う景色でも子どもに見せようかとか、いろいろな使い方があると思うんですけれども、このタクシーの用途と、あとはこちらのリフトつきの車いすの購入・改造費、助成されておりますけれども、こちらのほうの用途と。","respondent":"高橋障害者福祉課長","answer":"車いすの助成のところの利用の目的、それからストレッチャーを使用したリフト寝台つきタクシーの目的は特に制限しておりませんので、使い道についてはそれぞれの利用の方が判断してご利用の申し込みをしていると思います。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"用途に対しては制限がないということで伺いました。それと手当拡充についてですけれども、こちらは陳情第１３号になりますけれども、所得制限の話も出ました。手帳につきましては都の制度ということで、これは区としては淡々とやるというお話だったと思いますけれども、これについても何かしらの要望といったらおかしいんですけれども、全く出せないのかどうか、この点を１点だけお伺いいたします。","respondent":"高橋障害者福祉課長","answer":"この東京都の基準につきましては、厚生労働省、それから都道府県は同一に行っているもので、機会があれば発言しますけれども、今のところそういう発言する機会はございませんので、その時点で、もしいろいろな条件緩和ということになれば発言はしたいと思いますが。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"確認","question":"陳情の部分からいきます。陳情第１４号については東京都の範囲ということで、区の判断は難しいのかなと。障害者手当の申請条件緩和は確かに厳しいなという状況はわかりましたけれども、手当拡充に関しての確認なんですけれども、先ほど所得制限が３６０万円という数字が出たんですけれども、これは３６０万円は手取り、それとも例えば住民税の基準とか、そこら辺をちょっと確認したい。","respondent":"高橋障害者福祉課長","answer":"あくまでも所得ですので、収入金額ではございませんで、いろいろなものを全部控除した上での所得ということになりますので、その辺については、この基準表をいろいろなもの、基礎年金も含めまして。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、３６０万円じゃなくて、もっと実際はお手元には増えていると判断をしているということでよろしいですね。請願の件に関してですけれども、逆にリフトつき寝台タクシーの利用度が非常に低いなという話になってしまう。利用料はそっくりそのまま払うということなんですか。","respondent":"高橋障害者福祉課長","answer":"それとタクシーの利用件数ですが、年間で２,６５７件を利用しているもので、寝台のみで申し上げたのが３人から９人ということになりますが、そのほかに車いすのみで利用している方もおりますので、その辺についてはプラスしていただければと考えております。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"利用件数はこの事務事業には１,７５９件と出ているから、その数字からちょっと今、お聞きしたんだけれども、ちょっと数字が、全体がちょっと疑問もあったんだけれども。","respondent":"高橋障害者福祉課長","answer":"中古車でこういう車いすが乗る車は、流通しているかどうかというのは、申しわけないんですが、私はつかんでおりませんので。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ある程度意見のほうにもなるんだけれども、この請願、陳情がどこまで一般的な話かなというのを非常に感じているんですね。個人の請願なのか、それとも全体的な制度を変えてくれという請願なのか、ちょっとその辺が非常につかみにくい状況だと私どもは判断しているんですけれども、ちょっとその辺も踏まえて、これは意見で終わりますけれども、質問ではないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"堺委員","kind":"確認","question":"これについての利用実績の中で、先ほども鈴木真澄委員からご指摘がありましたような事務事業概要に、確かに平成１７年、平成１８年、平成１９年の利用件数と実績が出ていたんですが、先ほどある方のご質問に対する答弁では、現在、このリフト寝台つき福祉タクシーの利用は、月平均すると大体３人から９人ですよということだったかなと思うんですが。","respondent":"高橋障害者福祉課長","answer":"それと手帳のところにつきましては、確認ということかと思いますが、あくまでも手帳につきましては、指定医が判断した上で私どもが東京都のほうに経由事務としまして申請し、東京都が判定医により判定した段階で手帳が交付されるですので。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"所得制限がないのが一番いいんでしょうけれども、ただ先ほどのご説明でいくと、平均すると重度の方が大体１４万６３０円交付されているようなんですけれども、こういう障害をお持ちの方から見ると、目に見えない経費というんでしょうかね、医療費については難病ですから、裏のほうに東京都が実施している難病治療の医療費助成制度（小児慢性疾患）は存在しているがということで。","respondent":"高橋障害者福祉課長","answer":"いろいろなところで医療にかかわるものについてのいろいろな薬品とか医療品というのがありますが、医者が必要ということになれば、今、子どもすこやか医療費助成の中で可能かと思いますので、その辺については、どういうものが必要かどうかというのは私のほうは判断できませんが。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この手当の所得制限の、特に配偶者や扶養義務者の所得制限の緩和というのは本当に必要だと思うんですけれども、それと同時に、この方の場合はちょっとわかりませんけれども、このさまざまな手当とかも含めての制度を知らないために受けられないということはないのかと、先ほどの予防接種のこともありましたけれども、そこのところをちょっと心配しているところなんですけれども。","respondent":"高橋障害者福祉課長","answer":"お知らせの部分ですが、手帳申請時に一覧表がございまして、その中で一つ一つにご本人に説明をさせていただいている状況であります。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"手帳申請時に説明をしていただく、このしおりもそのときに全員に渡されて、ご覧くださいということでお渡しされていると思うんですけれども、これってなかなか一般の人がばっと見てもわかりにくいということもありますので、保健師さんもずっとかかわられているということもあると思いますので、そこら辺のところが、受けられる制度が受けられないということがないというところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"請願第１１号についてなんですけれども、さっき聞き落とした点もあってちょっと失敗したんですけれども、非常に難しい判断をしています。今回、結論を出したほうがいいのか。ですから、継続が自民党としての考え方と思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問","question":"請願第１１号については、判断が非常に。この2)の予防接種ですかね。区外であっても指定医ならばできるんだということなので、ただこの請願者の方はその辺の情報を知り得なかったからこういうふうに出されてきたのかなと思いますので、その辺の周知徹底については、区側のほうにもご努力をお願いしたいなと意見を申し上げておきたいと思います。ですから、この請願は分けていいんでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"阿部委員","kind":"意見","question":"方向性としては賛成なんですけれども、いろいろと重要な問題を含んでいると思いますので、もう少ししつこく話をしたいと考えていますので、そういう意味で今回は継続で、もう１回やりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"陳情第１３号につきましては、先ほど所得制限の緩和という質問が随分出たんですけれども、本件に対しては、拡充に関して、これは新設ですよね。陳情１４号につきましては、これは東京都の事務ということで、現状、区のほうで対応する部分ではないということで、これも願意に沿いがたいということで、両方とも不採択という答です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"堺委員","kind":"質問・要望","question":"陳情第１４号につきましては、これは東京都の事業であるということから、区がどうこうするものではないかもしれませんが、区として都のほうに意見を上げられる際には、何らかの形で制度がよくなることについてはまた改善点があれば、ご意見として申し上げていただきたいなと思いますが、まず１点、３歳未満の方でも、先ほど答弁いただきましたように、手帳の交付については可能性がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"意見","question":"陳情２件ですけれども、今日は３つの請願、陳情が出されましたけれども、この全部をとらえたところで、重度の方の障害児・者の方々の実態をもっとしっかりとつかんで、トータルでの支援の充実が必要であると深く受けとめました。ぜひ趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問・要望","question":"そこに現場があるからそこに生の声があって、そこから制度をつくっていくのが基本であるということを考えますと、都の制度だから、国の制度だから区は物を言いませんというのではなくて、現場の声こそ制度の改善に生かしてほしいと、常にそういうパイプというのをむしろ区のほうで場を見つけて、区の中で実際に福祉の現場で矛盾を感じたところは、どんどん都にも国にも言っていく姿勢。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問・要望","question":"幾つかお伺いします。第７号といいますか、最初のなんですけれども、産業振興課のホームページが利用可能である。ただし広告扱いで有料ということだったんですけれども、大体どのくらいのものなんですか。普通に広告を出すぐらいの金額になるのか、それとももう少し安いのかなと。その金額を教えていただきたいと思います。技術支援教育訓練給付金事業、こっちのほうの実績を教えていただければと思います。","respondent":"諸岡児童課長","answer":"３番目の自立支援給付金の実績ですが、平成１９年度の支給実績で申し上げますと、これは申し込みと支給が、受講期間がありますので若干タイムラグがございまして、ホームヘルパーの２級を受けられた方が２名ですね。","id":"exchange-035"},{"speaker":"阿部委員","kind":"確認","question":"今の支給実績なんでけれども、支給年度で構いませんので、人数で何人なのかなかというのが、平成１９年、１８年ぐらいで、今、人数を言われなかったのは１人ということなんでしょうか。数字で確認させていただければと思います。どうなんでしょうか。","respondent":"諸岡児童課長","answer":"自立支援給付金事業実績ですが、平成１９年度は５名です。この制度は平成１７年度から開始されておりますが、平成１７年度は制度開始ということで、まだＰＲも十分ではないということで少かったんですが、だんだん周知されてきまして増えてきております。","id":"exchange-036"},{"speaker":"阿部委員","kind":"意見","question":"就業アドバイスについては、個別の状況を勘案してということで、そのことをぜひ強化していただければと思います。それから最初に聞き忘れました、実数を正確につかむことは実は意外に困難と聞いているんですけれども、区内に今、ひとり親家庭はどのくらいいらっしゃるのか、その中で計１０人の利用というのをどのように評価されているかということをお聞かせください。","respondent":"諸岡児童課長","answer":"実際やってみたいけれども、いざやるとなると、いろいろな事情があってちょっと躊躇してしまうのかなということもあります。ただ、だんだん増えてきている傾向でございまして、これは今後も十分ＰＲをしながら、丁寧な窓口対応も含めて進めてまいりたいと考えています。","id":"exchange-037"},{"speaker":"阿部委員","kind":"質問・要望","question":"国の制度ですので、根幹をどうこうということは難しいかと思うんですけれども、今、ＰＲともおっしゃっておりましたが、ぜひ事業の促進に努めていただきたいと思います。１個聞き落としておりました。ご本人のご希望で、あいているほうがいいとか、しめているほうがいいとか、そのようなことというのは、形の上ではできるかなと思うんですが、そういうお考えはありますか。","respondent":"志村生活福祉課長","answer":"これは非常に特異な例です。ですから、逆に言うと、あそこで面接をしなきゃだめなのよというわけでもありませんので、それはお申し出いただければそのような配慮というか、一定のできる範囲のことはしていきたいなと考えております。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"別に外に面して風を入れる窓ではなくて、ドアに見通せるような小窓をつけるという考え方です。伝わっていましたでしょうか。要は第三者の視線が入り得る構造にするということです。ドアのところですね。","respondent":"志村生活福祉課長","answer":"ちょっとこの辺が逆に言うと不十分じゃないかというケースもあります。声が聞こえちゃうということもあるんですけれども、この辺が許容の範囲かなと思ってやっておりますので、あとは個別の対応をさせていただきたいと思います。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問・要望","question":"４点の項目に共通して伺いたいと思います。ちょっと確認で伺います。そういった中では、これまでこういったやりとりが個別であったのかどうか、おそらくそこまで把握は難しいかと思うんですが、何回か引き続きやりとりをして、どうしてもという中での陳情項目なのか、ちょっとその点を確認したいのが１つあります。","respondent":"諸岡児童課長","answer":"実際にご相談があったかどうかにつきまして、相談の秘密ということもございまして、個人情報ですので、私ども相談があればきちんと相談記録に基づき記録をしていますが、それについてはちょっとご容赦いただきたいと考えています。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺において、ここにはいろいろ書いてあるんですけれども、就職活動からもう一歩進んで、働く応援的なところで何か求められていると思うので、この辺何か工夫はないのかなと思うのが１つと、２点目のところは、事業助成金制度というのはないけれども、事業開始資金のご紹介があったんですが、無利子で貸すというこの制度がどのくらい活用されているのか、３年くらいの間の利用状況を教えてほしいのと。","respondent":"諸岡児童課長","answer":"それから最後の会計士とか税理士の顧問料の一部負担ということになりますと、なかなかひとり親の支援という面からはしづらいといいますか、さまざまなひとり親については母子手当と言われるような児童扶養手当とか、経済的な支援をしてきておりますので。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目のところの事業開始資金が平成１９年に１件、額的にはかなり大きな額でこういうのが受けられたら、仕事を始める意味ですごい助かると思うんですが、この件数がなかなかいっていないというあたりがどういうところなのかなというのを聞かせていただきたいのと、あと陳情第８号のほうにいきますけれども、これの最初のほうに、さっきご答弁の中に、陳情第８号のところは国の制度で。","respondent":"諸岡児童課長","answer":"そのようなきめ細かな対応を行わせていただいているところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"陳情第９号のほうにいきますけれども、まず１点目のところは、先ほどここに書かれているようなことはありませんというご答弁があったんですが、なかなかやりとりのところはデリケートなところがあると思うんですけれども、ここにも誤解印象を受けたためと書かれているので、誤解を招かない対応をしていただきたいなと、これはなかなかやりとりの問題で難しいと思っていますけれども。","respondent":"諸岡児童課長","answer":"制度的には、就職をしない場合は受け付けできないということはございません。ただ、アドバイスの中にそのような受け取られ方をしたのかなと考えています。その辺の言い方につきましては、私ども今後十分注意していきたいなと考えています。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"よろしくお願いします。この２と３のところにいろいろ細かく書かれているんですけれども、先ほどもすごく件数が多いとか、いろいろご説明いただいたんですが、わかりやすい載せ方というか、例えば事例か何かを幾つか載せるとか、その辺の工夫をしていただくことで、理解がもうちょっと進むというあたりがあるんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"諸岡児童課長","answer":"なかなか数が多くて、１,９００機関の５,８００講座、しかもこの講座が日々動いておりまして、ご承知のように、大手の英会話学校が経営破綻に陥りまして、そういったことでこの指定講座を受けていたのも一切指定取り消しになったりとか、あるいは新たに指定をされた講座。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなんですけれども、過去の実績というか、こういうのがこれだけ活用されていますという件数を出すこと自体は困難ですか。支給されているわかりやすい事例をこうやって載せるというのは、それほど困難ではないような気がするんですが、いかがでしょうか。","respondent":"諸岡児童課長","answer":"ただ、やはり窓口での十分な説明をするということが基本かなと考えています。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"その後に調査をする。そこについてここでおっしゃっているのではないかなと思うので、原則的には申請者が見えたら申請書を書くという、その行為をきちんと受けとめていかなくてはいけないなと思うんですが、よくこの間、聞くと、相談件数と、多分カウントされているのは来ていろいろお話を伺った相談件数、その中で何件申請になったのかというのを、ちょっと具体的にそこも含めてお伺いしたいと思うんですね。","respondent":"志村生活福祉課長","answer":"先ほど申し上げたとおり、年間で２,０００件ほどの相談といいますか、記録に残っているのがこれだけです。その中でといいますか、平成１９年度、生活保護の開始になった者が５３１件です。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"セーフティーネットというご説明もさっきありましたけれども、ぎりぎりのところに行って、拒否をしていないのかもしれないけれども、そういう受けとめをしてしまうという、そういったぎりぎりの状況の中であそこの窓口に来るんだというあたりを、職員の方は重々、わかっているとは思うんですけれども、そこは本当にしっかりと受けとめてほしいなと思うのと、それから。","respondent":"志村生活福祉課長","answer":"職員の研修ですけれども、一番身近なところでは、実は明日と明後日、これは別にこの委員会があるから予定したわけではありませんが、実は明日、明後日は、私どもの全課職員、７１名ですけれども、対象に、２日間にわたりまして、防災シアターをお借りして。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実はの話を聞くまでが大変と、本当にいろいろな方が相談に見えるので、その中から相談の本質、真実を見つけ出すのはすごく大変で、ご苦労されていらっしゃると思うんですが、研修のところにぜひ力を入れていただきたいなと思うのと、最後に１つだけ、２のところに職員の方は加筆修正が容易な鉛筆でと、この鉛筆で相談内容が書かれていることがあるのかどうか、もしあるとしたら、やはりこれはボールペンとか。","respondent":"志村生活福祉課長","answer":"それに基づいて、先ほど申し上げたとおり、年１回の東京都の指導検査、それから国あるいは会計検査院等の検査には、その公文書を出して検査を受けてまいりますので、そのようなご心配はないと、先ほど申し上げたのはこの内容です。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今までの質疑の中でもその説明とそんなに変わらない答ばかりが出ているような気がしていますので、全体的な聞き方をしますけれども、このケースの陳情に対して、この方も個別に陳情を出していらっしゃるんですけれども、全体的に、例えば母子家庭の方から同じようなご相談事というのは、かなり役所にはあるんですか。それともこんなケースはレアケースだよという、どちらで判断したらいいのか。","respondent":"諸岡児童課長","answer":"今回の陳情のようなご意見はほとんど初めてお受けするようなことですね。私どもこれを聞きまして、これからさらに工夫していかなければならない点もあるかと思いますけれども、今回につきましては、この陳情については、今までたび重ねてあったようなご意見ではないです。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ひとり親だから認めるよという問題ではないなと私は、これは意見のほうです。例えばその下に行っても、事業助成制度、助成を個人にしていくのは、ひとり親家庭に対する本当の支援なのかというのも非常に疑問を感じています。もうこれ以上質問ということではなくて、ある程度自分の意見も、この全体をまとめていくでしょうから、意見ということで述べさせてもらいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらの第１号と、あと陳情第１０号のすべての項目もそうなんですけれども、先ほど飯沼委員も言われました研修ということについては、ぜひともある意味では重点的に進めていただきたいのと、それともう１つなんですけれども、この研修の中ではビデオを見るというような、ある意味では一方通行のままだと思うんですけれども、例えばある人が生活相談に来たという前提のもとで。","respondent":"諸岡児童課長","answer":"それを受けていただいて、それにパスして、入校が決まった段階で訓練手当の説明をして受給していただくという形になっていると聞いております。なお、母子家庭の方には母子家庭の優先枠などもあると聞いておりますので、まずは相談です。","id":"exchange-051"},{"speaker":"堺委員","kind":"意見","question":"この件につきましては、今、自民党の鈴木委員がおっしゃっておられましたように、今日結論を出すということで、採決方法については４件一括ではなくて、それぞれ個別に出すべきだろうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"意見","question":"個別に言います。全体的にこの方のおっしゃっている内容は、母子家庭ということでお１人で大変だということは十分承知した上での答ですが、もう１件、第１０号のほうの生活保護制度につきましても、理事者の説明を聞いておりまして、十分対応なさっているという点を考えると、この陳情項目につきましては、もう既に対応している部分ということで、不採択ということでいきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目については、助成金制度、貸付金ではないということですが、おっしゃっている意味合いも理解できないでもないんですが、基本的に事務事業概要等を見ましても、母子家庭等の資金の融資あっ旋というんでしょうか。申請が可能である資格の種類など、今以上に明確に公開、説明、記載を求めるとおっしゃっておられますが、さっき５,８００件ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"陳情第１０号に関しては、特にイのところで、まず申請を受け付けるという、職員の方は一生懸命やってくださっていることは承知の上なんですが、仕組みのところで、まずしっかりと申請書を希望する人にはすぐ書けるという状況をつくっていただいて、それから詳しく中に入るというところは、前から私たちもお願いしているところなので、特にこの辺の改善を求めたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただこの３つ、陳情第７号、第８号、第９号に関しましては、それぞれの陳情事項につきましては、ちょっとどうかなと思うものもあるんですけれども、そこに共通しているのは、結局はひとり親家庭の方のそれぞれの能力に応じて就職をするように道をつけてもらい、また、それぞれの能力を伸ばしてもらえるような制度を整えてほしい、そういう思いから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"阿部委員","kind":"質問・要望","question":"ですので、この相談を受けるときに、できるだけ早い段階で、これだけのことはこちらからも聞いていくんだということをお伝えしてわかってもらうということをしつつ、相談をしていくということも必要ではないかと、そういったことも含めて実施していただきたいという思いを込めて、この陳情については願意に沿いがたいという形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"ちょっと頭の中で整理できていなくて、教えてください。これは精神障害者の通所施設も入るんですか。精神障害者の通所施設というのはあるんでしたっけ。それが対象に入っているかどうか教えてください。","respondent":"高橋障害者福祉課長","answer":"精神障害者の通所施設は区内にありません。現在あるかもめ工房のことだと思うんですが、共同作業所ということで、現在、交通費等につきましては個別に出ております。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが受けられていて、今回新しく制度になったとき、不利益になる人がいないのかどうか、ちょっとその辺を教えてください。","respondent":"高橋障害者福祉課長","answer":"区内通所の人数が３１２人おります。一般の区分が入っているのが１９７人、低所得に生活保護までを含めますと１１５人という区分割合になりまして、今度世帯の変更になりますと個人単位となります。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"９割のところはわかりました。でも結構障害を持っていらっしゃる方でこの９割通うのは、通わないとこの３,０００円はいただけないということですよね。障害者本人の方を対象にということで、やっとこうなったなと思うんですけれども、その後の括弧のところがわからないんですけれども、本人と同一世帯の配偶者の所得で判断ということは、結婚をしていらっしゃる方は夫婦でという理解でいいんでしょうか。","respondent":"高橋障害者福祉課長","answer":"1)の部分につきましては、ご本人と配偶者ということで、ご夫婦の場合は２人の部分となります。","id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この利用料なんですけれども、全員が低所得者になるということで、１,５００円になるということなんですけれども、そうすると、今までは利用者実費負担が最大で、低所得者の場合は７５０円から１,５００円になるということでいいんでしょうか。","respondent":"高橋障害者福祉課長","answer":"予算額につきましては、あくまでも負担軽減の中の施策の１つと考えていますので、そこの中で十分充当できると考えております。全体の予算額ですと１,８００万円ちょっとをうちのほうでこの予算額を見込んでおりますので、その中で十分やりくりできるのかなと考えております。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"知的の方は欠席があまりないということなんですけれども、知的障害者の更生施設のほうは結構大変なんじゃないかという話もお聞きしたんですけれども、ここら辺のところで体調を崩して行けなかったりするとこの３,０００円が出ないということが、その体調を崩しやすい子どもさんにとって、この９割というのがかなり本人の状況からすると厳しいということがあるんじゃないかなという気がするんですけれども。","respondent":"高橋障害者福祉課長","answer":"利用料につきましては、その人の出勤の状況に応じて違うので、３,０００円を補助して上限まで使えば７５０円ということになりますが、それ以下の方もおりますので、その辺についてはその人個人の計算をしないとちょっとわかりませんので。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ただそれが９割以上行けば、逆にさらに３,０００円が支援金として出るので、９割以上行った方については、差し引き負担としては逆にプラスになるというところになるけれども、９割行かない方は、今までは最大７５０円で済んでいたものが１,５００円になるということで、そういう理解でいいんでしょうかということなんです。","respondent":"高橋障害者福祉課長","answer":"委員のおっしゃるとおり、そういうことになります。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと頑張って９割行けるという方は、そして頑張って９割出ている方というのもすごくたくさんいらっしゃると思うんですけれども、障害の程度に合わせて、行けないという場合があった場合は出ないというところは、またちょっとその障害の方に合わせた対応をぜひ検討していただけたらということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-03","title":"の５、その他を議題に供します。 (1) 所管質問","agenda":"の５、その他を議題に供します。 (1) 所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園の待機児童の解消にあたって、ご答弁の中で具体的に公・私立の保育園数と解消人数の数字が述べられていたので、ぜひその中身を具体化されている部分において具体的にお知らせいただきたいのと、今、長期計画が検討中なんですけれども、中期的な、また短期的なこの待機児解消の計画がどのように進んで、どこを見たらそれがわかるのかというのも教えていただきたいと思います。","respondent":"小林保育課長","answer":"今、予定しておりますのは、既にご報告いたしましたが、今年度１２月を目途に学研の認定子ども園を五反田に開所し、おおむね６０人強という形で予定しておりますほか、ウエルカムセンター原の私立認可保育園、そして、今後は平成２２年。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"４つの計画が示されましたけれども、今年１０月の学研の認定子ども園というのは、これは認可保育園、認可幼稚園ですか。中身的にこれは、くくり方をちょっと教えてください。","respondent":"小林保育課長","answer":"学研の認定子ども園につきましては、保育園型の施設になります。したがいまして、基礎となりますところは認可保育園を取得すると同時に、認定子ども園の認証を受ける形になります。","id":"exchange-066"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"本年の調査項目の要望ですが、１つ目が発達障害者の支援に関係すること、２つ目に小規模多機能型の介護事業所、この２点を要望し、また、今、品川区の方策の中で、区民との協働という点から、ＮＰＯ法人等が運営されているケース等の先進的な事例という点で、テーマに上げていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"具体的に申し上げてよろしいですか。今のところ以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"浅野委員","kind":"意見","question":"最近、自殺が増えているというか、そういう報道もある中で、１つの要因としましては、複雑な社会の中で精神障害を患うというようなケースがあると思うんですけれども、そういう精神的な疾患に関して取り組んでいるような施設とか、そういうものがあれば、ぜひとも過程、やり方とか、そういうのを含めて見学できれば、視察できればと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/481603?Template=document&Id=3208#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":59779,"voices":183}},{"id":"h20-20080624-8","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"建設委員会","time":"午前１０時０２分～午後１時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"質問","question":"工事の期間というところと、あと１点、以前に水上バスのコースがしながわ水族館のほうがなくなるような新聞記事があったんですけれども、そのことについて、何か情報があれば、もう終わっているのか、ちょっとその辺もよくわからないんですが、その辺のことがおわかりなら教えてください。","respondent":"藤田道路公園課長","answer":"水上バスの関係なんですけれども、委員会の昨年度の仕切りが、水とみどりのネットワークの関係が街づくり特別委員会の所管でございましたので、街づくり特別委員会のほうで報告をしてございまして、９月いっぱいで、今運営を行っています東京都観光汽船のほうが。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"それで、このしながわ水族館の利用の見込みとか、区としてはどのような把握をされているんでしょうか、９月から変わったとすると。","respondent":"藤田道路公園課長","answer":"そうした中で、水上バスについては民間事業者が営業が成り立たないということで撤退するわけですから、ほかの形でほかの企業者が参加できるようなこと、これは非常に難しいと考えていますけれども、私ども水族館を所管する部署としては。","id":"exchange-002"},{"speaker":"井上委員","kind":"意見","question":"今回の営業利益の中でこういったコーナーを設置するということで、集客するには少しいろいろなものを変えていかなければいけないということだと思うんですが、この先の５年、１０年、１５年というのは、大がかりな改築をしながら進めてきたところで、どういうふうな展望を持っているかということで、毎年こういう形で、新しいものというのは、区と水族館とどのような協議のもとに進めていかれるのか、また。","respondent":"藤田道路公園課長","answer":"これもやはり、どうしても施設をつくればそのときには集客が増える、それから減る、それの繰り返しですので、これから５年ペースがいいのか、あるいは６年７年のペースがいいのか、その辺はあるとは思っておりますけれども、いろいろな形で水族館のほうと。","id":"exchange-003"},{"speaker":"三上委員","kind":"意見","question":"名前は忘れたけれども、日本海のほうで増えるクラゲがあるね。要するに、そういうのもいるなら連れてきて、こういうものだというのは、これは話題になるわけでしょう。だけれども、現物、こういう水族館でもこういうものですよという展示というのがあっても、私はいいと思うんだけれども。そういう工夫というのがあってもいいと思うんだけれども。大き過ぎて持ってこれないというのかどうか。","respondent":"藤田道路公園課長","answer":"食とのつながりの話、今ございましたけれども、私ども水族館のほうにも、生体、体がこんなことになっていますよとかいう記載だけでなく、例えば特別の企画展示なんかのときには「食と魚たち」みたいな、そういった企画展示等も行うことで。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ聞いておきたいんですが、今さっき井上委員も言った、単年度の営業利益のところで、入館料については区とサンシャインで７対３に分けるというような話を聞いていますけれども、館内でサンシャインによる営業利益、販売利益がありますが、その辺との関係で、今回のような施設をつくる上でかかる経費とサンシャイン側の単年度の営業利益というのはどういう配分というか。","respondent":"藤田道路公園課長","answer":"それで、今回大規模改修というのは、そのかかる経費の中で必要な部分のお金というような形で計上させていただいて、改修工事を行っていくというものです。ですから、改修工事を行った後で収益があった部分を７対３で区と水族館で分配をするという形になってあります。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"勘違いしていました。ということは、品川区としても、形式としては出していますよという形式になるわけですね。そうすると、今回のこの費用というのは幾らかかることになるんですか。","respondent":"藤田道路公園課長","answer":"おおむね１,８００万円ほどになる予定です。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、こういう夏休み中の展示だとかというのは、私もあまり意識をしていなかったんだけれども、大体その程度を常に、こういった期間中にはかけている、これまでもかけているととらえていいのですか。","respondent":"藤田道路公園課長","answer":"それとは別の、今回のクラゲ展示コーナーを設けるというのは、常設の展示コーナーですので、そのために１,８００万円の工事費をかけて、常設の展示コーナーをつくるというものです。企画展示はまた別な営業スタイルで行っているものです。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"「明かりをかえる」というところの、一斉行動の選定地区において電球形蛍光灯の配布とありますが、これをもうちょっと詳しく、どういうところが選定地区になっているのかというようなことと、あともう一つは、裏面の消灯についてなんですけれども、予約のない施設の消灯ということで、７月７日に限ってということですが、そのことについて、これはイベントに対する協力行動だと思うんですけれども。","respondent":"藤田道路公園課長","answer":"施設の関係ですけれども、区の私どもの野球場、当然ＣＯ２削減とか環境負荷という観点からもものを考えなければいけないとは思ってありますが、一方ではスポーツの振興だとか、健康増進とか、そういった観点もあります。","id":"exchange-008"},{"speaker":"井上委員","kind":"意見","question":"蛍光灯の配布という選定地区で、こういったところの費用とかいうのはどういう関係で、この配布ということなので、お金が出るというところでは、八都県市がそういう関係でやっていこうとしているのか、その予算的なものがどういうものなのかということと、今の裏面の話ですけれども、スポーツ振興という、照明の話で予約のないときに今後どういうふうにするかというところで。","respondent":"藤田道路公園課長","answer":"入っているということは、８時半にはもう１回ここの場所については点灯開始をします。ほかの施設については、普段も７時以降入っていなければ消していますし、今回も消したままになるということです。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"品川区は積極的にこのキャンペーンに協力していくというところはわかります。実際区内の企業について、直接的な所管ではないのかもしれないですけれども、せっかく報告があったので、区内企業に対して働きかけというのはどういう状況ですか。","respondent":"藤田道路公園課長","answer":"済みません、細かい説明をしておりませんでしたけれども、裏面のほうの品川区の協力行動ということで、2)が区民・事業者の呼びかけということで、広報しながわの７月１日号、区のホームページ。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"東京都の条例改正が決まるみたいですよね、ＣＯ２問題で。今日のニュースを見ると、義務化の対象ということで年間１,５００kl以上の原油と都市ガスのエネルギーを消費する事業者ということですけれども、こういう対象というのは、当然品川区でも区内にある企業としてつかんでおられると思うんですが、そういうところへの直接的な働きかけというのは、区としては行っていないということなんですか。","respondent":"藤田道路公園課長","answer":"ただ、まだ条例が動いているわけではございませんので、その中で私どもが所管部署に確認する中では、協力のお願いを広く呼びかけていくというふうに、今のところ聞いてあります。今回の７月７日に向けてはそういう活動だというふうに聞いてあります。","id":"exchange-011"},{"speaker":"三上委員","kind":"質問","question":"古い話だけれども、平成３年のときに区議団の中から北朝鮮に行きました。そうなると、やはりこの明かりを、明かりを、となっているけれども、明かりも大事だが、それこそもう少し夕方になったら皆さん自宅の周辺に水をまいて、それで少しでも風を呼び起こすような仕組みに取り組みながら、エアコンも全部消してみたらどうでしょうかと。その辺どうでしょうか。","respondent":"岩田まちづくり事業部長","answer":"一方で、企業活動もそうなんですけれども、簡単に企業活動を一時停止しなさいと言えば、確かに数量的には排出量は減るかもしれませんけれども、企業活動が低下すれば国民生活が低下するということですから、いわゆる今の企業活動や国民生活を維持しながら。","id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点お伺いしたいんですが、これは一時的に豪雨時に貯留するための施設だと思うんですけれども、ここに水を貯めた後に、その水を出さなければいけないと思うんですが、その出すことに関してどこにも記述がないんですけれども、例えばポンプ式なのか、ちょっと詳しくないのであれなんですが、例えばポンプ式だとして、ポンプ所的なものというのはどの辺にできるのかなというのがわからないんですけれども。","respondent":"家壽田下水道河川課長","answer":"これは今委員のおっしゃったポンプというのは、次回以降の工事の中で発注契約をするものでございまして、実際には三ツ木公園につくります立坑が、これは将来人孔という形でマンホールになる予定です。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"シールド工事の基準が変更されるということで、今回はシールド工事の契約については次回に回すというお話であります。ちょっとそのシールド工事の基準の変更というのはどういうところにあるのかお聞かせ願えますか。","respondent":"家壽田下水道河川課長","answer":"しかしながら、今後維持管理をしていくときに耐久性を考えますと、雨水とはいえ下水がまざっていますと、やはり構造物を腐食させるおそれがあるということで、この腐食に対応する構造をとるべきだというようなことになりまして、防食性といいますか。","id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、これまでつくってきたこの関連の工事についても、同じことが言えるということになると思うんですけれども。その辺はどういう、もう完成してしまったものを含めて、どういういじり方をしていくのかわからない。","respondent":"家壽田下水道河川課長","answer":"従来つくりました構造につきましては、その腐食性を見込んでいないものですから、もし腐食した場合にはコンクリートの層もぼろぼろになってしまう。こうなりますと、鉄筋にまで至ってしまいますと構造が破壊されてしまうということになります。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"ではもう一つ、そうすると、当然維持管理するために調査をするという、定期検査みたいなものが当然あるんでしょうけれども、今のお話でいうと、当然腐食をしてくるであろうという期間というのは想定されているんですよね、きっと。そのときに今お話をしていた新しい基準でもって補修をしていくという考え方になるんですか。そこをもう少し。","respondent":"家壽田下水道河川課長","answer":"そういったものも１つのきっかけになってあります。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"きのう現地で説明を受けたときに、平成１１年、平成１４年、平成１６年に水害があったということで、その当時からの取り組みとして、こういう大がかりな工事をする前に、雨水浸透ますの設置の、品川区は独自でもその予算はとっている、ほかの自治体ではなくしたにもかかわらず品川区はとっているわけなんですが、その辺の設置は、働きかけはしているのは十分承知しているんですが、どれぐらいの実績。","respondent":"家壽田下水道河川課長、松代管理工事課長","answer":"実際問題、浸水被害が多数発生したときには１０件近い申請があったりもしましたけれども、なかなか進んでいないのが実情で、我々としても、今これを増やす努力をいろいろ検討しているところです。それ以外のところでもできる限り浸透させるという方向を道路改修工事の際にはやってあります。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"そういったものの誘導策みたいなもの、ただ助成があるということではなく、そういう形で進めていくということは、区としてはどうでしょうか。","respondent":"家壽田下水道河川課長","answer":"ですが、やっぱり浸透は非常に重要なことだと考えておりますので、この辺の課題も含めて、担当課長とも連携しながら浸透促進施策を推進していきたいという考えです。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問・要望","question":"きのうちょっと出ました公園の件なんですけれども、今回この工事が終わった後に、地元の声で変えていく、復旧というか、同じような現状維持を考えているのか、ほとんど改修という、そういう視点で考えているのかということをちょっとお伺いしたいと思うんですが、西大井にある大井第三地域センターですか、あのわきにある公園にちょっと久しぶりに行ったら、とてもびっくりするぐらい変わってしまって。","respondent":"松代管理工事課長","answer":"今後、そういった形でよりよい形の魅力ある、多くの方が使っていただけるような公園づくりというものを、そのようなケースバイケースでその公園にふさわしい、地域の方々と一緒につくっていくような形、そういったものを今後進めていきたいと、そのように考えております。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"公園についてはいろいろと主観があるかと思うんですが、せっかくですので、今の西の森公園についてはどのように評価をされているのか、ちょっとお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"地域センター側も下がり、公園側も下がって、４ｍ道路がそこにできました。そういった中で、道路も空間になりましたので、おっしゃったように中にありました滑り台とか砂場があって、使っていただいたんですが、その形態が少し変わりました。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺も資料提供というところで、そういう公園との関係とか、今後それはどういうふうに地元の人たちもここがどういうふうになるのということも問われることもあるので、資料提供としてもう少し親切な図が、全体で出されたものというようなところで、特に別につくってくださいということではないので、そういう資料提供について、もう少し親切なものをいただきたいと思うんですが、その辺はいかがでしょうか。","respondent":"家壽田下水道河川課長、岩田まちづくり事業部長、松澤委員長","answer":"今回の委員会に報告するというのは、あくまでも立坑工事をするということが目的でして、公園復旧ということであれば。ただ、今回の場合は全面封鎖で工事を行いますので、そういう意味でお付けしなかったということで。他にないようですので、本件を終了いたします。この中央大学はなにかと申しますと、立会川、去年浄化実験を行いまして成功したということで、浄化の対策を本格的に実施するんですが。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問・要望","question":"立会川の浄化は、近隣の皆さんにとっていえば大変長い間の願いで、いろいろなこと、手だてを区のほうでとってきていただいたんですけれども、立会川については河口部分からの運河の部分が浄化をされないと、なかなかどんな手だてをとっても難しいというような話もこれまで聞いてきたんですが、今回のこの高濃度酸素溶解水ですか、これでどの程度を見込んでおられるのかを、実際にこれまでの施策との関係で。","respondent":"家壽田下水道河川課長","answer":"これを昨年実施しましたところ、夏の間というのは雨が降りますと、また下水から汚れがどんどん流れてきまして、瞬間的には川がまた貧酸素状態になる場合もあるんですが、常に酸素を送り続けておりますと、かなり高度なものを送っておりますので。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"合流式の下水であふれると、確かに汚物が流れ出す。それは確かですよね。ただ、その場合というのは、本当に大雨が降ってあふれて森ヶ崎での処理ができなくなる状況の中で生まれる、まれなのかどうかわからないですけれども、年に何回かあるかという状況だと思います。その辺をちょっと。","respondent":"家壽田下水道河川課長","answer":"この勝島ポンプ所ですが、今は東京都からは平成２３年度完成予定と聞いています。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"平成２３年度よりも、私はもう少し早いように聞いていたんだけれども、いずれにしても、実質的には勝島ポンプ所の始動と、せっかくああやって第二立会川幹線ができて、汚水そのものが立会川を通らずに済むような形式の運営をより一層早く推し進めるようにしていただきたいなというふうにお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"藤原副委員長","kind":"質問・要望","question":"買い取ったのかリースかお伺いしようと思ったんですけれども、リースということで５年のリース代について教えていただきたいのと、それとこの装置を入れた流れを知りたいんですけれども、こういうのというのは、この装置をつくった会社が所管の課にこれだけいい実績がありますからという営業をかけてくるのか、それとも、ほかの自治体とかの実績等で、この装置がいいよみたいなことを聞いて。","respondent":"家壽田下水道河川課長","answer":"それを海水の混ざる川でできないかということを前任の課長が考えまして、会社を呼んでいろいろプレゼンテーションを受けた中で、これは効くかもしれないということでやってみたという経緯です。","id":"exchange-025"},{"speaker":"藤原副委員長","kind":"意見","question":"ここの所管で答えられる範囲でいいんですけれども、いろいろ調べてこの技術はいいよという形で、単独でこの会社にプレゼンテーションを受けるということですけれども、何社かという形で競争させるのではなくて、単独で所管が呼んで、この技術がいいからという形で決めてしまうというようにとれたんですけれども、その辺の説明をしていただけますか。","respondent":"家壽田下水道河川課長","answer":"ちょっと補足といいますか、説明が足りなかったんですが、単独の会社を呼びつけてここでと決めたわけではなくて、当然この場合はその前にプロポーザルという形で、こういった類似の企業、いろいろな企業がありますので、技術提案をさせた中で。","id":"exchange-026"},{"speaker":"三上委員","kind":"質問","question":"ちょっとわからないので教えてください。東京都施工分というところの1)のシールドトンネル工事と、それから首都高速道路施工分のシールドトンネル北行工事というのがありますが、これは要するに２つのシールドは別々の会社がやるという、そういう理解でいいんですか。","respondent":"梶都市計画課長","answer":"北行、いわゆるこちらの八潮のほうから目黒区へ行くほうについては首都高速道路のほうで行い、そしてこちらの大橋ジャンクションのほうから八潮方向に向かう部分については東京都のほうの施工分という形になってあります。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問・要望","question":"その線で２本掘るなら、両方とも発進は大井のほうから始まりますよ、終わりは大橋ですよという言い方だったらわかる。だから、説明がわかりにくいからこんな質問をしなければならなくなる。もうちょっとうまく説明していただきたい。そうでなくても首都高速と東京都で２つの工事を分けなければならないという話を説明するわけですから、わかりやすく工夫をお願いします。","respondent":"梶都市計画課長","answer":"申しわけございません。このシールドトンネル工事なんですけれども、両方とも掘り進んでいく場合、場所は発進のところから掘り進んでまいりまして、その工事、どこまで掘り進むかと申しますと、品川線の工事ではその到達の場所まで、両方掘り進んでいくという形です。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"東京都施工分の大井地区のトンネル工事、これは、首都高速道路は一切手を出さないという解釈でいいんですか。上下線ともに。そういう解釈でいいのかどうかということと、それからもう一つは、７月１１日の説明会資料配布というのは、これはどの範囲に配布されるのかということなんですが、それをお聞きします。","respondent":"梶都市計画課長","answer":"２点目のご質問でございまして、７月１１日に配布予定の工事説明会のお知らせなんですけれども、こちらの配布範囲につきましては、予定で、こちらの大井北工事箇所の半径５００ｍの範囲が原則でございまして、そちらと八潮の北側。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問・要望","question":"ここでは契約に入っていないので出されていないのもしれないですけれども、トンネルから抜けて地上へ上がっていく部分、湾岸線につながる部分ですかね。そこの施工というのは、一体どこが責任を持って、という形にするのか教えていただきたい。","respondent":"梶都市計画課長","answer":"そして工事説明会をお知らせしていただくものですけれども、今回大井北立坑の工事、あとトンネル工事につきましては、こちらのほうで７月２５日に説明会をするところですが、東京都に関しましては、これまでのさまざまな説明会。","id":"exchange-030"},{"speaker":"菊地委員","kind":"意見","question":"私は地域的にどこまで影響するのかというのが、例えば１日に残土が一体何台分のトラックで出て、どういうルートを通ってどこに運ばれていくのか、その辺がはっきりしないと、実際に影響が出る範囲というのが見えてこないんですけれども、その辺を、実際に残土はどういうふうに運ばれていくのか、一体どのぐらい出るのかということをお聞かせ願えますか。","respondent":"梶都市計画課長","answer":"ただいまの工事の残土関係の影響というところだと思うんですが、先ほどの地図の、大井北のところから反対へということですので、もちろんここの部分から残土のほうは排出されることになるわけなんですが、それに関しまして今聞いているところでお伝えすると。","id":"exchange-031"},{"speaker":"菊地委員","kind":"意見","question":"まだ確定しないという段階でこの１カ所に説明会を限定するという理由がさっぱりわからないんですけれども、実際今、さっき話しているようにすごく広範囲に影響するかもしれないのに、この１カ所に限定して説明会を開催するというのがどうしてなのかさっぱり、さらにわからない。","respondent":"岩田まちづくり事業部長","answer":"したがって、施工業者が決まれば自分のところのノウハウ、やり方によって工事計画というのを立てるわけです。それを東京都、あるいは首都高速道路なりが承認をし、その内容を地域の方に説明する。一般的には建築物であれば２Ｈの周りの方たちに工事の説明をする。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"部長が言われるように、まさに工事の説明なわけですよね。だから私が言っているんです。私はもっと広い範囲で説明会をやるべきだというふうに思いますので、それは意見として言っておきますけれども、これは地域全体の関心事でありますので、説明会を何度も開くということをやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"三上委員","kind":"意見","question":"今のことをはっきり言っておかないと。これ本契約の予定が６月２５日だということなんでしょう。契約もしていないのに、そんなに細かな話ができるわけはないでしょうという。ただここのところに決まるという今の予定でいますというだけの話でしょう。どうなのか。","respondent":"岩田まちづくり事業部長","answer":"それで１カ所だけとおっしゃいますけれども、工事説明会はその行われる現場の周辺が、やはり何といっても騒音なり、振動なり、車の出入りということで、何らかの影響をお受けになってしまうわけですから、半径５００ｍのところの方に声をかけていく。","id":"exchange-034"},{"speaker":"三上委員","kind":"質問","question":"まさに私はちゃんと聞いていたんですけど、今の質問、言われていることを聞いていると、そこらあたりを理解されていないから、もうちょっとはっきりと申し上げたほうがいいのではないかと。だから６月２５日に契約になったら、その後１カ月かけて準備をした上で説明会をやるんですと。だから１カ月かけると、そういうことになっているんだということと私は理解したんだけれども、それでいいんでしょう。","respondent":"岩田まちづくり事業部長","answer":"ご指摘のとおりです。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"今から契約してノウハウでということでは、今の現状ではわかりませんけれども、そういう意味で、八潮北というエリアについて影響があるところでは、行きにくいという立地条件があるので、そういうことも含めて、ぜひ区として必要があれば要請をしていただきたいというふうに思いますけれども、そのことについてどうですか。","respondent":"岩田まちづくり事業部長","answer":"本会議でもいろいろ質問が出ましたけれども、この間東京都が地域の住民の方、いろいろ不安を持っておられる方に対する対応の仕方を私どももずっと見てまいりました。","id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"ですから部長がおっしゃったことはわかるんですが、とりあえず１点だけちょっとお聞きしたいのは、区として区民に対して、というのは、区長は意見書を出していたり、議会でも上の当事者に対して出しておりますけれども、ちょっと部長の答弁の中で気になったのは、確かに一生懸命都もやっていらっしゃるのかもわかりませんけれども、前担当の方に関しては、私は東京都のほうの傍聴をしておりますので。","respondent":"岩田まちづくり事業部長","answer":"一方で個々の問題に関しては、やはり五反田を中心とした住地域の方たちが、排気ガスの集中化についてのご心配、これは区長も、そういう心配を持たれるのが当然だろう、したがって品川区としても、地域の方々にいろいろ誤解もあるので、まず工事の主旨から始めて。","id":"exchange-037"},{"speaker":"三上委員","kind":"質問","question":"トータル的な経費というのはどれぐらいかかったんですか。","respondent":"青木都市開発課長","answer":"映像装置が直接で６,０００万円弱、そのほかの経費全部含めまして、ほぼ１億１,６００万円ほどで、これは品川区の施設として品川区の工事で設置したものですけれども、大崎駅西口のまちづくり協議会という会員企業がいらっしゃいまして。","id":"exchange-038"},{"speaker":"三上委員","kind":"意見","question":"どちらにしても寄附をいただけないとなかなかこうはできないと。来年何とか完成してもらいたい武蔵小山もできればなと淡い期待を持っていたんですが。都市再生機構も入るという方針でありますので、そこらあたりはまたその時点でお願いしたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"菊地委員","kind":"意見","question":"前委員会で報告しているということで、ダブってしまうかもしれませんけれども、今課長の説明の中で、大崎エリアマネージメントの中で安定的な収益が出たら見直しますよという話がさっき出たけれども、何をどういうふうに見直すという話なのか。","respondent":"青木都市開発課長","answer":"先ほど申し上げましたけれども、電力料金についてもメーターの検針はずっと続けますけれども、当面初年度については品川区側の負担で運用を開始しましょうということで協定を締結しました。","id":"exchange-040"},{"speaker":"井上委員","kind":"意見","question":"今の使用料の算定になるでしょうというところで、算定がどのぐらいになるものなのかというところと、あと初年度の電力、初年度だけで途中からですけれども、今年度ということだと思うので、それがどのぐらい保証されているのかということと、あと企業広告とか、これからケーブルテレビなんかのところで契約をして放映をしていくということだと思うんですが。","respondent":"青木都市開発課長","answer":"それと、電力使用量については、これも年間想定ですけれども、７０万円ほどになるだろうというものになっています。これの月割分で、今年度３月３１日までについては、当面免除で運用を開始しようというものです。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"調整で定期的に会議という、その基準みたいなものは、区のほうとしては用意されているのかどうかということと、あとここの掲示の時間帯、何時から何時までの放映を予定されているのかということと、あと音声のことも何か前にもあったんですが、その辺アニメーションもつくられていることを今おっしゃったので、音声、音響はどのようになっているのかということを教えてください。","respondent":"青木都市開発課長","answer":"参考にしますのは、広報広聴課とも連携しまして、広報広聴課のほうでやっているノウハウを一定程度これに反映させたいということで進めております。それと、この映像の放映時間ですけれども、午前７時から午後９時までで、現在運用しております。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"１点、地域情報ボードのギャラリー・ボードで、ポスターとか旗みたいなものもあったと思うんですが、それについても、どんなものをつけるかということは、大崎エリアマネージメントにすべてお任せということなんでしょうか。","respondent":"青木都市開発課長","answer":"立ち上がりの段階で綿密に連絡会議を持っていますけれども、今回行政側がああしたほうがいい、こうしたほうがいいということは、あまり過度に関与するのはこのまちづくり、あるいはまちの運営というものの趣旨をたがえてしまうことになると思いますので。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問・要望","question":"これは要望になると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと区営住宅のところで聞きたいんですけれども、区営住宅の場合１３団地それぞれに登録者を置いて、今、やっていますよね。そういうものを累計して、世帯の人数に応じて募集をかけるみたいなやり方というのはできないんでしょうか。","respondent":"齋藤住宅課長","answer":"景気動向や、その年によって退去され、亡くなられる方の数によって変わりますので、今年度中に何戸という予測に基づいて公平というのはなかなかできないと思います。一番単純にできるのは、自分が住みたいところの住宅を選んでもらって、それで抽選するというのが一番だと。","id":"exchange-045"},{"speaker":"菊地委員","kind":"質問","question":"満足度というけれども、都営住宅に入りたい、区営住宅に入りたいという方たち、経済的にも大変な状況で応募をされるわけですから、満足度という点でいえば、とにかく区内どこかに入居できれば一番高い満足度のはずなんですよね。本当に１００％の満足度といえば、私は入れることだと思いますから。たとえどこであろうと、中延であろうと、東品川だろうと、とにかくいいから入りたいと。","respondent":"齋藤住宅課長","answer":"私は１階でなければ嫌だとか、ここでなければ嫌だとか、こういう方がいらっしゃいます。では、それは、なぜでしょうというところもありまして、要は機会をどうやってとらえるか、入れればそれでいいというのであれば、都営住宅を申し込まれるでしょうし、あるいは三多摩のほうに。","id":"exchange-046"},{"speaker":"石田（慎）委員","kind":"質問","question":"申込用紙の配布は７月１日から７月８日の１週間で、申し込みの締め切りというのは７月１４日でよろしいでしょうか。それと、あと平成１８年、平成１９年と２４戸、７戸、どれぐらいの倍率なのか、それをちょっと。","respondent":"齋藤住宅課長","answer":"郵送であれば消印７月１４日までと、こういうことです。申し込みの倍率ですが、平成１８年度は６９３人の方が申し込まれて入居が２４戸、平成１９年度は６３６人の方が申し込まれて、入居が７戸です。","id":"exchange-047"},{"speaker":"石田（慎）委員","kind":"質問","question":"これ７月８日から７月１４日まで、例えば７月１日のときに気づけばまあまあの期間があるのかなと思うんですけれども、７月８日ぎりぎりの時期に、例えばこんなのがあったんだと気づいたときに、７月１４日となると少し短い気もするんですが、そういったことは、例えば区民のほうから、もうちょっと長くしてというような声とかというのは上がっていないですか。","respondent":"齋藤住宅課長","answer":"基本的には応募したい方は期間については広報誌、新聞等々で確認されていると思います。ただ周知期間については、今後もっとよい形でできないか、検討したいと思います。","id":"exchange-048"},{"speaker":"石田（慎）委員","kind":"意見","question":"そうであれば、広報の期間に関しては、できるだけさまざまな工夫をして周知をしていただいて、より区民がわかりやすい、本当に必要な人が申し込めるような体制をつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"団地の先ほどの考え方なんですけれども、ほかの自治体で区営住宅というのがあると思いますから、その辺の状況をちょっと把握されていたらお願いしたいと思います。それから、休日相談窓口、毎回こういったところでは開設をされていますけれども、そこのところでどういうふうな利用実態があるのか、区民の方の相談のところでどういうことを把握されているのか教えてください。","respondent":"齋藤住宅課長","answer":"どの自治体も空き数、あるいは空き見込み数に応じてと、そういうやり方であります。申し込みの窓口ですけれども、大体１０人から１５人の方々が来られます。","id":"exchange-050"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原副委員長","kind":"質問・要望","question":"このエスコートゾーンをつくるということですが、まず具体的な場所を教えていただきたいのと、それからなぜその場所にしたのかということと、障害者の方が利用されていくと思うんですけれども、場所については障害者の方々とか、障害者の団体の方からのご要望というのを受けたのか、３点をまずお伺いします。","respondent":"諸石交通安全担当課長","answer":"今の３点について警視庁のほうの答えを私からお答えをさせていただきたいと思います。エスコートゾーンの具体的な設置場所ですけれども、１カ所目は品川区役所本庁舎前、番地でいいますと品川区広町二丁目１番から品川区西品川一丁目２７番までというふうに回答がございました。","id":"exchange-051"},{"speaker":"藤原副委員長","kind":"質問・要望","question":"朝回答をいただいたということを考慮して質問をしますが、なぜここなんですかという質問の答弁が、ここを利用するからということだったんですけれども、ここだけではないと思うんですね、利用しているのは。","respondent":"諸石交通安全担当課長","answer":"それと、今回は警視庁の独自の判断で視覚障害者用の音声信号機がついている場所、これも加味しまして、この区役所前の２カ所に選定したということで聞いております。今後の話なんですが、今年度は警視庁の独自の事業として、１１７カ所都内に設置をする予定だそうです。","id":"exchange-052"},{"speaker":"井上委員","kind":"提案","question":"警視庁のほうで調査をしていないということであれば、本来、一番身近な自治体として、そこのところがどうかというお話が、地元自治体から提案をされてもいいのではないかと思うんですが、そのことについてどうだったのかということと、もう一つ、これは確認ですけれども、私が東京都のほうに確認をしたときに。","respondent":"諸石交通安全担当課長","answer":"今回設置する場所、設置する前の段階で区としての提案はどうだったのかということでしょうか。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"違います。そのことについて、自治体としてどういうふうに、この利用者の声、今後は声を聞いていきたいということだったんですけれども、この部分について警視庁は調査をしていないけれども、自治体としてそこにつけるわけですから、自治体が警視庁へ、何といいますか、ここが有効な場所なのかどうかという回答はしなかったのでしょうかということなんです。","respondent":"諸石交通安全担当課長","answer":"昨日警視庁の担当のほうに確認したところ、先ほど申し上げました２カ所に設置するということで回答をいただいております。","id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"今の中延幹線ですけれども、バイパスで地元との調整がつかないで工事が延びているという話もあったんですが、ちょっと私、その辺がよくわからないんだけれども、どういうことですか。","respondent":"家壽田下水道河川課長","answer":"最後到達させなければいけないわけなんですが、その到達する位置ですとか、人孔につきまして、なかなかその周辺の方々との調整が、場所等も含めまして、難航したというふうに聞いておりまして、現在ではそれが調整がついて、すでにシールドは発進、今まさに掘削しています。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/803869?Template=document&Id=3916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":48515,"voices":159}},{"id":"h20-20080624-9","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"文教委員会","time":"午前１０時０３分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西本委員","kind":"質問","question":"事故があった日が１１月２１日ということで、昨年ですね。もう少し早く解決しないんでしょうか。大体こういう事故になるとこのぐらいの時間が必要なのかなということ。あまり使うなというのは仕事に支障があるんじゃないかと思うんですが、この辺はいかがでしょう。","respondent":"田村庶務課長","answer":"すまいるスクールの話ですが、どうしても手で持てる量というのは限られますから、必要に応じて私のほうに連絡をもらって、どうしても必要だということだったら車の利用も、安全運転を心がけるという前提で個別に判断してまいりたいと思います。","id":"exchange-001"}]},{"id":"topic-02","title":"校舎改築事業の進捗状況","agenda":"校舎改築事業の進捗状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一番左側の丸がついているところ、準備会とあるんですけれど、これはどういうメンバーでどういう概要を決めるのか教えていただきたいのと。例えば第一日野小学校でご説明があったのは、計画説明会と建築説明会を終えたという形でしたけれど、どのように分けているのか教えていただきたいのと。ちょっと報告いただけますか。","respondent":"田村庶務課長","answer":"特に影響の出る地域の町会あるいは関連団体の方、あるいはその学校そのもののＰＴＡの役員を中心にして、大体２０人から２５人ぐらいのメンバーでそれぞれ準備会を立ち上げて、そこにある程度の基本計画案、実施計画案ができたとき実際にご説明しているということです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜかというと、つくられる学校が従来の小学校、中学校、または一貫校どちらであれ、地域の理解と協力がなければ成り立たないわけであって、丁寧な説明やまた協力を求めることが非常に大事なのかなと思っているんですね。一貫校についてはいろいろ言いたいこともあるけれど、学校が今まで根づいてきて今後も根づいていくわけですから、そういう説明会というのは非常に大事になってくるのかなと思うんですね。","respondent":"田村庶務課長","answer":"やはり２年にわたる工期ですから、やはり地域の方の声も真摯に受けとめて対応しないとトラブルの原因になるだろうということで、私が４月以降出ている説明会でもいろいろな意見、すべてとは言いませんけれど、可能な範囲で具体的に対応しているという状況です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"同時に、どうしても問題意識を持っているのは、事業説明会を地域でしっかり開催することが必要なのかなと思っているんですよね。この間の経過を含めてこんな学校づくり、こんな教育活動をこの地で進めていきたいんだと。そういう説明会、いわゆる事業説明会なんですかね、それが必要ではないのかなと思っているんですね。事業説明会というのはどういうふうに位置づけているんでしょうか。","respondent":"市川教育次長","answer":"ですから、委員は地域向けの説明会を別途また行うべきではないかというご提案ですけれども、その考え方については先ほど申し上げたように、そういうことをこの準備会などで反映させようということでやっておりますので、ご意見はご意見として承っておきます。","id":"exchange-004"},{"speaker":"川西委員","kind":"質問","question":"流れ方というのはどういう。私、品川小学校と城南中学校に過去、関わってまいりまして、今現在どんな意見が出ているのかも含めて、なぜこの委員会でなくて次の委員会なのかということを伺いたいと思います。","respondent":"市川教育次長","answer":"これについてはハード面で併設ができるかどうかが一番問題だったわけですが、小中一貫校と幼保一体施設の意欲的な連携を図るといった計画が可能かどうか、これについて少し時間をかけて検討してきて、併設ができるという結論を出しました。","id":"exchange-005"},{"speaker":"川西委員","kind":"意見","question":"今のはわかりました。ほかの、例えば校庭に大きな木があるでしょ、あれをどうするかとか、どの辺の緑をどう残すかという意見は地元から出ましたか。そういう具体的な、もう少し地元からの意見を聞かせてください。","respondent":"市川教育次長","answer":"今ご指摘がありました大きなムクノキ、城南中の校庭のところにムクノキがありますけれども、あの歴史のあるムクノキは当然、私どもも最初から残すつもりでいろいろな計画を立てておりましたけれども、この準備会の中では。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"実はこの地域のお年寄りたちがとっても首を長くして待っておりますので、特に施設を利用したいということでリーダーたちが待ち望んでいるんですが、できれば地域センターにプリントとか、「延びました」みたいなお知らせというか目にわかるようなものを貼っていただくとか、そういうことをできればお願いしたいと思うんですが、いかがでしょうか。","respondent":"田村庶務課長","answer":"正式に今日、文教委員会にもお話ししましたので、可能な限り、地域センターも含めて目に見える形の掲示物も含めて、提示したいと考えております。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"八潮の話なんですけれども。今ご報告いただいて、文教委員会で２カ月遅れるという報告がされるのは初めてかどうか。自治会とＰＴＡにはもうお話が済んでいるというお話だけど、済んでいて委員会には今日なのかというそこら辺の話で、時間的なものを教えてほしいのと。それから鋼材のお話があったけれど、なぜというのを教えていただきたい。そこら辺の考え方を教えていただきたいのと。","respondent":"田村庶務課長","answer":"それとほかの八潮についての影響ですが、やはり本体の引っ越しが先ほど申し上げたように８月ということになりますので、ほかの施設もそれによって約４カ月ほどですか、４月に開校を予定しておりましたので２学期からという状況です。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"確認","question":"もう一遍確認したいんですけれど。夏休みに工事を考えていますよね。そうすると同じような形の時期になるのか、７月と８月に分けてやるのかというところがあるけれども、どうせ校舎を使わないのであれば、４月からあわせてやったほうが合理的と思えるんだけれど、そういう形に変えるのか。そこら辺のところを教えてほしいのと。今こういう状況になってどこの工事もおくれているんですよ。というのを知りたい。","respondent":"市川教育次長、和氣小中一貫教育担当課長","answer":"ただ、委員のご質問の趣旨は、認識しているだけじゃなくて実際に認識からもう１歩進めたところで役所として対応するようなことを、今回のこういう事態からどういう教訓として生かしていくんだというお尋ねだと思うんですが。八潮の工事の件ですが、夏休みに予定しておりました工事につきましては早めまして、校舎を使っておりませんので全部済ませて、２学期には終わった段階で入るということを考えておりまして、８月中に引っ越しをしたいと考えております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう一度教えてほしいんだけれど、それはそれで結構なんですけれど、ということは、随意契約でプラス工事でやると我々は思っていいんですか。４月からだったらそれはまた別工事でというのはわかるんだけれども、一体で一緒にやってもらうのであれば、もちろん今やっている業者は絶対できるわけだから、随意契約でそのままプラスでという形で……。それは決まっているんじゃないの。","respondent":"市川教育次長","answer":"確かに今、委員にご説明いただいたのは、私どもからすればそれが１つの方法だと考えていますけれど、現在議決をいただいてこれから工事に取りかかる、その関連工事のような形になるのか、契約上別途の工事の取り扱いになるのか。","id":"exchange-010"}]},{"id":"topic-03","title":"学事制度審議会 中間まとめ","agenda":"学事制度審議会 中間まとめ","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この審議委員に区民の代表とかいますので、だれが何を話したとか個人名を出すというのは配慮が必要だと思いますけれども、そのときであっても学識経験者とか区民の代表とか、学校とか教育委員会事務局とか、選出区分は出しても問題ないと思うんですけれども、議事録や資料の公開はぜひ出していただきたいと思うんですけれど、いかがでしょうか。","respondent":"富田学務課長","answer":"中間まとめですが学校には配付をしておりまして、保護者の方からのお求めがあればご覧いただけるようにしていただく予定です。ただ、一般の方々、保護者の方々以外につきましては、ほかの場所であるいはホームページでの閲覧ということでお願いをしたいと考えております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"「保護者の求めがあれば」という説明ですけれど、パブリックコメントをかけるわけですからきちんと置いておく、「どうぞお取りください」、そのぐらいはあってもいいんじゃないかと思うので、そこだけぜひ言っておきます。何で混乱が起きるのか、そこがよくわからなかったので教えてください。それはいかがでしょうか。","respondent":"富田学務課長","answer":"今回の中間まとめは、あくまでも審議会の最終答申を得る前の中間のまとめの報告ということでありまして、審議会は継続されているものであり、そういった意味で議事録等の非公開については審議会の中での定めに従ったものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"もう一定の結論が出ているわけですから、今までの経過を出すのは必要だと思うし、最終まとめが出ればその時点で出すお考えなのかどうかも含めてお伺いしたいのと、情報公開条例の縛りで考えると、非公開の理由が変わっていないなら変わっていないでいいんですけれど、どこの規定をもってそうしているのか、審議会の委員の意思だというのと、諮問をかけた時点でもう非公開ですから。","respondent":"富田学務課長","answer":"非公開というのは審議会の皆さんで決めていただいたことですけれども、情報公開等の条例で当てはまる部分が、近いものがあるとすれば第８条の５号と考えます。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"諮問のテーマの小中一貫教育と学校選択制を高く評価して、それを実施される方策という形で審議していますが、この中身でも、到達点というのが提言というところになるんでしょうか、学校選択制はアンケートでも評価が高いとか、小中一貫校は保護者のニーズが高いと、いわば天まで持ち上げているわけですけれども、まずは議論の初めとして、そういう結論をどういうふうに受けとめているのか。","respondent":"市川教育次長","answer":"今回、学事制度審議会では、審議の方向性を明らかにするということでこの中間まとめを出していただいたわけです。その意味では、この方向性につきましては極めて多角的な面から検討が行われていると教育委員会としては受けとめ方をしています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会としては多角的な検討をされているということですが、私自身審議の経過がわからないのでこの範囲で読み解くしかないんですけれど。例えば２ページ目の一番下のほうに学校選択制のことが書いてありますけれど、アンケートを根拠に小中学校ともに通学区域の学校以外を希望する人が３割を超えていると。逆に言えば、従来の指定校に入学した人が６割なわけですよね。その辺、教えてください。","respondent":"市川教育次長","answer":"学事制度審議会がどういう考え方をし、あるいはどういうある一定のことに評価をしているか、これについていろいろお考えを述べられるのはあろうかと思いますけれど、それが言い過ぎだとか、やり過ぎだとかそういうことも含めて、ご意見としては承りますけれども。","id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"ただその経過がわからないので、わかりようがないので、どうしろと言われても困ってしまうんですけれど。基本原理は特色ある学校づくりだと言っているけれど、区民のほうはそれを２割しか選択の理由に挙げていないわけですよね。要は、区民に高い評価を得ているとおっしゃっていますけれど、このアンケートからもそうは言えないんじゃないかと思うんですけれど、どう受けとめていらっしゃるのか。","respondent":"市川教育次長","answer":"先ほども申し上げたんですが、今のご質問にお答えするのは学事制度審議会でなければこの時点でお答えできないわけでございまして、要するに教育委員会としてどう考えているのかというご質問なのか、この中間まとめにこう書かれているのはおかしいじゃないかということは。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"この中間のまとめを教育委員会はどう受けとめているのか、どういうふうに理解しているのか。審議会でどんな議論がされたのか、ぜひ中身も知りたいけれども、少なくとも中間のまとめを教育委員会がどう受けとめているのか、どう評価しているのか。そこを聞きたいと。","respondent":"市川教育次長","answer":"冒頭お答えしたことの繰り返しになりますけれども、学事制度審議会は今回、私ども教育長からの諮問事項を検討するに当たって、まず私どもからは教育改革を着実に推進する上でご意見を伺いたいという、このお示しした前提。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"１つ伺いたいのは、この報告書は今後よく見ますけれど、区民の選択制や小中一貫教育も含めて意見が二分していると、どちらでもないも入れれば三分しているというふうに私は思うんですけれど、この報告書はどんなふうに分析されていらっしゃるんでしょうか。そこだけ教えてください。","respondent":"富田学務課長","answer":"学校選択の評価等々につきましても評価しているという方々がまあ、半分を超えているというような報告はいただいておりますし、また望ましい学級数につきましても先ほど審議会の中でも触れられたような。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"後ろの１６ページからの生徒数の見方を教えてほしいんですけれど。１５ページの（２）にあらましは書いてあるんですが、１６ページからの図を使ってもう一度説明していただけないでしょうか。","respondent":"富田学務課長","answer":"これに対して施設面での対応可能な教室数を、この品川地区の６つの小学校に１年生が入るときの学級数で見ますと、１４教室ということになっております。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"要は、それぞれの対応可能教室数というのは、例えば品川地区の小学校であれば６校の中の定数はこれだけありますよという説明ですよね。それで、対応可能教室数より上回っている場合は見直しが必要ではないかとしているわけですけれども、もうちょっと、これをよく見れば分かるんだと思うんですけれど、注釈を書いてあげないとわからないんじゃないかなと思っているんですけれど、いかがですか。","respondent":"富田学務課長","answer":"ご意見ありがとうあります。中間まとめでいただいている中身ですので、このまま出さざるを得ないところがありまして、読み方等々お問い合わせがあれば丁寧にお答えさせていただきたいと思います。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"まあ、このまま出すということだろうなと思ったんですが。例えば質問が来たとき、何か１枚つくっておけば簡単にこういうことですよと渡せるかなと。人口がどういうふうになってということを考えるためのもとになるような感じがするんですよね。ここをちゃんと読み取っていただいた上での考え方を出していただくことが必要だと思いますので、その辺の配慮をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"市川委員","kind":"質問・要望","question":"パブリックコメントの内容のほうなんですけれども、意見募集期間が７月１日から７月１５日と、正味１５日間にしたという根拠というか理由をお聞かせいただきたいんですけれども。","respondent":"富田学務課長","answer":"パブリックコメントについての区の要項の中で２週間から３週間ということがありますので、それを踏まえまして半月ということで決めさせていただきました。","id":"exchange-022"},{"speaker":"市川委員","kind":"質問・要望","question":"要綱では最低１４日という規定になっていて、それはクリアしていると思うんですけれど、この内容は先ほど西本委員からもありましたように読み取れないというところもあったり、これからの教育を考えていく上では非常に、教育の根幹をつくるというところもあって、区民の皆様もこれについては意見を出したいと思う方もいらっしゃると思いますので。","respondent":"富田学務課長","answer":"学事制度審議会の最終答申のスケジュールというものがありまして、１０月末を予定しているということがあります。そうしますと、こうしていただいた意見をまとめ、最終答申に反映させていく全体のスケジュール等々勘案いたしますと、この日程はやむを得ないものと考えております。","id":"exchange-023"},{"speaker":"市川委員","kind":"質問・要望","question":"そういうスケジュールのこともあると思うんですけれども、あと１週間でも延ばしていただければというのが要望ですので、それはお伝えしておきたいと思います。いろいろな資料を読んでいるんですけれども、小中一貫校６校構想というのが言葉として出てくるんですけれど、この６校構想というのがどうして６校ということになったのか、ちょっとよくわからないのでその説明をお願いします。","respondent":"富田学務課長","answer":"小中一貫校６校構想というのは、歴史的な地区割り等々ありますので、そういったものを踏まえて各地区に小中一貫校をということで６校になったと私は受けとめておりますけれども、実際この中間まとめで審議会では６地区で検討しますというふうに書かれておりますが。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問・要望","question":"そういうことで今後、急にどうこうということはありませんが、今進めている６校構想が終わらないと次の段階に進まないのかなと思いますけれど、多少、ブロック、地域、学校規模というものも将来考えざるを得ないんじゃないかということを、この選択制の分析をしながら、６番とか（２）で言っていらっしゃるような気もいたします。基本的なところを私は知らないので、２番目はその質問です。","respondent":"富田学務課長、田村庶務課長","answer":"この中間まとめをご覧いただいて、先ほども多角的な検討をしていただいているということでしたけれども、そのとおりであろうと思います。教室の関係ですけれど、改築に当たって今の教室が４０人学級で大体６０m2、改築後は７０m2台ですから、逆算すると１人当たりというのが大体出てくる。そういう状況です。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはこれとして、多分、今日議会に報告されるということは学事制度審議会のメンバーの方にも今後伝わると思って、議会からこういう意見がありましたということは多分どこかでお伝えいただくと思うので、ぜひ委員の方々に伝えていただきたいという観点で。やはり最適な教育環境のためにこれから最終答申に向けて、ぜひどんどん議論を重ねていただきたいというのを伝えていただきたいというのが１つ。","respondent":"市川教育次長","answer":"今回の中間まとめに基づいて最終答申が出された折には、折しも新しい長期基本計画の策定ということと相まって、これからの品川区政の１つのビジョンを示すときですので、教育委員会といたしましては、この間進めてまいりました教育改革の着実な進展ということも視野に入れて。","id":"exchange-026"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"この２項目で正副で調整した上でということで構わないんですけれども、特別支援教育は子どもたちへの配慮があるとは思うんですけれど、市民科は実際どういう授業や取り組みが行われているのか、実はそこが一番知りたいんですね。もちろん概要としての説明は必要でしょうけれど、委員会としてはそこでどんな教育が行われているのか。意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"意見","question":"品川区の教育改革は、そういう意味では、私、文教委員にならせていただいたこともあるし、社会教育委員で視察に行かせていただいたりすると、逆取材を受けることが非常に多かったりして。教育改革で行くというと大変だというのも大分あると。事務局も含めてぜひそういうのを取り上げてほしいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"視察ですけれど、今の市民科でいくと、ふだんの姿を見たいなというのがあるんですよね。でもどうしても視察の方々が来るからといつもと違うような感じになってしまうのかなとも思うんだけれど、そうじゃなくてふだんどういう授業が行われているのか、ぜひありのままを。１つの授業だけですべてを見るのはもちろんできないでしょうけれど、ふだんの姿が見られたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"西本委員","kind":"意見","question":"これはどうかなと思うんですけれど、ずっと文教委員会をやっていて、平成１５年に呉市に行かせてもらったんですよね。そのとき一貫校ってどういうところかというのがあったので、品川区よりも先に一貫教育というか連携という形での教育をやっていたところがあったと思うんですよ。先に動き出したところはどういう動きになっているのかなというのも気になるので、ちょっと勉強してみたいと思ったんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"地方と都市部では違うということはよくわかっていますけれど、やはり新しくできるところですから、どうやって住民の活動の拠点として文化活動なり図書館活動がされているか。ちょっと覚えていませんが、ニュースで聞いたんですが、財政問題で一部縮小、閉鎖しているところがあると聞いているんですよ、地方で。ですからこれから大事なことだと思っているので。これはついでで結構ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"山元委員","kind":"意見","question":"私もちょっと申しわけないんですが、学校と地元の商店街がタイアップをして、北海道のほうだったかちょっとあれなんですけれど、本来学校でお金をやりとりしたらいけないんでしょうけれど、何か提供しているというのをニュースで聞いたことがあるんですね。地元の商店街と学校とのつながりというか、そういうところがあるのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"川西委員","kind":"質問","question":"きのう質問すればよかったんでしょうけれど、平成２０年度に予定されています耐震化工事の工事日程等はほぼ決まっていますか。","respondent":"田村庶務課長","answer":"前回もたしかお話があって、大体３カ月から長いので６カ月ぐらいかかるので、もう具体的に今年度の平成２０年度については夏休み中を中心に工事をしますので、具体的な日程は決まっていますので、学校名を教えていただければ後ほど。","id":"exchange-033"},{"speaker":"川西委員","kind":"確認","question":"そうしますと、確認しておきたいのは、一応夏休み終了までにほぼ予定されている学校は終わるのかどうか。","respondent":"田村庶務課長","answer":"今回１１校の耐震補強工事をやるんですが、やはり工事は３カ月以上かかるので、夏休みの時期に教室内を使ったり音が出るものを中心にやりますが、その前後についても一切工事をしないというわけではございませんので。夏休みを中心にするという調整の仕方なので。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"議会はわかりましたけれど、学校といいますか、そういうところはこれはどういうふうに渡るんでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"学校には３冊ずつ全部お渡しをして、研究、検証に使っていただくということで、学校では校長先生を中心に、これを１つの素材にしながら自分たちの実践に生かしていくという形になっております。","id":"exchange-035"},{"speaker":"川西委員","kind":"質問","question":"今の説明によりますとどのぐらいの電力量が節減されるか、計算というのは出されているんですか。","respondent":"堀越生涯学習課長","answer":"例えば公園の部分については白熱灯ですとかいろいろな種類がありまして、その算定が可能かどうかまた後で改めて確認いたしますが、今回の趣旨は温暖化防止の、１０分間という形でとにかく一斉に行動を移そうと、改めてできることをやっていこうというキャンペーンですので。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/361184?Template=document&Id=4638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":30261,"voices":119}},{"id":"h20-20080624-5","meetingId":"h20-cm06","date":"2008年6月24日","dateIso":"2008-06-24","committee":"総務委員会","time":"午前１０時０２分～午後４時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"第４４号議案、平成２０年度品川区一般会計補正予算","agenda":"第４４号議案、平成２０年度品川区一般会計補正予算","exchanges":[{"speaker":"土井委員","kind":"質問","question":"今回も、その意味では歳入のほうの入ってくるのは、都からのお金が入ってきているものと繰入金で、新たな事業をやるために入れるものという形と債務負担となっているんですけれども、いつも思うんですが、もとのやつとどれだけ違ったらどうするのというところもやらないと、こういうものがいっぱい出てきて、ものすごい時間がかかって大変なお金がかかること。","respondent":"日下部企画財政課長","answer":"６月ですから、やはり当初の段階である程度見通しをしっかりと立てられれば補正の措置を講じなくて済むんですが、どうしても先ほど来ご説明させていただいた事業につきましては、当初予算の編成の時点でその具体的な事業、例えば商店街の活性化事業につきましても。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"それで新たなものなので、裁量の範囲でやれるかやれないかというところの判断もあるけれども、１点でも大きいのがあれば、あわせてここでやりましょうという意味だということなのか、要するに例えば今回、この中に大きなあるものがなかったら出てこなかったんですか、という話にもなるわけです。だからそこら辺をちょっとお聞きしておきたいわけです。","respondent":"日下部企画財政課長","answer":"ただ、流用という措置もあるだろうと。それは２３区それぞれが判断して対応しようということになりましたが、ただ品川区、私どもとしましては、やはりこういった新しい施策を実施するという以上は、やはり１つの政策決定というプロセスをしっかりと踏んだほうがいいだろうと。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"今のお話を伺っていても、例えばさまざまなものの幾つかは、というかかなりの部分が新規のものであるということは、とはいっても例えば学校給食の追加分の話はもともとあるわけです。それがちょっと誤差が生じた。誤差というか何というべきかどうかわからないけれども、ある範囲でいける代物でもあるわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"確認","question":"ちょっとその辺の２つを伺いたいと思います。１回目が不調に終わったということを受けて、区としてはこの予定価格そのものがどうだったのかという検証をされて、その後なおかつ同額で示して入札をしたのか、ちょっとその辺のところだとか、その後、やむなく随意契約になっていくわけなんですけれども、その辺のあたりのところをちょっと伺っておきたいなと思いましたので、ちょっとそのあたりの質問を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"実質的には来年度以降の債務負担行為のところになっているんですけれども、私どもとしては、この債務負担行為の後の議案と絡んできているから、非常に審議しづらいなという思いを持ちながら発言・質問しているんですけれども、ここのところがどうしてもきちんとしておかないと判断ができないところがあるので、それで伺わせていただいているということ、後の審議と絡んでいることは承知しながらも。","respondent":"須藤委員長、日下部企画財政課長","answer":"ただ、やはり委員会として運営の上で、審議が違っていますので、最初の議題は一般会計補正予算ということで見ていきますから、その範囲の中での債務負担行為についての経緯等についてのご説明にとどめていていただかないと。それから債務負担の荏原西地区小中一貫校建設についてですけれども、これは、今、ご質問にもございましたいろいろな入札等の経過がございましたけれども、先ほどご説明させていただきましたように。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"それから債務負担行為のところは、そういう資材、鋼材の価格が高騰ということが理由とされているんですけれども、鋼材価格が高騰しているということは、この荏原の校舎新築、一貫校校舎をつくるということを計画した時点から、一定程度の鋼材の価格高騰というのはあったんじゃないかなと思うので、とりわけ入札を組む時期にはそういう状況というのはまた顕著になってきているという時期だと思いますので。","respondent":"日下部企画財政課長、市岡総務部長","answer":"品川区といたしましても、このところ昨年来食材が大分高騰しておりましたので、実は４月の段階でもいろいろと検討したんですが、家庭への影響等もいろいろ考慮いたしまして、何とかやはり当面いろいろ工夫をして頑張っていこうと。したがいましてこの補正がないと、その後の鋼材の高騰には対応ができないということで、お願いをするというものです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それから債務負担行為の部分なんですけれども、そういう今の説明のことだということは理解しているわけですけれども、私の知りたかったのは、起工時点で直近の基準で計算をして示したということなんですが、そのときの判断基準として、さらにこれから鋼材価格が値上がりしていくということを予想しなかったのか、してもどうだったのか。","respondent":"日下部企画財政課長、市岡総務部長","answer":"給食の関係ですけれども、私のほうで教育委員会のほうから聞いている限りでは、今までの品川区の先ほど申し上げました現行のそれぞれの給食費の単価につきましては、２３区の平均以下でございました。起工の時点では、そのときに直近の価格の高騰も反映したもので積算をしたわけですけれども、積算基準というのは、これは起工する執行機関側も当然拘束される公正なルールですので、その後の高騰については。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"資料によりますと、見積もり金額が４５億８,３６７万円。それで今度、これからもとの予定価格を引くと、３億３,７０５万円にはならないんです。それで３億３,７０５万円に来たというのが、ちょっとどういう話し合いがされたのかという、この辺というのは教えていただけたら、明らかにしていただきたいと思います。","respondent":"市岡総務部長","answer":"どれだけの不足が実際の入札の経過の中で生じたかということと、どれだけ補正をすれば成約に至るかということ、これは全く別の話でございまして、今回は、これはまだ補正のお話ですけれども、契約の種別としては４本ありますので、４本あわせた必要額に対して不足が生じたので。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"それで、随分この問題について質問させていただいているんですけれども、最後にちょっとその点について、どういうふうに区としては努力をしてきたのかなということを、ちょっと改めて伺って終わりにしたいと思います。","respondent":"市岡総務部長","answer":"最終的に随意契約で成立するまでの過程では、この補正予算の所要額を、一番最小の経費で当初の計画ができるように十分な折衝等を行いながら所要額を算出して、補正をお願いしたです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"財源を３億３,７０５万円プラスしなければできない状況になった中で、建築工事そのものを、今、進めていかなければいけないものなのかというところで、進めるということよりも、むしろ状況を見てというふうに足踏みをしてもいいんじゃないかなと思いましたので、改めて、ここについては大変残念ながら賛成はできないということで、態度は反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"今の委員長のご心配については、私たちは一貫校そのものには反対ですけれども、しかし現実的には荏原第二中学校で一緒に授業を受けているという状況がありますので、それはそれとして、どこかの校舎がない状況でいるということではないわけですから、それは別の問題じゃないかなと思いますので、さっき言ったとおりの意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"地区小中一貫校新築給排水衛生設備工事請負契約、(4) 第５８号議案（仮称）荏原西地区小中一貫校新築空気調和設備工事請負契約および(5)","agenda":"地区小中一貫校新築給排水衛生設備工事請負契約、(4) 第５８号議案（仮称）荏原西地区小中一貫校新築空気調和設備工事請負契約および(5)","exchanges":[{"speaker":"土井委員","kind":"意見","question":"この新築工事にかかわって最初に契約をしよう、入札をお願いしたいということで、制限付き一般競争入札、これは今の品川区におけるさまざまな入札の主要なものだというふうに理解をして、これでやりましたということですよね。それで残念ながら辞退されてしまったということは、間違いなく資材高騰等のせいだろうなというふうに理解をしたということでして、そのときには予定価格は出ているわけですね。","respondent":"阿部経理課長","answer":"そうです。","id":"exchange-012"},{"speaker":"土井委員","kind":"意見","question":"それじゃいけないから、じゃあ、この方式じゃない入札の仕方を考えようということで、指名競争入札となります。指名競争入札の場合は、過去の事例から言ってもこれは予定価格なしと。要するに業者をご指名申し上げて、こうこうこういう条件で入札してくださいという形ですよね。少なくとも２社は入札されたし、そこが２回目になっているわけです。この辺のところをもうちょっと話していただけませんか。","respondent":"阿部経理課長","answer":"ここでも応札がなかったですので、したがいまして先ほどご説明いたしましたけれども、この２回目の指名競争入札で最低限の価格を入れた戸田建設と最終的には随意契約に至ったというような状況です。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"イメージしていたんだけれども、それでも１回目はだめでしたと。いや、ちょっと違うのでもう１回といったら、２回目、それじゃあ、だめ。そして次に随意契約に行くときに一番安いところと交渉をして、私どものイメージはちょっと違うんだが何とかなりませんかと、こういうお話だったというふうに理解してよろしいんですか。それで、その上で随意契約になった金額は、どういうようになるかという話です。","respondent":"阿部経理課長、市岡総務部長","answer":"ですから最終的にはし直して、その結果をもちまして教育委員会、あるいは施設担当のほうで戸田建設と交渉して、今回お示ししている金額、４５億八千万何がしという金額で合意をしたです。今のをちょっと補足しますと、指名競争入札の１回目に、この資料のとおり４番目の戸田建設は４６億８,３００万円という札を入れております。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"ただ、もう１つだけお伺いしたいのは、仮に制限付き一般競争入札であっても、入札の条件とか、それから終わった後の契約の条件等の中に、資材の高騰等の急激な大きな変化があったとき、天変地異が入っているかどうかは知りませんが、そのような場合には契約の再交渉もあるよというのは、普通には書いてあるというか、普通の契約のときにも書いてあるやに伺っているんですけれども。","respondent":"阿部経理課長","answer":"いずれ近々には決まると思いますけれども、そうしますと区としても具体的な、既に契約を行ったものについてどういう範囲で適用していくのか、そういうことは検討していかなければならないと思っています。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"わかりました。それを今までどうもかなり泣いている業者もあった。地元の業者なんか、「まあ、しようがないか」というリスクをそのまましょってしまったという方もあるようですけれども、そんなようなことが今回の場合、後から「いやあ」という話になるのかならないのかという問題が必ず起きるんですけれども、名誉にかけてもそんなことはやらないと思うけれども、そこら辺はどうなんですか。","respondent":"市岡総務部長","answer":"ただ、これはなかなかあまり言われていないことですけれども、すべての価格上昇リスクを公共だけが負担するということではありませんので、これは事業者のほうも積算の時点で必ずその後の価格高騰だとか。","id":"exchange-016"},{"speaker":"土井委員","kind":"質問・要望","question":"さまざまなその種のリスクは民間は大いにしょってやるというのは、多々、事例を言ってはおかしいけれども、輸出物なんか相手国の戦争が始まっちゃったりすると一遍に値段が違っちゃってとてもできなくて、我々なんか従業員の給料を下げてまで頑張ったものがありますので、そういうことにならんように、逆に言うとしなきゃいけないし、公共の責任。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"それとあと、１階から６階ということで結構移動が大変なのかなというのはあるんですが、休み時間が少し長くなるのか削られるのかわかりませんが、何かいい工夫は、もちろん教育委員会のほうでもとると思うんですが、それだけちょっと１階から場合によっては用事があって６階まで行く場合は、５階ですか、プールが６階ということで、大変なんだろうなというのはちょっと見受けられましたが。","respondent":"宍戸施設担当課長","answer":"１点目の地中障害物を事前に予見できないかというご質問です。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"これは前代未聞だったと思うんです。そういう問題点が１つは過去にありました。そういう中で伺いたいんですけれども、制限付き一般競争入札としては予定価格が４１億９,３７０万円と設定して入札したけれども、ＪＶ２社が辞退をしたという、まずこの時点で、区としては辞退になったことをどういうふうに見たのか。そこのところの評価を１つ伺いたいと思います。","respondent":"須藤委員長、阿部経理課長","answer":"入札の日程は、今、いただいた書面で、最初は５月２８日に実施されました。それから６月１３日に指名競争で執行されましたというような記述が入っておりますので、そこから読み取れると思います。それでこういう適正な手続きをとってまいりまして、最後に指名競争入札で最低の価格を提示した者、戸田建設と随意契約を結んだということで、この間、契約事務については適正に進めてまいったと考えています。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私が質問したのは答えていただいていないと思うんですけれども、１回目の制限付き一般競争入札をされて、ＪＶを組んだ２社が辞退をされたというこのことを、予定価格を公示しておきながら辞退をしたというこのことをどういうふうに評価をしたのかという。ちょっとその辺を伺ったんですけれども、答えがなかったのでどうなんでしょうか。","respondent":"阿部経理課長","answer":"検討状況を踏まえたからこそ、第２回目に起工し直して指名競争入札にしたものです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"ですから問題ない、資材の高騰がこの時期にあったということがここにあるわけで、それでもなおかつ辞退をされたということで、業者がそういう対応をされたということなんですから、その辺をどう見ているのかということをちょっと見解を伺わせていただきたいと思って質問しています。","respondent":"阿部経理課長","answer":"第１回目の制限付き一般競争入札の予定価格につきましては、私どもは積算基準に従いまして適正に積算をいたしました。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"だからその起工し直したというところはわかりましたけれども、しかし１回目の制限付き一般競争入札で辞退をされたというところがあって起工し直したわけですけれども、そういう状況をせざるを得なかったというのは、先ほどからおっしゃっているように資材の高騰とかそういう背景があってのことだというふうに私は理解をしているんですけれども、そうなのかどうかを改めて確認をしたいということで。","respondent":"阿部経理課長","answer":"先ほどの土井委員の質問にもお答えしましたけれども、第２回目の指名競争入札には価格を上げております。ただ、これは公表はしておりませんけれども、私どもの持っている数字としては価格を上げております。それは、今、申し上げたとおり、資材の高騰等を踏まえたです。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"それはこの議会の場面でも明らかにできないものなんですか。私はしてもいいんじゃないかと思うので伺いたいと思っているんですけれども、それも踏まえてちょっと１つそれは伺いたいということと、結果的にそこには応じる状況じゃなかったから２回の入札を、指名競争入札を２回されたわけですよね。しかもその２回とも不調に終わったと。その辺のあたりをちょっと知りたいんです。","respondent":"市岡総務部長","answer":"これは日銀の物価統計等で鋼材の値上がり率というのが客観的に出ておりますけれども、そういうものに基づいて改めて起工をし直したということで、再検討したということですが、ご理解いただきたいのは、これは予定価格を上げれば入札が成立しますけれども。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"先ほどもどなたかの発言の中で出ていたけれども、自分たちで全部かぶらざるを得ない。ですからそういうのがあって、価格の高騰もあって、応札できなかったという事態がずっと続いてこざるを得なかったんじゃないかと思いますので、その辺についての認識というのはどういうふうに持っておられるのか、全くないのか、あるいはどうなんでしょうか。そこを伺いたいと思います。","respondent":"宍戸施設担当課長","answer":"あくまでもこの標準単価という実勢価格をもとにつくられていまして、もちろん我々も鋼材費の値上がりの兆候がありますとか、あるいはどんどんこれから値上がりする恐れがありますというふうなことは新聞記事等々で見ていて、実は我々も心配していたところではあるんですけれども。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"それと随意契約のところの金額なんですけれども、ちょっとこれはよくわからないんですけれども、見積もり金額ということで４５億８,３６７万円が示されているわけですけれども、これは実際に指名競争入札のところで、２回目の入札金額として示された４６億３,０００万円で、この価格を示した業者に対して随意契約を結ぶということで、その見積もり額として示されたというふうに私は理解するんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"当然、向こうの入札価格が４６億３,０００万円ですよね。こういう判断をされて随意契約に至るわけですね。そのときの金額も５,０００万円ぐらいの差があるわけです。率直に言うと、端的に言うと痛み分けしましょうみたいな、そういう角度で話し合いをしてこの金額に落ちついたという、そういうことになるわけですか。ちょっとそのあたりの経過を教えていただきたいと考えていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"それで、今まで質問していろいろなことがわかったんですけれども、なおかつそういうふうにして、区は最大限の努力をしたということは、それはそれとしてわかりますけれども、不調に終わってしまえば、今回は随意契約という選択をとろうということでここまで進んできたけれども、もう一方の選択としては、もうちょっと資材の高騰がおさまるまで様子見をしようじゃないかと。","respondent":"市岡総務部長","answer":"この契約議案というのは、私ども契約の担当の部局である総務部が原局から執行委任を受けて契約事務を進めておりまして、開校時期ですとか、それから委員もご案内だと思いますけれども、この計画の財源となる国庫負担金、国庫支出金。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"それは国庫補助金との関係で、支出金との関係ではそれはそれとしてあるということはわかりますけれども、しかしきのうもあれしたこういう選択がいいかということじゃなくて、あり得るという可能性のところで申し上げるんですけれども、繰越明許という形で引き延ばしてやっていくことだってない道じゃないわけですから、私はやはり今回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問","question":"本会議では多少ご説明がありましたけれども、やはりこの委員会で、なぜ、今、この時期に出してきたか。それは結果的にどういうメリットになるかということの説明が、今、質問があって初めてあったんですけれども、できればこれだけ大きな案件でありますから、当初の説明でいただきたかったなというのがありますので、改めてなぜ、今、これを出してきたかという背景を教えてください。その２つです。","respondent":"宍戸施設担当課長、市岡総務部長","answer":"２件目の、資材高騰の影響がなぜこの荏原西にだけこのような補正予算というふうな形になったのかという部分について、ご説明したいと思います。これは何回かご説明したとおり、早期開校を目指して、この時期に契約の議案をご承認いただくことからスタートをして、計画どおり進めていきたいと考えておりました。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それぞれありがとうあります。それで先ほど施設担当課長の話であった標準単価を決める。そうしないと、幾ら皆さんがその時点で努力したとしても、もともとの基準が変わらない限りは、それが一致がしないことになってしまうことが、当然あり得るわけですから、そういうことも含めたこれからの対処についてお聞かせいただきたいと思うんですが、いかがですか。","respondent":"宍戸施設担当課長、市岡総務部長","answer":"そういう意味では、東京都、それから２３区一緒になってこういう事態のときの対応方法、それから対応策について検討していきたいと考えております。区の工事請負の積算基準というのは、これは品川区のものではありますけれども、東京都の財務局の積算基準を参考につくっておりますので、今回の事態が、これは国。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問","question":"本当に、もしこれからも高騰が続いていくのであれば、同じような案件が十分出てくる可能性がある。だから品川区がこれだけある意味、そのスライド分を追加しているわけですから、そのことを通して、担当する都側なりいろいろな窓口のところに対して、ほかの自治体の参考例、いい意味での参考になる仕組みをつくり出すということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"これはどういうふうに考えるのかなというのと、あと積算されたこの金額は、いわゆる品川区としてはこの価格でいきたいというものに対して、この物価高騰でそれでは無理だろうというような、それぞれの業者で積算をしてきた金額に見合うように歩み寄って、結果的にはこの金額になったということなんですけれども、先ほどとダブってしまうかもしれないですが、この積算をする時期。","respondent":"阿部経理課長、宍戸施設担当課長","answer":"ただ、２回目につきまして、じゃあ、そのＪＶを組んだ親の企業を入れるのはどうかという話ですけれども、工事の内容の規模から言いまして、やはりある一定程度の格付けの上位の企業が必要だということが考えられます。起工と言いまして工事を起こすという行為から実際の入札までの手順ですけれども、まず起工と申しまして、実施設計の図書関係を確定させて、それに基づいて積算をして、工事金額を確定する。それが起工です。","id":"exchange-032"},{"speaker":"金野委員","kind":"意見","question":"わかりました。そうすると、相手方の自分たちでも見積もりをしてくる期間も含めて、３月に起工をしたもので、５月２８日のこの期間の中約２カ月あまりかかる。そこでは見直しはできなかった、相手方も見積もりをしているからという今のご答弁です。次、このＪＶでは不調に終わったので、指名競争入札までの間の日にちというのは１カ月ないわけですね。これはどう解釈したらいいんでしょう。","respondent":"宍戸施設担当課長","answer":"入札の期間中には、もちろんその設計図書ですとか予定価格というのは変更できないんですが、今、るるご質問にあるとおり鋼材も高騰していますし、これは非常に兆候としては不調になるおそれが非常に高いのではないかということを内部でも感知いたしましてある程度の準備をして。","id":"exchange-033"},{"speaker":"金野委員","kind":"質問","question":"何回もさっきから繰り返しのことになってしまうので、理解はしているつもりなんですが、物価高騰でやはり早急にこれは何とかしなければというこの期間の中で、単純に考えて、だったらこの前の２カ月の中でもそういった見直しというか、そういうことがあり得るぞということでできなくはなかったのか、そういうことはなかったのかということが、すみません、繰り返しになってしまうんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"山路副委員長","kind":"提案","question":"それを前提として、疑問な点は何点かちょっと聞かせていただきたいと思うんですが、５月２８日の入札時に不調に終わるのを感じられたということは話があったんですけれども、業者の積算と区の積算との大幅な違いといいますか、そこに、我が党でも前から何回も提案していたんですけれども、昔の営繕課の時代はそういうことがなかったような記憶があるんです。１回目の入札のとき。","respondent":"宍戸施設担当課長","answer":"したがいまして、先ほど、もとの別のスタッフであればこんなことにならなかったのにというふうな意味かなと思いますけれども、そういうことはなくて、一定の仕組みの中で計算していきますから、ある程度だれがやってもという言い方はおかしいですけれども。","id":"exchange-035"},{"speaker":"山路副委員長","kind":"質問・要望","question":"ありがとうございました。それと、今回随意契約まで来られましたけれども、先ほど言われた内容変更と業者努力ですり合わせて随意契約に持ってこられた。打ち合わせをここまで持ってきた、その辺をちょっとお聞かせいただきたいんですが。","respondent":"宍戸施設担当課長","answer":"着工してから以降は常駐の管理者もつきますし、私ども技術職員もかなり頻繁に検査等いたしますし、契約担当のほうにもついております検査員も配筋検査のたびに配筋検査等もいたしますし、手抜き工事等については一切できないような仕組みになっていると考えています。","id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"最後に確認だけ１点いいですか。金額が膨らんだ部分の財源というのは区の独自財源ということでいいんですよね。","respondent":"日下部企画財政課長","answer":"基本的には、先ほど申し上げましたように負担金補助金というのも見込まれておりますけれども、そちらでその分を補填するというような見込みは今のところは明確にはなっておりませんので、基本的には一般財源で負担をするという形に現時点ではなろうかと考えています。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問","question":"これは、第５６号議案に賛成する、そういうことではなくて全部ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"私は残念ですけれども、４本とも反対です。反対の理由は言わせていただきたいんですけれども、財源が、今、最後に聞いたら、これからのところもあるような印象も受けましたけれども、基本的には独自財源だと。財源があるから資材が高騰してもできるという状況で進めていくと、工事期間を間に合わすために進めていくという姿勢であるというところが、やはりちょっとなかなか理解しがたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-03","title":"を聴取いたします。 最初に、都区のあり方に関する検討状況","agenda":"を聴取いたします。 最初に、都区のあり方に関する検討状況","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"それで、何回も言っているんですけれども、こういういろいろな背景が変わってくる中で、どうしても心配なのが２３区の区長会の意向。それから、２３区の意向をくんで幹事会の委員として参加されているとは思うんですけれども、幹事会に参加される前に、区長会としてはどういう意見の集約をして区側の意見を都側にぶつけているといいましょうか、議論をしているのでしょうかということの確認。","respondent":"濱野区長","answer":"とにかく事務の話を進めていこう、それから区割りの話はなるべく対応しないようにしようという、その基本線を決めてやっておりますので、そこについて細かいやりとりはございません。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"提案","question":"そのことについては、濱野区長としてもつらいところはあるんだけれども、でも、区長は今、すべがありますので、幹事会の提案と２３区の区長会が十分受け入れられることがなければ進んでいかないと思いますので、そのことについての確認をもうちょっとお願いしたい。やはり事務の引き継ぎをきちんと、これは区側からも都側に対して担保する必要があるんじゃないかと思うのですが、その２つについてお話を。","respondent":"濱野区長","answer":"もちろん、同時並行で副区長会のレベルで実務的な検討もしております。ですから、例えば２３区で１つしかないような施設の運営といったものについては、いろいろ意見が出ているのも確かであります。そこの所在地だけがやるのかという。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、副区長会でもいい、担当部課長会でもいい、そのところで十二分に議論をしていただいて、今まで過去にやった経過も、失敗は失敗、合意できないこともあった、だけど、それを踏まえた上で、このチャンスをしっかりとらまえた上で２３区が一体となって都に向かっていっていただきたいという思いで発言させていただきましたし、また私たち議会も、できるならば後押しをしていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"土井委員","kind":"質問・要望","question":"だから、まさしくそういうことで、港区ができなければ品川区がやればいいしというスタイルでもやれるものはいっぱいあるはずですから、そういう形で、ぜひとも多くのものを移管するという形をとっていただくように働きかけをしていただきたいし、逆に弱音を吐きそうなところ等については、ほかのところでちゃんとやるんだから、やれるから、やるんだからということで進めていっていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問・要望","question":"一緒にやっていけるのかな」という問題もやはり出てくることは、私はやむを得ないんじゃないかなと思うんです。これだけ２３区がしっかりした自治体になっていますから、僕自身はもう、東京都というよりは、２３区一区一区がそれぞれ一生懸命、自治体の中で取り組んでいく事業こそが、一人一人の区民に、また都民にサービスをもたらすものだと思っていますので、ぜひ頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"南委員","kind":"質問","question":"その辺の区長の認識はどうなのかなというのをちょっと伺いたいと思うし、先ほどの説明では、「区に移管すべきものはすべて移管して完了しているという認識でいる」というふうにおっしゃっていましたけれども、そのこと自体がちょっと振り出しに戻っちゃったのかなという印象を持ったんですけれども、その辺はどうなのかと、基礎的自治体について都はどういうふうな認識を持っているのかという。","respondent":"濱野区長","answer":"そのためには、２３区がどれだけ協調できるかということだというふうに思っています。","id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"ですから、そういうお立場だと思いますけれども、そのことはちょっと強調しておきたいなと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-04","title":"２番目の男女共同参画社会をめざす品川区行動計画の改定","agenda":"２番目の男女共同参画社会をめざす品川区行動計画の改定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ここにも書いてありますように、法律が改正されたというふうに書いてあるのですが、どういうふうに改正されたのか、その内容についても教えていただきたいと思います。","respondent":"吉岡人権啓発課長","answer":"法改正についてですけれども、男女共同参画社会基本法そのものではないんですけれども、男女共同参画に関する法律ということで、平成１５年には次世代育成支援対策推進法が制定されたりとか、平成１９年の４月には男女雇用機会均等法が改正されまして。","id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"女性の社会参画を品川区民の狭いレベルで考えるのはいかがなものかなとも思いますけれども、率先してやっていくという点で、品川区の共同参画というのがどの程度のレベルにあるのか、その代表として、１つの指標として見るのが品川区役所としての見方かなというのもあるかなと思うので、ちょっとその辺を伺いたいのと、あと、品川区内の民間団体とか、さまざまな企業だとか、そういうところも含めて。","respondent":"吉岡人権啓発課長","answer":"区内の団体なんですけれども、昨日のＮＰＯの関係で出ていた団体で、「おばちゃんち」という団体がございましたけれども、ああいう子育ての支援をするような団体ですとか、あるいは、若いお母さんたちが子育てをするに当たってのマップを自分たちでつくって、先日。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"品川区は、結構、何年も前から女性の登用はずっと進んでいるなというふうに私も認識しておりましたけれども、女性の登用の目標は、ちょっと紹介がなかったんですけれども、３割ぐらい、３０％ぐらいかなと思っていたんですけれども、団体のところで、審議会では目標４割というふうにしているという紹介がありましたので、同じかなとも思うんですけれども、ちょっとその辺を改めて伺いたいと思うし。","respondent":"吉岡人権啓発課長","answer":"それで、現行１６％というお話をしましたけれども、一応、男女の雇用計画のほうで設定しておりますのは区の審議会等への参画ということで、こちらのほうは一応４０％目標でしていますけれども、どちらに対しても。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"特に品川区の行動計画の推進が非常に進んでいるだけに、その指標としても、もちろん能力というところはありますけれども、能力を度外視して女性を登用すればいいと、そういう論理で言っているわけじゃないですから、それはそれでくみ取っていただきたいと思うんですけれども、やっぱりできるだけ、女性だってすばらしい、男性に勝るとも劣らない能力を持っている人はほんとうにいらっしゃいますので。","respondent":"榎本人事課長","answer":"その中でも、先ほど来、話があります次世代育成の関係とか、それぞれの人生の設計の中で、どの段階でどういう管理的な地位につくのかという形は、それぞれ個人の問題の部分と組織の問題の部分と両方兼ね合ってきますので、この辺を考えていきますと、そういう目標値を定めて。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと答弁のあれで質問したくなっちゃったんですけれども、能力とその方、一人一人が、男性も含めてですけれども、自分のライフプランの中でどういうふうにしていきたいかというのは、個々が決める問題は、それはそうだと思います。しかし、私、いろいろ国会の状況なんかも見ていて、女性の答弁者だとか政府委員になったりする方が非常に多いですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"土井委員","kind":"意見","question":"男女共同参画社会を実現していくという過程において、さまざまな意味での数値目標を設定する、このことは悪いことではないんですけれども、逆に実現性のない目標ほど虚しいものもないわけで、この辺は大変重要だということなので、やはり着実に進んでいく目標設定ということであってほしいなということが１点と、残念ながら、品川区がいくら頑張っても、やはりこれは全体的な国レベルを含めた。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-05","title":"３番目、総合庁舎耐震改修工事に伴う出入り口、駐車場等の変更","agenda":"３番目、総合庁舎耐震改修工事に伴う出入り口、駐車場等の変更","exchanges":[{"speaker":"金野委員","kind":"質問","question":"この来庁者に関しての通常の可能な通路のところには、案内の人と言うのでしょうか、そういう人は立つのでしょうか。それと同時に、車いすの方の動線が、第三庁舎のエレベーターを使って第一庁舎に向かうのと、それから第二庁舎の通路をずっと渡って第一庁舎に向かう通路と、同じですね、この経路に関して警備なり案内人の方が立つかどうか、その辺はどうでしょうか。","respondent":"阿部経理課長","answer":"工事期間中は、先ほど申しましたけれども、歩行者あるいは車いすの方の安全確保のために誘導員を配置するということで、事業者と話し合っております。","id":"exchange-053"},{"speaker":"金野委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"伊藤委員","kind":"提案","question":"目に見えている話ですから、第二駐車場まで誘導するのはいいのですが、その入り口についての渋滞解消策といいましょうか、対処策はどう考えているのですかということをお伺いしたい。出入り口はこうですよ。ですから、こうしてくださいよ」というふうな、さらに進んだＰＲ、この工夫も考えていかないといけないところなのかなと考えていますので、そのことについてのお考えを２つまずお聞かせください。","respondent":"阿部経理課長","answer":"その辺につきましては、動線が変わるということもありますので、所管のほうと十分連携をとりながら、スムーズなＰＲ、歩行者動線が変わるたびにきめ細やかなＰＲをしながら、来庁者の方にご不便をなるべくおかけしないような、そう言ってもかけますけれども。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もうそれは目に見えている話なんですよ。もっとさらに進んで、直接、品川区役所に定期的に来ている方もいらっしゃるでしょうから、そういうことの体制は品川区としてやるし、やっていただきたいし、さらには、そういう方々から多くの方々にお声かけをしていただいて、工事期間中、例えば車での来庁はお控えくださいとか、当然、働きかけをいくわけですよね。それで、そのモデルを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"質問・要望","question":"山北ですか。山北町に行きました。山北町の庁舎そのものが耐震改修が済んでいて、そのモデルが役所の入り口にあるんです。地下に潜って、実際の免震施設はこうなんだということが目に見えてわかりましたので、となれば、この品川区役所も同じようなことを考えていただいて、くださいということを、これは２年先の話になるかもしれませんが、話だけしておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"土井委員","kind":"質問","question":"車の話は先ほどして、もっと端的な話です。同様に、議員の駐輪場は、相当の方が自転車を使っていらっしゃるので、それをどうするのかなという感じが若干ありますので、どこかにまたご指定をいただけるとありがたいなというふうには思っておりますが、いかがでしょうかというところです。","respondent":"阿部経理課長","answer":"駐車場は、先ほど申し上げましたけれども、８月から使えなくなります。ただし、今現在の議員の方の使える駐車場は確保してまいりますし、あともう１点は、駐輪場につきましても、当然のことながら確保してまいる予定です。台数は、今と同様の台数を確保してまいります。","id":"exchange-058"},{"speaker":"須貝委員","kind":"提案","question":"そこで商店街のために、たしかこの近くに駐車場、駐車できるスペースを、イトーヨーカドーのあそこがいっぱいになったために、商店街で使うということでそこに設けてありますが、今、このスペースだと、一般区民の方が例えば殺到したときに、何か会合があってほぼ使えないと思うので、そちらも利用できるような何かそういう仕組みも考えられないのかなという、ちょっと提案ですが、何か障害とかはありますか。","respondent":"阿部経理課長","answer":"それで、朝出ますと、そこがあきますので、来庁者の方は、そういう庁有車のスペースも使いながら、有効活用しながら、来庁者の方の駐車に対しては対応していきたいと考えています。","id":"exchange-059"}]},{"id":"topic-06","title":"４番目、東京海区漁業調整委員会委員選挙","agenda":"４番目、東京海区漁業調整委員会委員選挙","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"東京都の選挙ということだと思うのですが、大体、費用的にどれぐらいかかっているのでしょうか。","respondent":"早津選挙管理委員会事務局長","answer":"ちょっと資料はあれですが、人件費込みで１００万円ちょっとぐらいだったと思います。それで、全額、東京都から区のほうに参ります。","id":"exchange-060"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"意見","question":"あるいはまた、５時以降ですので、運転手の方々の仕事量の関係でも、改めるところは改めるべきではないかなと思いますので、その点についてどうなのかというのをちょっと、考え方を。","respondent":"須藤委員長","answer":"わかりました。委員会の委員の皆さん方のお申し出、事務方によって、２回運行せざるを得ないという状況であれば、またちょっと今のご意見等もありますので、考えていきたいと考えています。","id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"私は、現地解散にすれば問題ないと思うし、現地解散になれば、帰りのバスの便が空っぽで帰っちゃうということになるわけですから、それはそれで１つの選択肢だし、あるいは１回に限ってやるということも合理的でいいかなと思うんだけれども、２回もというののは、私たちの希望という点でも、あったにしても、私はやめるべきじゃないかなというふうに思いますので、ぜひそういう方向で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/917943?Template=document&Id=1790#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":71970,"voices":189}},{"id":"h20-20080625-14","meetingId":"h20-cm06","date":"2008年6月25日","dateIso":"2008-06-25","committee":"行財政改革特別委員会","time":"午前１０時０２分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員長","kind":"提案","question":"今後の委員会運営について、前回の委員会において皆様からいただきましたご意見・ご要望を踏まえ、先日理事者の意見も伺いながら、正副の間で調整をさせていただきました。大まかでありますが、１年間のスケジュールを立てましたが、調査・研究が深まりますように、事前に資料要求も含めて提案等ございましたらご発言をしていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"今、これからの流れというところでご説明いただいたんですけれども、この後、保養施設なんかの委託契約というところでしょうか、その辺での審議をしていくということですが、この保養施設もそうなんですけれども、あらゆる形で委託契約が行われていると思います。品川で実際にどういう形でどういうところに委託契約がされているのか。","respondent":"飯沼委員長、阿部経理課長","answer":"わかりました。正副で調整します。本日の日程に入ります。例えば工事に関しましては、予定価格が１３０万円を超えないものにつきましては随意契約ができるとされておりますけれども、先ほど申し述べましたとおり、私どもでは工事の請負、物品の購入、委託等、すべての契約に対しまして。","id":"exchange-002"}]},{"id":"topic-02","title":"これより予定表の１ 特定事件調査を行います。「契約のあり方に関すること」","agenda":"これより予定表の１ 特定事件調査を行います。「契約のあり方に関すること」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとこの場では難しいというのであれば、次回以降などで具体的に数値で示していただくことは可能かどうか、お伺いしたいと思います。","respondent":"阿部経理課長","answer":"ただ、ものによりましては区内業者ではどうしても供給できない場合、例えば先ほどご説明いたしましたけれども、代理店制度をとっていて区内に代理店がない場合もありますし、あるいは工事の関係で、規模が大きい場合に、区内業者ではなくて区外の業者がとるということもあります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"すべてとなると難しいかもしれないんですけれども、実際どうなっているかというのがすごくイメージしにくいですし、具体的な数字で見ないと何ともつかめないので、例えば工事の案件はどうなのかとか、そういうできるところだけでもお示ししていただくことは可能じゃないのかなということを改めてお願いしたいんですけど。","respondent":"阿部経理課長","answer":"ただ、全件になりますと、工事につきましても６００件からありますので、それを全部洗っていくという形になりますので、時間はかかると思います。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"違う質問なんですけれども、お伺いしたいのは、自治体が発注する多岐にわたる小規模工事を中小企業に回して仕事の確保や地域おこしをするという、いわゆる小規模工事等希望者登録制度というのが全国の自治体に、もともとは埼玉での運動で始まったように伺っているんですけれども、このような制度というのは品川区ではあるのかということと、もしあるのであれば制度の説明と。","respondent":"阿部経理課長","answer":"私どもとしては、一番後ろのところに東京電子自治体共同運営サービスというところをとっておりまして、指名業者になる場合にはここで登録をするという制度をとっておりますので、今おっしゃった小規模工事の登録方法はとっておりません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"小規模工事等希望者登録制度という、その精神というのが、今おっしゃったその制度でカバーできるのかどうかというのをちょっとお伺いしたいのと、あと、サービスに登録している業者に「こういう仕事がありますよ」というところで、いろいろな仕事の募集がかかると思うんですけれども、その対象というのは工事だけなのか、物品購入なども含まれているのか、もし工事だけということであれば。","respondent":"阿部経理課長","answer":"３０万円未満のものにつきましても、随意契約ではありますけれども、それにつきましても特定の業者に偏るというようなことはございませんで、そういう意味では小規模の方につきましても受注機会の拡大を図っているということは適切に行っております。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"事業部とか、内容で言っていただいてもいいんですが、どういうところが業者推薦として多い種別なのかということを教えてください。","respondent":"阿部経理課長","answer":"委託の業者推薦の件ですけれども、これにつきましては、例えばコンピューター関係のもので、ソフトウェアが決まってずっと使ってきているもの等もありますし、あるいは先ほどちょっとご説明しましたけれども、委託につきまして、プロポーザルで決める場合があります。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"そうしないと、単年度で変わっていくということになると、次の年につなげていきたいというような事業を委託された場合には、受益者となる区民にとっても不利益があると思うんですが、そういう場合には、契約の仕組みとしてはどのようになっているんでしょうか。","respondent":"阿部経理課長","answer":"先ほど申し上げなかったんですが、総合評価も含めまして単年度というのはございませんので、その中で当初のモニタリングをして、よければ次年度もやるという形をとっておりますので、そういう意味では質の確保は十分されていると考えております。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"その部分で業者推薦４１％ということなんですが、今みたいなケースでの随意契約というのがこの中でどのぐらいの割合を占めているかということと、先ほど第４号の方の該当なしというので、近隣セキュリティシステムの、ものづくりのところの契約というのはこういう部分ではなかったんでしょうか。","respondent":"阿部経理課長","answer":"もう一つ、先ほど来から出ている第４号ですけれども、先ほど申し上げたとおり、総務省令で定めるところの普通地方公共団体の長の認定を受けたものということですので、今おっしゃっているものがこの認定を受けているのかどうか、それはちょっと把握してございませんので。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"先ほど安藤委員が質問していた区内業者への発注というところで、先ほど課長の方から、４,０００件からあるのでまだ精査をしていないので、どれぐらい区内業者に行っているのかわからないというお話があったんだけれども、何でその辺、厳密に精査をしないで区内業者優先という立場に立っていると言えるのか、その辺がいまいち、先ほどの説明だとわからなかったので。","respondent":"阿部経理課長","answer":"なぜまれなのかといいますと、先ほど申し上げたとおり区内の業者では供給ができない場合、あるいは、工事の規模でＪＶを組めばあれですけれども、区内の業者を第１グループにできない場合、これは企業の格付けですので、そういう場合は区外の業者になるということです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"要するに、区の方針の中にある区内業者を中心にして、きっちり仕事を回していくんだという立場に立ったときに、「こう思っています」という話ではなくて、数字をきっちり示せるような中身をつくってほしいんです。とりわけ、今、４,０００件からあるというんだけど、逆に言えば、区外はまれですよというのであれば、数字としてはすぐにわかると思うんですけれども、どうなんですか。","respondent":"阿部経理課長","answer":"今申し上げましたとおり、４,０００件をすべて当たらなきゃいけないわけですね。例えば、どれが代理店制度を採っているかというのはわかりません。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"お示しくださった表について幾つかわからない点があるのでお聞かせ願いたいんですが、２ページ目の随意契約、今の議題になっているところですけれども、これはそれぞれに工事・物品・委託と、合計の件数含めてそれぞれ件数が示されておりますけれども、とりわけ業者推薦のところですとか、３０万円未満の随意契約のところですとか、この辺。","respondent":"阿部経理課長","answer":"申しわけございませんけれども、どの業者がどれだけとっているか、あるいはどれだけ契約しているか、それは詳細は持っておりませんので、この場でご答弁はできません。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"私はこれが随意契約かどうかちょっとわからないところなんですけれども、これは工事に属するのかな。これは随意契約なのかどうなのかわからないので、その辺も含めてなんですけれども、そういった工事、設計そのものは１件ずつに数えられていくのかどうか。その辺も教えていただければと思います。","respondent":"阿部経理課長","answer":"今、ＮＰＯの話がございましたけれども、２者と契約しておりまして、その場合には、ここの表で申し上げる業者推薦ということでとっております。件数については１件１件です。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、今の例で話させていただいているけれども、業者推薦というところで工事の方は３５件ですか。そうすると、この３５件のうち、ＮＰＯに発注をされた件数というのは何件なんですか。","respondent":"阿部経理課長","answer":"工事ではなくて設計の方ですので、委託の６４１件の中に含まれるです。そこに何件かというのは、今は詳細には持っておりませんので、この場ではご答弁できませんので、ご理解願いたいと思います。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"小規模の設計ですとか工事管理ですから、この委託の６４１件のうちかなりの数に上るのかなと思うんですよね。そうすると、委託の部分で言えば６４１件になっていて、このうち委託を受けている業者というのは、単純に想定をすれば相当絞られていくのかなというような気がするんですよね。ぜひ、その辺の数字についても資料として正副のところにお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"あるいはそういう経験が蓄積されているのかどうかということをお伺いしたいと思います。最後に随意契約についてなんですけれども、これはすべて３０万円未満の契約ということでよろしいでしょうか。３０万円を超えないものが２,０３３件集まって、平均が２９万９,０００円ということは、ほとんどのものが３０万円ぎりぎりのものばかりが２,０００件集まっているということなんでしょうか。","respondent":"阿部経理課長","answer":"次に１点目の電子入札の件ですけれども、現在、１,０００万円以上のものにつきましては電子入札を行っておりますが、電子入札をどこまで広げていくかというのは今後の検討課題だと思っておりまして、見積もり合わせにつきましては。","id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"コンピューターなどのメンテナンスに関しては、リース業者などの複数入札、そこまではいいんですけれども、要は、こういう業者にとっては、最初に入札するときには安く入れておいて、その後、当然のように発生するメンテナンス料で稼ぐというのが一般的なビジネスモデルになっていると思いますので、そこをいかに適正価格を維持するか、その辺の工夫をお伺いしました。それも教えてください。","respondent":"阿部経理課長","answer":"システムの件につきましては私も十分把握しておりませんので、それは今後、いろいろなところで精査をしながら適正な価格維持に努めてまいります。","id":"exchange-017"},{"speaker":"阿部委員","kind":"質問","question":"設計について含まれていないというのは、あえて外しているんですか。あってもいいのかなと思ったんですけれども、いかがでしょうか。","respondent":"阿部経理課長","answer":"設計につきましてはまた別途、それは評定ということではないかもしれませんけれども、果たして適切なのかどうか、それは所管課の方で十分に調査をしているというふうに考えております。","id":"exchange-018"},{"speaker":"阿部委員","kind":"意見","question":"工事評定をされているというのはすごくいいことだと思うんですけれども、工事だけではなく、設計に対しても、実際にできてみて本当にそれがよかったのかどうかというのを振り返ってみる視点も必要だと思いますので、今の仕組みに乗らないのであれば、何らかの段階でそういう振り返りもしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"渡辺委員","kind":"質問","question":"１点お伺いします。随意契約の中の内訳なんですが、委託契約がほぼ該当すると思うんですが、単年度予算の原則の中、ぱっと今思い浮かぶ中で、清掃だとか警備だとか、それぞれのビルや何かの保守管理の契約の年数のあり方で、原則だとか基準に関連して伺えればなと思います。","respondent":"阿部経理課長","answer":"ただ、総合評価のものにつきましては、先ほどちょっと説明をいたしましたけれども、モニタリングというものをやっておりまして、その施工業者が施工能力が十分であって、なおかつ仕様書を十分に満たしているか、その辺をモニタリングしまして。","id":"exchange-020"},{"speaker":"浅野委員","kind":"質問","question":"例えば、時価が１００とした場合、１割なのか、２割なのか、もっと低いのか、そういうような腹積もりというのが区の方にあるのかどうかということを１点お伺いしたいのと、あと、例えばこのようなものは、あるとすると売り込みとかそういうことが多いのかなと思うんですけれども、例えばそのような調査ですとか、業者からのアプローチとかいうものが実際にあるものなのかどうか。","respondent":"阿部経理課長","answer":"ただ、一つ考えられるのは、大量に在庫を抱えた場合に在庫処分で入れるという場合は、多分ここに掲げてあるような「著しく」ということに該当するのではないかと考えています。ただ、私は４月に来たばかりですけれども、記憶している限りでは、ないというふうに聞いております。","id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"大量在庫処分という例を挙げられましたけれども、これは探しに行ってもということはないんですけれども、想定されているとすると、そういうような、ある意味では売り込みみたいなものを想定されているのか、それとも市場調査を常にして、そういうような業者がいないかというようなことを研究されているのかということをちょっとお伺いできればと思います。","respondent":"阿部経理課長","answer":"私どもとしては、会社の状況はどうなのかというのは絶えず見ておりますけれども、ただ、在庫処分と区が必要なものと合致すればそういうこともありますけれども、そこまではなかなか細かく調査できないというのが現状です。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"そうした場合、平成１９年度で大幅に変更があったというようなものが、ここでは何かあるんですか。","respondent":"阿部経理課長","answer":"金額ベースでも、平成１８年度は件数としては４,０２５件の２０３億円でございまして、今年は４,０２２件の１９９億円ですので、それほど大きな変動はないと考えています。","id":"exchange-023"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、当委員会で見ていくときに、随意契約の委託というところが、数的にも金額的にも一番大きくなってきているので、そのあたりをひとつ勉強していくことが必要かなと思っています。それから、平成１９年度の事例で幾つか１号、２号、３号で数字を出していただいているんだけれども、この事例はどういうふうな形でチョイスしたのか。そのあたりはどういうことになっていますか。","respondent":"阿部経理課長","answer":"これは金額ではなくて、一覧してわかりやすい、表書きと対した場合にわかりやすいような事例を記載しているというものです。","id":"exchange-024"},{"speaker":"須藤委員","kind":"意見","question":"品川区で開発したまもるっちというのがあったよね。あれが２号に該当するのか４号に該当するのかなという思いがちょっとしたんだけれども、あのあたりは、品川区がベンチャーとしてやってきたような品物なので、これは該当なしと。昨年は契約のところでいろいろあったので、どういう順序でやられたのかなと思って。","respondent":"阿部経理課長","answer":"というのは、最初に申し上げましたように、４号の場合には、総務省令で定めるところによりまして、地方自治体の長の認定を受けた者というふうになっておりますので、その供給した業者が、多分この４号に該当するものというふうにはなっていないと思います。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"電子入札の対象でもないということになると、どういうふうに「仕事がありますよ」と中小企業に周知をしているのかなというのが見えないので、そこら辺、説明をお願いしたいんですけれども。","respondent":"阿部経理課長","answer":"見積もり合わせの件ですけれども、これは申し上げましたとおり３０万円以上のものについてやっておりまして、なおかつ、見積もり合わせにつきましては、参加の機会の拡大ということで、当然ランクの下の方を中心にしてやっておりますので、そういう意味では、今。","id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"３０万円以上ということなんですけれども、そういういろいろな仕事がある。もちろん、先ほどの電子自治体共同運営サービスだとちょっと金額が高過ぎるので、そういう対象でもないし、また、町場の零細の方と接していると、インターネットすらも全然わからないという人もいる中で、品川区の中小零細の方の実態に合わない面もあるんじゃないかというふうにも思いますので、そこら辺どうなのかなと思います。","respondent":"阿部経理課長","answer":"その場合でも電子自治体共同運営サービスを使いながら中小企業者の受注の機会の拡大を図っているですので、委員おっしゃったところに改めて再度登録をするという考えは持ってございません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"そういう登録制度があれば、「そういうお仕事がある場合だったら私たちも名乗りを上げたいんだ」という人たちが登録をしてあれば、そこに送られるというようになると思うんですけれども、そこはどうなんですか。ファックスを送っている先というのはどういうふうに決まっているんですか。","respondent":"阿部経理課長","answer":"委員おっしゃった、例えば１人とか小人数でやられているところにつきまして、原則は、私どもとしては電子自治体共同運営サービスで登録しているというふうな認識がありますけれども、万が一そういうことがないという業者につきましては、そういう入札等には参加できない場合でも。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"それ以下の小さな小回りがきくようなお仕事とかというのは対象外になってしまっているんじゃないかと思うので、登録をされてもそういう仕事はお知らせとして回ってこないんじゃないかと思うんですけれども、１,０００万円以下のことに関しても、様々な仕事があるのでありますから、幾らまでにするのかというのは非常に難しいところなんですけど。","respondent":"市岡総務部長","answer":"これは例えば、保育園で「ここのエアコンが壊れたのでちょっと修理をしてもらいたい」というときに、大規模にいろいろな業者にファックスを送ったりということはありませんで、町の一番近いところの電気屋さんに。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"よくわかりました。ありがとうございました。ほとんどのところは電子自治体共同運営サービスに登録をしているということであったんですが、ほとんどというのはかなり１００％に近いということでよろしいんですよね。そこら辺の実態といいますか、最後にちょっとお伺いしたいんですけど。","respondent":"阿部経理課長","answer":"登録している事業所がどれだけかというのはわかりますけれども、その割合までは、正直言って把握してございません。登録の数ですけれども、工事につきましては、区内の業者では２９９、物品については３５６です。","id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"この３０万円以下の物品の契約に対して２億円ちょっとの金額が表に示されているんですけれども、例えば消耗品でお聞きしますけれども、実績から見て「今年度はどれぐらいにしようか」という見直しをされているのか。その点をお聞きしたいと思います。","respondent":"阿部経理課長","answer":"ただ、今の中で、私どもだけで消耗品の見直しというのはなかなか難しい観点もありますので、それは庁内全体の中で省エネルギーという観点も含めまして、消耗品の使用を見直しして、結果、私どもの努力と、庁内の各課の努力を合わせまして。","id":"exchange-031"},{"speaker":"菊地委員","kind":"意見","question":"例えば人が入れ替わるごとに畳を替えなくちゃならないとか、壁紙を替えなくちゃならないとか、そういうときの工事というのは、指定管理者によってきっと契約内容がそれぞれに違うんだと思うんですけれども、こういう区営住宅、区民住宅の工事というのはどういう契約方式がとられているのか、そこだけちょっとお聞かせ願えますか。","respondent":"阿部経理課長","answer":"今委員おっしゃったようなことは、今、契約書がございませんので、ちょっとわかりませんけれども、指定管理者がやっていると考えています。","id":"exchange-032"},{"speaker":"菊地委員","kind":"意見","question":"区民住宅でいうと、借り上げ型がありますからオーナーさんがいらっしゃって、当然そこはそのオーナーさんが管理をしていくということになるんだと思いますよね。区外の畳屋さんがよく来ているよ」という話を聞いているんですけれども、この辺の指定管理者に対する指導というのは、契約内容の中に明確に区の考え方が打ち出されているのかどうか。そこをお聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"昨年度、平成１８年度の区営住宅の総括シートを見ますと、指定管理業務の概要の中に、「区民住宅・区営住宅の保全、修繕および改良に関すること」ということで、業務内容が決められておりますので、その中で指定管理を請け負った業者が。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問・要望","question":"それからもう一つ、これはいつ聞いたらいいのかわからないんですが、前回の委員会で契約全般に関しての質疑がありましたので、そのときに、下請二法との関係で国会の付帯決議のところをお聞きして、次回の委員会にでもという話があったんですけれども、そのときに、二次下請けですとかの契約額とかといったことについて、品川区として。","respondent":"久保田行財政改革担当課長、阿部経理課長","answer":"先ほどの指定管理者のところで、もう一度詳しくご説明いたしますけれども、区民住宅、区営住宅につきましては、品川宅建管理センターの方が指定管理の業務になっておりますので、まさに品川区の宅建ということですから。付帯決議の件ですけれども、私どもは申しわけございませんが十分把握しておりませんので、この場で答弁は差し控えします。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問","question":"これは前回の委員会でお聞きしたときに、課長の方から「把握していないので」というお話だったんですよね。「そういう決議なんかありませんよ」という話なのか、それとも、「あるけど別に位置付けはしていませんよ」という話なのか。今のお話だとちょっとわからないので。","respondent":"阿部経理課長","answer":"前回のお話を受けて、いろいろ探してみたんですけれども、手元に資料をそろえることができませんでしたので、今のような答弁をいたしました。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"今の菊地委員の質問に関連してなんですけれども、指定管理者は住宅関連だけではなくて、今、いろいろなものが指定管理者制度になっていると思うんですけれども、どこが管理しているから区内業者だろうということではなくて、例えばその指定管理者が何か物品を調達したりとか、あるいはメンテナンスの仕事をどこかに出したりするときに。","respondent":"久保田行財政改革担当課長","answer":"区内業者を使うように指導しているかというお話なんですけれども、指定管理の業務につきましては、区民住宅のもの以外にも様々なところで指定管理という形を使っておりますので、一律に区内業者をという形は、今のところでは確認できませんので。","id":"exchange-036"},{"speaker":"阿部委員","kind":"提案","question":"それはむしろ要望というか提案になると思うんですけれども、その考え方だけでもちょっと教えていただければと思います。","respondent":"福田企画部長","answer":"と申しますのは、なぜ区内業者を優先するかと考えますと、これは区内業者を育成するというだけではなくて、地域における経済波及効果を期待するということが一つですので、そう考えますと、単に品川区だけではなくて、品川区が指定管理関係を結んでいる法人等にも。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"今の指定管理者なんですけれども、区内業者を第一義に育てていったりというのは理解するんですけど、そもそも指定管理者の制度というところで、そうであれば、契約するときにそれなりの、そこは民間ノウハウとかいろいろなところで財源も含めて契約するわけで、そういう部分において品川区がきちんと上乗せというか。","respondent":"福田企画部長","answer":"したがいまして、区内業者を優先したとしても、契約にほとんど全部貫かれる三つの原則は貫かれるわけですので、その意味で、区が区内業者を優先する指定管理者に対して、新たに予算上の措置を講ずるというような関係にはないと思います。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"予算上の措置とかそういうことではなくて、制度そのものはそういうものだと思うんですね。だから、そこのところを検討するという視点をきちんと品川区が持っていないと難しいんじゃないかと。議会でもそのことがどうなのかということを問われているわけですから、そこが今、疑問だったなと思います。これから考えていかなきゃいけないかもしれませんが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"菊地委員","kind":"質問","question":"私もよく質問や何かの中で、区内で１００万円使われるとどういう経済効果があるかという話をしたことがありますけれども、今、企画部長の答弁がせっかくあったので、官公需と、それから区内経済の関係で、区としてどういう役割を果たしていくんだろうというところでもう少しあれば、ぜひお話をしていただければと思います。","respondent":"福田企画部長","answer":"品川区というのはこれだけ非常に大きな発注者側の存在ですから、それが例えば大井町の商店街ですとか、大崎の再開発なんかもそうかもしれませんけれども、そういう周辺地域にある程度の経済波及効果が見られるのではないかと考えておりますし、また、それを期待しているです。","id":"exchange-040"},{"speaker":"原委員","kind":"意見","question":"委託契約、多分いろいろな形で何パターンか、出せるもの、出せないものあると思うんですけれども、その辺のドラフトというのか、こういう素案みたいな形のものが２パターンか３パターンぐらいあると助かるということです。つけ加えますと、出せるもので結構なので、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/655011?Template=document&Id=5842#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":26661,"voices":98}},{"id":"h20-20080626-16","meetingId":"h20-cm06","date":"2008年6月26日","dateIso":"2008-06-26","committee":"街づくり特別委員会","time":"午前１０時０２分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林委員長","kind":"質問・要望","question":"前回、今後の委員会運営についてご意見をいただきましたが、理事者の意見も伺いながら、正副委員長で調整をさせていただきました。当委員会は、調査事項として八潮のまちづくりに関すること、安全・安心のまちづくりに関することの２項目について付託を受けてあります。今年度１年間、このような形で進めさせていただきたいと思いますので、よろしくお願いいたします。","respondent":"中山防災課長、片田建築課長","answer":"３つ目ですけれども、都民の地震災害に対する認識を深め、防災意識の高揚を図る、以上の目的で実施されているものです。ただ、東京都のほうは、さらに第１次から第３次まで路線を拡大してきた中で、区としてどのように考えるかということを今後引き続き検討していくわけですけれども、そういう内容を今回改めてしていきたいということで、これも同等に。","id":"exchange-001"}]},{"id":"topic-02","title":"日程に入ります。特定事件調査の安全・安心のまちづくりに関すること","agenda":"日程に入ります。特定事件調査の安全・安心のまちづくりに関すること","exchanges":[{"speaker":"南委員","kind":"質問","question":"２月から４月にかけて、１,９１０世帯を回って、本当に大変なことだったなと、説明を聞いて改めて思いました。お疲れ様だと思います。ですから、その背景には、資金調達というところが一つの大きなネックになっているのではないかと思うので、その辺についても、どういう見解を、今回の調査で持ったのか、策を練る上でも必要な部分だと思いますので、伺いたいと思います。","respondent":"片田建築課長","answer":"そういうことも含めて、いろいろな検討をしていきたいと考えています。必要に応じた施策の見直し等も、一定の期間の中での評価を踏まえて、計画にもきちっと反映することを検討してまいりたいと考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"それ以上のことというのがなかなか、課題が重過ぎて、大変なんですけれども、個人の財産を一定程度動かさなければいけないわけですから、私は建替え促進というか、従前居住者用住宅、ああいうものをつくって、入れてという、そういうやり方がいいのかなと思って、考えてみたりもするんですけれども、それはいろいろな状況があって、必ずしもそういうふうにいかないかなと思うので。","respondent":"片田建築課長","answer":"したがいまして、区としては、積極的なＰＲ活動を行うと同時に、いろいろな施策のメニューといいますか、高齢者の対応についても、高齢者は資産の活用等々を含めた何らかの検討ができないかとか、それぞれの区民の置かれた状況が違いますから。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"なかなか大変なんですけれども、ぜひ進めていただきたいし、地域を挙げて、そういう話し合いで進めていくということが大変大事なことだと思いますので、時間はかかる作業ですけれども、成果を一つずつ積み重ねていくことが大事かなと改めて思っています。そういうところも合わせて、次回以降もやっていくことになっていくんでしょうか。","respondent":"片田建築課長","answer":"というのは、個別訪問を毎年続ければいいという話ではございませんで、やはり事業をきちっと認識してもらうということが先ですから、事業の冒頭に先立って、そういう説明を行っていくということが効果的なのかなと考えています。","id":"exchange-004"},{"speaker":"山元委員","kind":"質問・要望","question":"今いろいろお話を伺わせていただきまして、本当に個別訪問していただいて、大変なご努力だと感じました。申し込んだものの、実際に審査の結果というんですか、そちらのほうが、具体的に何カ月とか、何日とかわかれば、教えていただきたいと思います。","respondent":"片田建築課長","answer":"したがいまして、順番についても、まず、町会長の日程とか、まずそういうお話を含めて、６６町丁目全部を一度に説明できるわけではありませんから、その町会の会議の日程等をお伺いしながら、それで逆に順番を調整していった上で。","id":"exchange-005"},{"speaker":"山元委員","kind":"質問・要望","question":"今、専門家が五、六人の方でとおっしゃっていたんですが、先ほど人数に対して、対応というか、私たちは申し込む側にしてみれば、すぐにでもやっていただきたいと思うんですけれども、五、六人というと、やっぱり２カ月、もう少し早くできないのかなと思うんですが、いかがなんでしょうか。","respondent":"片田建築課長","answer":"現時点でも、東京都のほうで、木造の診断ができる講習会みたいなものを行っていますので、そういう講習会への登録とか、そういう方の積極的な活用についての研究とか、そういうことも今後少し検討していきたいと、このように考えております。","id":"exchange-006"},{"speaker":"稲川委員","kind":"質問","question":"１点か、２点お伺いしたいんですけれども、地域危険度測定調査で、５年に１回、都がやると聞いているんですけれども、品川区、耐震支援の実績が、平成１６年からということで、いろいろやられているとは思うんですが、５年前とランキングという言い方はおかしいですけれども、さまざまな危険度があったんですが、変わったとか、外れた場所というのはあったんですか、この５年の間に見直された場所とか。","respondent":"中山防災課長、片田建築課長","answer":"それで２カ所になっているわけです。それから、火災危険度については、前回危険度５から４に下がったところが３町丁目、それから、４から５に上がったところが６町丁目ほどあります。いわゆる建築確認のときに、２項道路のセットバックというようなこともありますので、そういう支援を行いながら、現況のブロック塀について改善していただく、あるいはできるだけブロック塀よりも生垣のほうが望ましいわけですので。","id":"exchange-007"},{"speaker":"山内委員","kind":"質問","question":"専門家というのは、どういう資格を持った方かということを教えてください。これは専門家、やはり木造の耐震を診断される方が、同じ方なのかということを教えてください。例えば、第二京浜、それから、大きな道路では山手通りとか、品川区にはありますけれども、この辺の道路というものは、対象から外れるのか、それとも、今後、どういう流れになっていくのか、その辺を教えてください。","respondent":"片田建築課長","answer":"ただ、現在、都と区のほうでいろいろな課長会を通して、あるいは部長会の下命を受けたりして、どの路線を有効として考えるかと、あと東京都と区の役割分担、費用負担の問題、原則は緊急輸送道路ですから。","id":"exchange-008"},{"speaker":"山内委員","kind":"意見","question":"これはわかればでいいんですけれども、道路にある公共物というのがありますよね。例えば、電信柱とか、信号とかに対しての耐震というのは、これはわかればでいいんですけれども、これは区ではないんでしょうけれども、そういうものの耐震というのはどういう形でやっているのか。","respondent":"松代管理工事課長","answer":"そういったものに対しての対応というところで、さらに強度を増すような形で対応がとられているように聞いております。加えまして、さまざまな点での耐震化、そういったものを電柱、信号機、またそれ以外のライフラインについても今対応がとられていると聞いているところです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか教えてください。そこでなぜなんだろうと。この助成金というのは、住宅によってかかる金額が変わると思うんですけれども、大体どのぐらいの割合の助成を区で考えているのか、その助成金という、もともとの出どころ、それは品川区独自の金額なのか、それとも国とか、都の助成金がどのぐらい入っていて、区の持ち出しというのはどのぐらいあるのかということを教えていただきたいと思います。","respondent":"中山防災課長、片田建築課長","answer":"地盤の関係ですけれども、先ほどもちょっとご説明申し上げましたが、東京都の地盤は山地・丘陵地、それから山の手台地、沖積低地、谷底低地に分けられると申し上げましたけれども、台地および谷底低地は。促進計画に関連するご質問ですけれども、まず、促進計画の平成２７年度、期間設定ですけれども、実はこの期間設定については、国の方針が平成１８年１月２５日に、国土交通大臣による基本方針の概要という形で出されて。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"助成金なんですが、耐震診断はわかりました。建替えのとき、建替えはすると相当お金がかかると思うんです。改修で済むのであれば、改修でもやはりそれなりに、結局１００万円ぐらいはかかるんですかね、持ち出し、その家屋によっても違うと思いますけれども、１００万円ぐらいの、数百万円までいくのかどうか、ぐらいの持ち出しが必要になるわけですよね。そこは確認しておきたいと思います。","respondent":"片田建築課長","answer":"ただ、実際には診断を受けた方が、中には建替えたいという方もいらっしゃるわけですから、そこの中で、区としても何とか同じ金額、最低限ですけれども、それを出して、建替えを積極的に支援していきたいというようなことも一応考えた中で、実際には上物の費用としては。","id":"exchange-011"},{"speaker":"西本委員","kind":"提案","question":"よくわかりました。これは、全世帯数の何割ぐらいの方なのかなと、大ざっぱでいいんですけれども、そこで対象になっているところが１００％行けていると、個別訪問できているという進め方でよろしいんでしょうかということが１つです。それから、提案ですけれども、建替えとかがあったときに、もう財産をいろいろと考えていきたいという方もいらっしゃると思うんです。","respondent":"片田建築課長","answer":"ただ、いろいろな、国のほうとしても、高齢者の資産の活用とか、そういうことも含めてのリバースモーゲージみたいな考え方も一つは出してきているので、そういうことを含めて、高齢者の住宅問題等々との連携をとりながら、研究していきたいと考えています。","id":"exchange-012"},{"speaker":"西本委員","kind":"提案","question":"個人でできることというのは限られてしまうし、高齢になってくると、地震があったら、自分はどうなってしまうのかと、半分あきらめたような状況になるかと思うんです。そこは特にお店にくっついているんですね。そうするといつまでたってもシャッター通りの状況になるところですから、そういうところを踏まえてどんどん提案していくということができると、もうちょっと整備できるのではないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれの町丁目の状況については、実際議員も住んでいるし、一部職員も住んでいるし、まちの情報や、住民の声や、受けとめ方、率直なところを出し合って、実際の事業に結びつけていかないといけないわけですから、そこは特別委員会の中で、それぞれまちの状況を私も知りたいなと思っていますので、教えていただきたいと思っています。しばらくたってしまうと、また減ってしまう。","respondent":"片田建築課長","answer":"今、耐震シェルターというところについても、出来合いのものではなくて、やはり地元の工務店とか、建築士、あるいは大工の方の代表とか、そういう形で知恵を出し合っていただけないですかというような進め方で検討し始めているところがあります。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"建物の倒壊が何を生むのか。そこを絞っていかないと、情報を伝えるのも、確かにこういうパンフレットがつくられて、これはあくまでも事業の紹介だけであって、何が問題なんだというのをしっかり住民に伝えること、進めるに当たって、何を身近に感じていただくことが必要なのか、そこを示していくことが大事ではないのかと思ったので、そこをもう少し伺いたいのが１点。もう一つが、ギャップなんです。","respondent":"岩田まちづくり事業部長","answer":"ひどい人は何の準備もしないでそのままで逃げてしまったという、ですから、ここをどう変えていくかというのは、まさに十分検討していかなければいけない部分で、いよいよ我々も心理学の分野に足を踏み入れて、いろいろ対策、これはハードだけではなくて。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"特に何もしていない、どうしてこういう声が強まってしまうのか。やっぱり相手の気持ちも、今、防災意識も上げなければいけないわけですから、何をどうお伝えするのか、何を理解してもらうのか、そのポイントをしっかりとつかんだ上でやっていかないと、事業に結びついていかないと思うんです。一つの例でいうと、パンフレット的なものがあったらどうかと思うんだけれども、そこを教えていただけますか。","respondent":"岩田まちづくり事業部長","answer":"先ほど、担当課長が申し上げましたように、我々はいろいろな媒体を通じて、今回の事業、今年１月からＰＲをさせていただいています。先ほど委員がおっしゃったように、ケーブルテレビでも、特集番組もつくって、わかりやすく説明をしていますし、あらゆる媒体をやっています。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"２点伺いたいんですけれども、荏原地域には中原街道、第二京浜が通っているんですけれども、火災のときに、消防ポンプで消しにいこう、消防団がポンプ車で消しにいくにしても、あそこにある歩道橋が落ちた場合は何も通れなくなってしまうので、歩道橋について、今、バリアフリーの見地から、東京都で撤去する方向になってきているのかなとは思うんですけれども、耐震の強度検査なんかをしているのかどうか。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"加えて、今、学校周辺等に通学路として位置づけられて歩道橋があるものが多うあります。そういった観点から、やはり落橋等については、きちんと状況等を踏まえながら、慎重に対応していく必要があろうと考えているところです。補助２９号線絡みのお話ですけれども、私どもとしてなかなか議会で補助２９号線のことをはっきり申し上げることは、言いにくいんですが、現時点では、これは２区にまたがる都市計画道路ですので。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問","question":"２つ聞かせてください。簡単で結構です。アーケードの耐震化について、先ほど電線については警察云々ということで伺いましたけれども、このアーケード、民間特定建築物でも、多数の人が利用する施設に当たるのか、それとも地震による倒壊で、道路を閉塞するおそれのある建築物に該当するのか、それとも別のカテゴリーになるのか、それが１つ。","respondent":"片田建築課長","answer":"ただ、一般的なアーケードのつくり方としては、工作物ということではなくて、屋根がかかっていますので、当然一応建築物ということで、基本的には、つくる場合にも、構造計算をして、適切な対応をしてきているです。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"武蔵小山商店街のパルムは、昭和５６年前後だったと思うんです。そうすると、この昭和５６年以前というのに合ってくるのがありまして、ほかは中延、戸越、ほかのところも同じようなものだと思うんですけれども、往来が激しいから、仮にあれが崩壊して倒れる危険性が高いと思うんですけれども、それを区が主導になって指導されるのか、都が主導になって指導されるのか、主になる指導主体はどこなんでしょうか。","respondent":"片田建築課長","answer":"それについてどういう通知文を出すかというのは、２３区と東京都を含めて、やり方について今検討していますけれども、もし、お話があれば、助言なり、アドバイスをさせていただければと考えています。","id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"今後の委員会についてなんですけれども、今日は品川区の事業を見ましたけれども、お話の中でも、他の動きが若干ありましたけれども、２３区の中で、耐震診断だったり、補強だったり、それぞれ独自のやり方もあるのかもしれないんですが、ＰＲ方法も含めて、２３区の事業の様子、そういう資料が出てくるといいのかなと思ったので、その資料をお願いしたいと思ったんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"西本委員","kind":"意見","question":"密集地域とかはよく行くんですけれども、逆に整備されているところも、比較で、区内にあるのかどうかわからないんですけれども、全然ないとしようがないんですけれども、ここまで密集ではなくて、こういう感じになると、二葉三丁目、二葉四丁目は、という実態がより鮮明になるような感じ、区内にないというのであれば、ほかの区が、近隣でそういうのがあれば、そこを見たいと思うんですけれども、なければ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/208457?Template=document&Id=6368#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":40380,"voices":51}},{"id":"h20-20080722-6","meetingId":"h20-cm07","date":"2008年7月22日","dateIso":"2008-07-22","committee":"区民委員会","time":"午後１時０２分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","topics":[{"id":"topic-01","title":"平成２０年度地区総合防災訓練・職員防災訓練","agenda":"平成２０年度地区総合防災訓練・職員防災訓練","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"地区総合防災訓練で、共催のその他関連団体ですけれども、どんな団体なのか教えてください。","respondent":"斉藤防災安全担当課長","answer":"共催のほうですけれども、品川区、消防署、警察署、消防団、医師会等、品川区地域防災計画で防災会議の委員になっていただいている機関がメインです。さらに防災計画に基づきまして協定をしていただいている獣医師会、医師会、こういったところになっております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"災害対策の意識というのは、すごくあると思うんですけれども、例えば多くの一般区民の方がこういう訓練に参加できたほうがいいと思うんですけれども、そのためにはどのような道が用意されているのか。","respondent":"斉藤防災安全担当課長","answer":"さらには、町会の掲示板にも掲示する予定にしております。さらに、訓練当日につきましても、各地区ごとの防災行政無線で訓練開始の案内をしましたり、町会の方々が町内を回って訓練を呼びかけたりという形でやってきております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"組織に所属していない人などは、地域の防災組織に入って参加するということなのか。広報を見た方が参加して、訓練の様子を見るだけでも勉強になると思いますので、そういう形の参加になるということなのでしょうか。","respondent":"斉藤防災安全担当課長","answer":"その集合体が地区の防災協議会になりますので、一人の方で町会員が地区協議会と関係ないのかということではなくて、そこに住んでいらっしゃれば町会に加入していなくても町会の母体として区民組織はつくられておりますので、参加資格といいますか。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"普段、忙しくて、特に働きざかりの方は地域の中に普段から関わりにくいけれども、防災には興味があるという方をどんどん巻き込んでいくことが大事なのかなと思いますので、今までもやってきたと思うんですけれども、さらにそういうところへの工夫は町会の方とも、あわせてやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"前回、温暖化対策について調査項目の提案がありましたけれども、今回は盛り込まれていないということです。それから、所管事務調査項目にものづくり産業の支援と環境への取り組みについてとなったんですけれども、ものづくり産業の支援は該当しているんですけれども、それ以外は該当していないということで、今回出された視察案の思いを伺えればと思います。","respondent":"本間委員長","answer":"温暖化等、環境問題は今回の部分から取り込みはできませんでしたが、別の形で検討していきたいと思っています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"と言いますのは、現実に区内の中小ものづくり企業の支援策を考えるにあたって、実際に直面している個々の問題があると思うんですけれども、もちろん個人としてもやりますけれども、委員会として区内の現状をつかんで、初めて必要な調査になっていく面もあるんじゃないかということで、あわせてぜひ区内の現状を委員会として把握していくこともやるべきじゃないかと思うんです。そういう点ではいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"いろいろな提案に対して、やはり委員会の中できちんといろいろな角度からより深めていくことが大事だと思いますので、そういう思いで今言ったわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/487097?Template=document&Id=2524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":6092,"voices":29}},{"id":"h20-20080722-7","meetingId":"h20-cm07","date":"2008年7月22日","dateIso":"2008-07-22","committee":"厚生委員会","time":"午後１時０３分～午後４時３８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件抜き出しています。","topics":[{"id":"topic-01","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"本件につきまして、まず、車いす同乗車両の件ですけれども、車両の購入で３０万円、改造が１５万円ということなんですけれども、この助成金の目安というんでしょうか。例えば、全体の費用がどのぐらいかかるから何％とか、そのような目安があるのか、どうかということについて、ちょっとお伺いしたいと思います。","respondent":"高橋障害者福祉課長","answer":"目安ということでは、一般車両を購入するものと、市販されている車いすで製造ラインに乗っているものの差額が大体３０万円、改造については１５万円というような感じで、一般的に流通しているものを参考に、その一部助成するという形でしているものです。","id":"exchange-001"},{"speaker":"浅野委員","kind":"質問","question":"前回、話が出た中ですと、やはり個人の財産についてどこまでお金を投入するか、助成という形にするかということも、一つの問題だと伺っているところです。その上で、やはりこういう形であれば、助成制度というのはどうかという意見もあってしかるべきかと思うんですけれども、まだそこまでいってないような気がします。何しろ高い車両だということもあると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"確認","question":"前回からの審議過程と、今の浅野委員のお話に沿う形で思っております。その中での確認なんですが、リフト寝台付タクシーをお勧めをする中で、現在、稼働している率というんですか、例えば、今回のケースのような方がご希望されたときに、９割、１０割に近く、目いっぱいだとほんとうに使えないんですが、そのようなことがあるのかどうか。","respondent":"高橋障害者福祉課長","answer":"現時点で、リフト寝台付タクシーで予約できなかったものは、４月で２０件あります。ただ、このところについては、日にちがぶつかっているものです。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"確認","question":"利用制限というと表現が変かもしれないんですが、このようなケースの方が実際に申請をされて、断られるというようなケースはないという確認のために伺ったのが１点。それから、今、稼働率の点でもう１点伺いたいのが、常識の範囲内で、何日か３日なり５日なりの希望日を出して、それが全部だめというケースは想定されるのか。","respondent":"高橋障害者福祉課長","answer":"障害が重たいから利用ができないかと言われると、そういうことではございません。基本的に、ストレッチャーに乗り、隣に介助者がいれば、運転手そのものは運転業専門に行っている者ですから、安全に病院、もしくは目的地まで運行ができると思います。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"何点か、お伺いします。現在、区には車いす用の車両については、助成制度がありますが、これの対象になっている方というのは福祉タクシーは使えないんでしょうか、それとも使えるんでしょうか。１点、教えてください。","respondent":"高橋障害者福祉課長","answer":"福祉タクシーと車の助成の部分については、両方ともダブルで利用可能です。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"多分、そのようなことだと思いました。つまり、車いすを利用されている方は、ご自分の助成を受けた車で外出することも、福祉タクシーを使うことも、選ぶことができるわけですね。この件につきましては、車いすの助成自体も、実は、区として問題があるというとらえ方なんでしょうか。ちょっとその考え方だけ教えてください。","respondent":"高橋障害者福祉課長","answer":"品川区としては、車いす同乗車両のみは、一応社会外出の支援ということで助成を考えて制度をつくったものですので、その辺については、今後の課題というような形かなと考えています。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"今後の課題と言われた部分、もう少し詳しく教えてください。","respondent":"高橋障害者福祉課長","answer":"重度の障害者、医療行為の重たい方に関する支援を、障害のほう、いわゆる福祉のほうで支援するかどうかというのは、その辺の境目につきましては、まだまだ検討する余地があるのかなと思います。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"今のご発言は、つまり、福祉の範囲として対応できるかどうか、検討課題であるとともに、行政の中で、医療分野とも連携しながら検討を進めていただけるということなんでしょうか。そうであると、大変ありがたいと思いますが。","respondent":"高橋障害者福祉課長","answer":"したがいまして、医療が重たい方について福祉のところで、ということになると、安全性の確保を重点に考えれば、現時点の事業の推進が適切かと、私のほうは考えております。","id":"exchange-008"},{"speaker":"阿部委員","kind":"意見","question":"例えば、重度の方の施設をここでつくれということではなくて、ここはあくまでも移動手段の一つである車について、さらに、その一部分を助成をする仕組みをつくってはどうかということですので、そういったバランスも考えて、区でできることを前向きに考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"車いす同乗車両助成事業実施要綱を見せていただいて、その中でも、社会生活の利便と生活圏の拡大ということが、この助成の目的になっていますよね。ちょっと確認なんですけれども、こういうリフト寝台付タクシーのご利用の件数というのは、こういうケースの要望はかなり多いんでしょうか。ですから、そういう点で、どうしてもストレッチャー付でなければいけないという方は、数が多いんでしょうか。","respondent":"高橋障害者福祉課長","answer":"昨年、利用人数が１,７５９件のうち、７３件の方がリフト寝台付タクシーをご利用いただいたという状況です。ほかの方については、すべて車いすでご利用いただいています。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、先ほど、前のほうの質疑にあった中に、先に予約しておけば、何こまか日にちを言えば大丈夫だというお話がありましたけれども、そんなことをしなくても、例えば決まっていても、この日のこの時間というのは変更するということも可能ではないんですか。","respondent":"高橋障害者福祉課長","answer":"車いすのみの同乗車両につきましてのタクシー運行ですが、昨年１０月から１台プラスしておりますので、車いすのみの利用の方については、そちらをご利用いただき、寝台で利用されないといけない方については、リフト寝台付タクシーを優先してご利用いただいているという状況です。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"この請願を出された方は、区の窓口にもたびたびいらっしゃっているようなんですけれども、区のほうとはコンタクトはよくとれているのか、その辺をお伺いしたいと思います。","respondent":"高橋障害者福祉課長","answer":"必要に応じて訪問ということもありますので、ご本人の状況もありますので、その辺については、訪問したとか、しないとかいうことはちょっと申し上げられません。窓口では対応しておるところです。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区民で、区に実際に相談に見えたり、訪ねればすぐに行けるところに、困難を抱えていらっしゃる方がいたら、やはりその辺を取り上げてできる限りのことをする、また、都や国に対しても、こういう状況の人に対して手を差し伸べるようにという働きかけをしていくのが、一番身近な自治体に求められていることだと思うんですが、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"この方の生活そのもの、また、お子さんに対する思いというのは十分に承知しておりますが、現段階で、この単独のみを助成するということではなくて、障害福祉施策全体を考えた上で制度設計しているもので、単独での困難性はわかりますが。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状的に受けられていないものも、個別で相談があればできる部分もあるのかもしれませんけれども、インフルエンザなんかは、現に受けられていないわけですから、一人ひとりに合わせて、必要なものが受けられるように、これはそんなにたくさん予算が要るわけではないし、命を守るということでは大事な拡充であると思うので、ぜひこれは受けとめていただきたいなと、これは質問ではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"ちょっと聞き取りづらかった点がありましたので、申しわけないんですが、何点か確認を。先ほど、リフト寝台付タクシーの件で、去年の秋口に１台追加したから４台ということでしたが、では、この事務事業概要に書いてあるリフト寝台付タクシーが２台で、車いす対応型が１台の合計３台ということですか。さっき何か４台とおっしゃったように聞こえたので、その点の確認が一つ。","respondent":"高橋障害者福祉課長","answer":"４台と申し上げたのは、社会福祉協議会で、車いすに対応した移送サービスを行っているのが、今年の４月から、２台から４台に増えたです。私どもが運行しているリフト寝台付タクシーは２台で、昨年１０月からは、車いす対応を１台増やしまして、全部で３台で運行している状況です。","id":"exchange-015"},{"speaker":"堺委員","kind":"意見","question":"今のリフト寝台付タクシーのほうですが、１,７５９人のうち７３件。ということは、これは使った件数であって、使っている人の数、お１人が７３回使ったのか、２人が使ったのか、その辺はわかりますか。何人がご利用されているのか。","respondent":"高橋障害者福祉課長","answer":"申しわけございません。月々の利用人数を積み上げていったもので、同じ方が毎月利用しているのか、１カ月に一遍なのか、同じ月に３回なのかという、利用人数をチェックしているものではないので、ちょっとこの辺についてはわかりかねます。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"というのは、前回、２４日の当委員会で質疑がありましたね。そういう面からいくと、さっき７３件とおっしゃっていたのは、例えば９人とすると、１人が８回使うと大体７３人になる。だから、いわゆる何人が品川区でご用意されているこの車を利用されているのかなということを把握されたほうが、今後の事業展開において、具体的な数字が見えてくるかなという気がするんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"私が、前回申し上げました３人から９人というのは、月によって一番少ないときで３件、一番多いときで９件利用しているという件数であって、堺委員がおっしゃっている、この７３件は利用人数なのかというところは、ちょっと私どもでは、今のところつかんでおりません。","id":"exchange-017"},{"speaker":"堺委員","kind":"確認","question":"ここで先ほどから悩みの中で、ちょっと確認しておきたいと思う点がありましたから、お伺いしました。そういう中で、現在、同じ車でも、同乗車両については、購入助成が３０万円で改造助成が１５万円と。仮にこの方が、さっき申し上げました、車いす同乗車両と同じような助成、３０万円という部分なんですけれども、そういうのは考えられるのか、考えられないのか、ちょっとその辺、いかがなんでしょうか。","respondent":"高橋障害者福祉課長","answer":"ですので、現時点で、金額だけの問題で拡大したらどうかというところでは、ちょっと今、即答はできない。したがいましてストレッチャーの方については、リフト寝台付タクシーをご利用いただいて、お願いしたいと考えております。","id":"exchange-018"},{"speaker":"堺委員","kind":"意見","question":"わかりました。それでお尋ねしたわけです。いろいろな要素が必要になってくるかもしれませんし、今後、そういうサービスのあり方、内容等についても研究し、また、検討をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今のお話をお聞きしていて、ちょっとよくわからないので教えていただきたいんですけれども、ストレッチャーだと安全性が確保されにくいということの意味が、ちょっとよくわからないんです。ストレッチャーの改造車だと、安全性は確保されないけれども、リフト寝台付タクシーであれば、安全性は確保される、そこら辺の違いがよくわからないので、説明していただけますか。","respondent":"高橋障害者福祉課長","answer":"将来的に、医療行為の高い方、重たい方について福祉のほうでということになれば、再度、この辺のところを考えていく必要が出てくるのかなと思いますけれども、現時点では、安全性が高いということになれば。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、リフト寝台付タクシーであれば、安全性は確保されているけれども、そういうものを一般の人が、安全性が確保される改造車としてつくることが、技術的に難しいと、そういうことなんですか。","respondent":"高橋障害者福祉課長","answer":"つくったものに対して、区として、安全性が高いから助成金を出すという制度にはならないのではないかと考えているのであって、その車そのものが安全性が高いか低いかではなくて、それを区として認めて助成するには、ある程度の制度設計が必要かなと考えているところです。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしましたら、車そのものの安全性が確保されないという意味ではなくて、そこら辺のところが、なぜリフト寝台付タクシーが助成の対象にならないのかというのが、いま一つ説明として理解ができないんです。技術的に安全性が確保されないということでだめなのか、それもと何か別な意味で安全性が確保されないということがあるのか、ちょっとそこのところを教えていただきたいんです。","respondent":"高橋障害者福祉課長、木下福祉高齢事業部長","answer":"リフト寝台付タクシーにつきまして、専門の運転手がついているということで安全性が確保できるのではないかというふうに、私どもは考えています。緊急を要するものは、当然、救急車を使えばよろしいわけですので、そういうふうに考えてまいりますと、請願者が希望されていることが一体何なんだろうかと。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問","question":"これが１点です。ですから、それは、制度の周知のお話だと思います。もう一つ、前回、ちょっとはっきりしなかったのが、インフルエンザなどの助成についてなんですけれども、これについては、重度のお子さんなどで、事実上、区内の医療機関で接種を受けることができない場合について、やむを得ず区外の医療機関で受けた場合に、助成を受けるということはご検討いただけましたでしょうか。","respondent":"山岡健康課長","answer":"ただし、品川区外で受けられた方には、相談していただければ対応を考えますです。","id":"exchange-023"},{"speaker":"阿部委員","kind":"意見","question":"おたふくかぜ、水疱瘡については、個別の相談ベースで、ほかの子どもと同様の助成が受けられるということですね。では、これも周知方、お願いします。インフルエンザについては、区内助成制度がないので、それはどの子どもについてもないという理解でよろしいですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"先ほどの福祉高齢事業部長のご説明の中で、医療法上の問題点が出てくるのではないかという、そのあいまいもことしたご答弁だと、ちょっと納得がいかないんです。リフト寝台付タクシーの場合の運転手というのは、どういう資格を持って乗っていらっしゃるのか。家族は、家族が乗ればいいのであって、運転手さんが家族であってはならないような要件があったとか、その辺教えてください。","respondent":"高橋障害者福祉課長","answer":"リフト寝台付タクシーの運転手につきましては、基本的には、運転業務プラスヘルパーの講習を受けたということを聞いております。その辺については、医療的まではいかないんですが、多少なりとも介護的な知識は持っているかと思います。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"予防接種のところも、公費負担として利用拡充を強く要望というところにおいては、任意のところあたりも、やはり公費負担でという願いだと思うので、この部分は金額的にそんなに大きな額ではないので、ぜひこれは拡充を願っていきたいと思って、これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"阿部委員","kind":"意見","question":"先ほどからのご答弁を聞いていても、ちょっとまだ説明がクリアでないところを感じておりまして、もう少し継続をすべきではないかと、私は考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党として、大変に難しく考えています。ご家族は言わないですけどね。ただ、先ほど来出ているように、医療と福祉の問題という境目で、先ほど、私も意見の中で述べたんですけれども、福祉部門ではなく、この請願自体が医療の治療、通院ということにかかっている部分からすると、福祉の部門である車いす同乗車両助成事業がこのまま拡大していいのかどうかというのは、ちょっと疑問を感じています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"堺委員","kind":"質問・要望","question":"ただ、これからも、こういう方々が出ないとも限りませんので、先ほども申し上げたかと思いますが、品川区の福祉という面におけるいろいろな事業においても、いろいろな選択肢があってもいいのではないか、またそういう選択肢をつくるべきではないかというような面から、先ほど、今後の検討をしてほしいということも、要望として申し上げましたので、その辺のところも踏まえて、今回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前回は採択を主張しました。私は、いろいろ困難があっても趣旨を十分に理解して、行政として何ができるかということをとことん追求していただきたく、前向きに改善、拡充をしてほしいという意味で、できましたらご賛同いただきたいなと思って、趣旨採択をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"阿部委員","kind":"意見","question":"ただ、医療と福祉の境というのは、これからも大きな問題になってくると思いますし、もう既に難病というのは、福祉の対象になって日が経ちますので、この件もそんなに直接は大きな医療と福祉の境の問題ではないと考えているんですが、役所の中で、まだこの問題について未整理ということであれば、ぜひ、この１件を一つのきっかけにして、医療、福祉でそれぞれ、どうすみ分けつつ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"１０ページの介護予防事業の中で、これの利用者は、特定高齢者および非該当の方々ということなんですけれども、利用者の中で、特定高齢者の割合がわかれば教えてください。それから、プログラムや場所によって、非常に参加人数にばらつきがあるんですけれども、それについて、何か理由なり、コメントなりがあれば教えてください。","respondent":"冨岡高齢福祉課長","answer":"参加数のばらつきですが、それぞれ開始の時点が違っていまして、エリアを中心にやっておりますので、なかなか広まっていかない部分と、案外広まって数多く参加していただいている部分があるという状況です。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"今、特定高齢者が１０人ぐらいとうご答弁だったんですけれども、ここに出ている何千人のうちの１０人ぐらいということなんでしょうか。それとも、それぞれのプログラムとか、それぞれのエリアで、すべて挙がっている累積１万人ぐらいの中での１０人ということではないかと思うんですけれども、ちょっとその辺、はっきり教えてください。","respondent":"冨岡高齢福祉課長","answer":"今のこの数字は、私の記憶で申し上げたので、全体の中に混じっておりまして。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"それからもう１点、ちょっとうろ覚えで申しわけないんですけれども、違っていたら言ってください。介護予防の中で、制度上は口腔ケアというのが含まれていたかと思うんですけれども、これは品川区やっていない、あるいは、今後ともやる予定はないということなんでしょうか、教えてください。","respondent":"冨岡高齢福祉課長","answer":"口腔ケアについては、実施をいたしております。予防ミニデイの中に単発で入っている、混ざっているのではないかと思います。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問・要望","question":"予防ミニデイの中に単発で入っているということですか、わかりました。ちょっとこの表からはわからなかったものですから。先ほどの資料の取り方については、伺ってもいいですか。つまり、特定高齢者の数がわかるように統計を取っていただきたいということについても、一言お願いします。","respondent":"冨岡高齢福祉課長","answer":"次回、そうなるようにいたします。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"今日はたくさんの資料をつけていただいて、介護保険制度の状況をお知らせいただいて、ありがとうあります。全体の流れなんですけれども、現在は、第４期の事業計画に向けていろいろ検討中であると受けとめているんですが、この辺に対して、議会としてどこで意見を発言できるのかなという思いが、今、しているわけです。流れについて、教えてください。","respondent":"冨岡高齢福祉課長","answer":"パブリックコメントの関係ですが、この委員会は公募の委員もお入りいただいて、ある程度区民のご意見もいただいているということで、今の段階で、パブリックコメントについては考えておりませんが、検討をいたします。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"骨子のまとめができてから、議会のほうにという流れだと、そういうふうに受けとめました。質問は、ページを追って順次します。１ページと２ページ、３ページを見たところで、高齢化率が上がり、人数が確実に増えているわけですけれども、２ページの上の図のところで、認定率が下がっている部分と、下のところで、ケアプランを立てているケースが減っているんですが、この理由を教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"それからもう一つ言えるのは、逆に、認定者数の中で死亡される方が増えていまして、平成１２年のころは１,０００人でしたが、一番最後のが１,４８１人ということで、以前から認定を受けていた方がだんだん高齢になってお亡くなりになることが増えている、この二つの要因で。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"国の２６.１％に比べて品川区の要支援の率が３２.４％で、前年度も３３.０％なんですけれども。これも前年を見ると６７％という感じなんです。今はお元気で活動されている方が増えているというところは、とても嬉しいことだし、また反対に、認定を受けていた方がお亡くなりになられたということなんですけれども、こういう条件が、品川区は全国の場合と違うところがあるんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"平成２０年度の表を見ますと、全体的にお元気だということは、要介護が少なく、要支援が多いということで説明がつくかと思います。それから、要支援のほうが高くて、要介護が低いです。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全国の構成比とかなり違っていますよね。だから理由があるんだったら、その辺がわかっていたら言っていただきたい。元気な方が多いというのは、そのとおりだったら、私は好ましいと思うんですが、そうなんですか。今のところ、不十分なご答弁だったので、もう１回。私はそこが大変疑問で、問題意識を持っているので、ちょっと先にご答弁をいただきたい。","respondent":"木下福祉高齢事業部長","answer":"一つは、平成１８年度の制度改正で、要介護１の人については、審査会で、コンピュータ判定が入るんですけれども、いわゆる要支援２、あるいは要支援１に行く人と、要介護１、あるいは要介護２にいく人の切り分けがされることになっていました。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"特に要介護１の人などは、認知症がなければ要支援のほうに実質的に行ってしまうし、ケアマネージャーなんかが、いっときベッドが取り上げられたり、私は車いすが取り上げられちゃった人にもほんとうにお会いしましたけれども、そうやって必要な人に必要なサービスができるような、介護度ではなくて、お金の枠がないから受けられないんだというケアマネージャーの声も伺っているんですが、その辺は。","respondent":"木下福祉高齢事業部長","answer":"これは、どういうことかというと、品川区の場合は、認定審査会に単に結果をお諮りするということではなく、その人が使っているサービスを検証して、例えば要支援に行った場合、どのような問題が出るかということまで分析しながら、言ってみれば、訪問調査の結果。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この数字から見ると、単純にお元気な、家事援助なども受けなくても済むような、予防介護で積極的に悪くならないようにいい方向にもっていくという人が増えているんだったら、それはとても喜ばしいことだと思うんですけれども、ここの数字の陰には、やっぱりそういった、今の制度の切り換えのところで苦労していらっしゃる方がいらっしゃるということを、適正に行われているという言葉で済むのか、どうか。","respondent":"木下福祉高齢事業部長","answer":"今後とも、このことについては、繰り返し説明をしていきたいと考えています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"周知をしていただきたいんですけれども、４ページの一番上がホームヘルプサービスなんですけれども、予防給付のところは、どういったケースの人が受けられているのか、ちょっと知りたいんです。どこにも当てはまらなくて、施策の合間のところの人が現にいます。現実的に独自支援策が行われていることについて、見解は。","respondent":"冨岡高齢福祉課長","answer":"谷間とおっしゃいましたけれども、要支援状態でない、要介護状態もない方に対しても、予防という形で生活の援助をいたしておりますので、こういうものをさらに利用していただければ、独自で対応しなくても、むしろこちらのほうをご利用いただければなと考えています。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"今の説明、具体的にどういったサービスが受けられるのか、中身を聞かせてください。これは、区の持ち出しですよね。そこもちょっと教えてください。","respondent":"冨岡高齢福祉課長","answer":"区の一般財源で対応している部分でございまして、対象者につきましては、今申し上げましたように、介護予防の視点から、主治医から認められた方に訪問介護員を派遣して、日常生活における意欲の向上を喚起するということで。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"４ページの通所リハビリテーションのデイケアのところなんですけれども、介護給付の経過をずっと見ていくと、平成２０年度が２９カ所から２３カ所に減っているんですけれども、どうしてかなと思います。私は、えっ、２３カ所もあったのかと思ったので、さくら会とか、あと何カ所しか知らないので、どういうところがここに該当するのか、ちょっと教えてください。","respondent":"冨岡高齢福祉課長","answer":"これは、さくら会のほかには、医療機関を中心に施設で実施しておりまして、あとは近隣の区の部分ですが、やはり保険での対応ですので、医療との関係で今回は減っているというところで、細かい理由については分析をしておりません、申しわけありません。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"久しぶりに報告を聞いたので疑問点がいっぱいあるんですが、ハートページの通所リハビリテーションのデイケアのところを広げると、これは２００７年度版なんですが、５個しか書いてなくて、区内は２カ所しかないんですが、ここに書いてある以外に、近隣の医療機関にたくさんお世話になっているというとらえ方でいいんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"こちらに出ているのは介護保険対応だけで、医療保険対応の部分については出ていないです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"二つですけれども、5)の訪問看護・訪問リハビリテーションのところが一括りになっているんですよね。本来だったら、内容的にかなり違うものですよね。看護師と理学療法士と違うと思うんですが、これが何で一緒になっているのか。かなり減ったにもかかわらず、さらに平成２０年３月で４５０ぐらい減っているんですけれども、この辺の理由が何か教えてください。","respondent":"冨岡高齢福祉課長","answer":"福祉用具ですけれども、これにつきましては、予防のほうが少し増えまして、介護のほうが減っているという状況でありますので、むしろ実際の予防のほうは、いろいろ特殊寝台が継続外になったということであれなんですが、介護のほうにつきましてはそのままの状況ですので。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"さっきの訪問リハビリテーションのところ、分離してくださるということなんで、表記をよろしくお願いします。それから、リハビリが何件あったのか、もしわかったらでいいんですが、教えてください。","respondent":"冨岡高齢福祉課長","answer":"すぐに出ませんので、後で。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"短く聞きます。それをただ質問しろというのは、流れがちょっとわからなかったんです。もしかすると、これは委員会のほうのあれになってしまうのかもしれないんですけれども、自分が聞かなかったから、資料は出たけれども、どういう流れでやるんですかということが非常にわからなかったということが、自分も失敗しているけれども、もうちょっと説明が欲しかったという気がします。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"この部分については、今後の課題となろうかと思います。予防と給付のことを申し上げましたけれども、今回の制度改正であと重要なのが認知症対応です。サービスにつきましては、それぞれ居宅サービスもあれば、施設サービスもあるわけで、さまざまなサービスに対する苦情ということで、サービスの計画に対する問題とか、実施に際して、介護者の態度の問題とか、苦情を言っても。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、ぜひ説明会をやっていただきたいというのが一つ要望なんですけれども、そのことをお聞かせいただきたいと思います。それから、国庫支出金のところも２０.８％で、調整交付金は０.８％しか来ないという、前はもっと出ていたような気がしているんですけれども、ここら辺はどうしてこういうふうになっているのかということもお聞かせいただきたいと思います。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"私のほうから、説明会の件、現時点での考え方なんですけれども、平成１２年は、制度創設時ということもありまして、地区別説明会を行いました。細かい制度上そうなっていますので、ご理解をいただきたいと思います。あわせまして、繰越金が若干ありますので、それを足すと１００％になるという決算の見込みの数値です。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"滞納者なんですけれども、国民健康保険なんかでは、相談のときに、滞納されている理由の一覧表をつくられるんですけれども、去年も、行財政改革特別委員会の滞納の問題の審議のときに、介護保険でもそういうふうに滞納者の実態がわかるようなものをつくってほしいということが、議会の中でも出ていたんです。そういう点では、滞納者の理由がわかるような、区として把握されたものはできたでしょうか。","respondent":"冨岡高齢福祉課長","answer":"６５歳ですからまだお仕事をされている方もおいでになるケースもありますけれども、それをすることで、次の手を打てるのかというと、もうちょっと生活に即して分割なり何なりでお支払いいただく実践的な方法をとったほうがいいのかなと思います。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、前回が大きな改定ということになるんですよね。ほんとうは、前回やっていただければ一番よかったなと思うんですけれども、その中で、大きく中身が変わったというところで、大変な実態が区民の中にすごくあふれている状況があると思いますので、そういう声を聞いていただくためにも、ぜひ、説明会はご検討いただきたいということで、これも要望させていただきたいと思います。","respondent":"大沢委員長、永尾高齢事業課長","answer":"本件を終了します。このお二方につきましては、申し出書と口座振替依頼書を提出していただきまして、天引きを外すことが可能となりました。次に、品川区の対応についてのご説明をいたします。Ａ３版資料の左側のほうをごらんください。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"法改正があった後というのは、事務をしていらっしゃる皆さんは、準備から、またその後の問い合わせの対応まで、ほんとうに大変なご苦労があって、特に、今回軽減割合が拡大されたというので、住民にとってはいいことだし、またもう１回手間があって、また次のときもということで、ほんとうにご苦労が大変だなと感じつつも、いろいろ教えていただきたいと思います。軽減策というのが、一体いつまで続くのか。","respondent":"永尾高齢事業課長","answer":"その人数は１２４人となっております。国の軽減策につきましては、平成２１年度から実施ということで、政府与党のほうの決定が出ておりまして、その先については、まだ明らかにされておりません。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"平成２１年度以降はわからない、まだ指示がないということは、今回お示しいただいたのは、平成２０年度の３月までの軽減策という受けとめ方でよろしいんでしょうか。","respondent":"永尾高齢事業課長","answer":"今の段階だと、いつまでというような規定がないという状態です。ですから、平成２０年度は８.５割軽減で、平成２１年度からは９割軽減という通知が来ております。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"均等割の８０万円を超えて１６８万円の方はもとの７割に戻るという新聞報道を読んでいるんですが、その辺をお聞きしたい。実際に、後期高齢者医療制度の決定をした中で、３月までに国民健康保険を払っていた段階よりも軽減された方が、どのぐらいいるのかを教えてください。","respondent":"永尾高齢事業課長","answer":"均等割の軽減についてですが、平成２１年度の９割軽減になられる方は、現在７割軽減になっている１６８万円以下の方全員です。訂正をします。９割軽減になる方は、年金収入が８０万円以下の世帯ということになります。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"割合が大変狭まっているなと、私は受けとめているわけです。この指摘に対してどうかという質問に対して、そのとおりであって、６５万人で、これを計算すると５％の方なんですよね。この辺の推計というのは、品川区とか、東京都の広域連合においてはできないんでしょうか。国段階でこうやって数字が出ているということは、自治体も当然、つかんでいくべきであると思うんですけれども、いかがでしょうか。","respondent":"永尾高齢事業課長","answer":"大変申しわけないんですけれども、現在のところ、広域連合のほうから、具体的なそういう数字が出ておりません。そしてまた、品川区においても、国民健康保険との比較等はまだやっていない状況です。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大変関心が高いので、実際のところ、区民の皆さんがほんとうにどういった状況にあるのかというところをつかんでいきたいので、ぜひその辺はつかむようにしていただいて、明らかにしてほしいと思っています。区で出された資料にのっとって、そういうことが出ているので、その辺もぜひ明らかにしていただきたいと思うんですが、いかがでしょうか。","respondent":"永尾高齢事業課長","answer":"減になっているのが、年金収入で言うと１６０万５,０００円以下。４３７万１,０００円以上というような資料をいただいておりますが、これは一つのパターンでやったということなので、すべてがそういう結果になるとは言い切れない部分があります。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私としては、今回、平成２０年度までで、その先が決まっていないというところにおいては、とりあえずソフトランディングというか、軽減策が先に示されて、その先が不安というか、２年後には保険料の改正をさせるというところにおいては、すごく国民がだまされる軽減策というか、目先をごまかしているような中身であるなと思うので、そういうことも実際に今の段階ではわからないのかもしれませんけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ。金額が、保険料が安くなるということで、喜ばしいことだと思うんですけれども、私が勘違いしていたらいけないので、１点確認です。東京都広域連合のほうで、保険料の関係が決まりますよね。この資料の中で、６月１２日に、政府与党決定があって、７月１３日に送った。その間に、広域連合では何か会合が開かれて、その決定があったんですか。それがわからないので、ちょっと教えてください。","respondent":"永尾高齢事業課長","answer":"広域連合のほうで、幹事会等がございまして、その定例的な取り決めに基づいて会議を開いての決定です。","id":"exchange-058"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと資料の見方で教えてください。これは広域連合から出てきたものだと思うんですが、２ページ目の下の表、対象者数と必要経費と出ているんですけれども、対象者数というのは、それぞれ都内全体でこれだけということなんでしょうか。必要経費については、Ａ、Ｂはこれはやはり都全体の必要経費ということなんでしょうか。","respondent":"永尾高齢事業課長","answer":"対象者数というのは、東京都全域です。必要経費も、同様に東京都全域です。","id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"Ａ、Ｂ、Ｃ、Ｄ、それぞれ東京都の積み上げの数字なのか、理論値なのか、ちょっとわからないんですけれども、大体、品川区はＡ、Ｂ、Ｃ、Ｄ、それぞれどのぐらいというのは、東京都段階でわかるのであれば、区段階でもわかるのかなと思ったので、教えてください。","respondent":"永尾高齢事業課長","answer":"Ａに該当する人数ですが、７１５人です。Ｂに該当する人数は２００人です。Ｃに該当する人数ですが、６３０人です。Ｄは１２４人ということになっております。","id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど、均等割の７割から８.５割軽減になる方が１万５９２人ということなんですけれども、この方のうち、来年８０万円以下で９割になる方は、どれぐらいの方がそのまま軽減されていくのか、その人数を教えていただきたいと思います。","respondent":"永尾高齢事業課長","answer":"来年の数字ですけれども、今年の１月から１２月までの収入に応じて変わってくると思います。ということですので、平成２０年度の住民税の結果では、そこまで算出はしておりません。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回の８.５割軽減になる方は１６８万円以下の方ですよね。それからもう一つは、今回の納付書が、銀行と郵便局でしか払えないということで、地域の方からは、すごく高齢者で、７５歳過ぎた方が杖をついて歩くのに、コンビニでも何とか払えるようにしてもらえないかという声もいただいたんですけれども、そこら辺のところが、可能性かあるかどうか、そこのところについてもお聞かせください。","respondent":"永尾高齢事業課長","answer":"最初の軽減の件ですが、当初は７割軽減ということでやっていたところ、世論のいろいろなご意見をいただきまして、今回、変更されたところです。これについては、品川区独自で考えられるものではございません。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つ、ちょっとお聞きしたいのが、今回の負担軽減等についてということで、政府与党から出されたことで、終末期の相談支援料については、凍結するということになったかと思うんですけれども、そのことについて、国がそういうことで凍結で、それは適用されないということになっていくと思うんですけれども、その点について、お聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ほんとうに制度が始まってわずか３カ月で凍結せざるを得なくなった。それからまた、政府与党のこれを見ますと、さらに後期高齢者診療料についても、これからは具体的な検討作業に入ると書かれておりますけれども、制度そのものがほんとうに矛盾の多い制度なんだということを、改めて申し上げて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"浅野委員","kind":"質問","question":"民生委員は記録は持っていないというようなことを聞きましたので、過去にもこのようなことがあったのか、どうか。対処方法を、簡潔に教えていただければと思います。","respondent":"永尾高齢事業課長","answer":"民生委員に名簿をお渡ししまして、判こをいただいて配付をしています。実際に、昨年、そういうことがあったですので、事務局のほうでもう一度、調査をいたします。","id":"exchange-065"},{"speaker":"阿部委員","kind":"質問","question":"１点、１０１歳以上の祝品なんですけれども、１００歳以上の方って、今、すごい勢いで増えているんですよね。毎年贈られるということで、この事業は対象自体の見直しは考えはなかったんでしょうか。いつまで毎年贈り続けられるのか、その辺を教えてください。","respondent":"永尾高齢事業課長","answer":"見直しを検討する際に、全部の人口を出しまして、その辺の動向などを見たんですけれども、今回につきましては、見送りをいたしました。","id":"exchange-066"},{"speaker":"鈴木（真）委員","kind":"確認","question":"すみません、１点だけ確認します。今、区道を挟んでというお話だったんですけれども、あそこの区道が、ちょうど山手通りから坂を上りながらの道ですよね。今現在、体育館があって結構斜面がきついんですよね。あまり細かいところは保育課長の範囲ではないかもしれないんですけれども、この道は広がるんでしょうか。というのは、保育園ですから、子どもを乗せてくる自転車がありますよね。","respondent":"小林保育課長","answer":"区道につきましては、大幅な拡幅は予定されていないようです。しかしながら、設置します建物のセットバック部分がありますので、外観上は拡幅できますので、安全確保には遺漏のないように、今後の施設計画を十分に注意してまいります。ご意見を、ありがとうございました。","id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"今、自転車の置き場の話はともかくということだったんですけれども、自転車置き場については何か具体的な計画、あるいは考え方でも結構ですが、あったら教えてください。","respondent":"小林保育課長","answer":"が、台数につきましては、ちょっと小さいんですが、調理室側のセットバックした部分に、通常よりも台数を多く設置いたしまして、上の預かり、あるいは地域交流室をご利用いただく方のスペースも含めて対応してまいりたいと考えております。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"幼稚園と保育園のところなんですが、幼保一元化の型というところにおいては、二葉すこやか園と、台場の小学校のところしか、現実的にはまだできていないんですが、中身的には、同じようなものととらえていいのか。それから、規模とか、形態はこれからということなんですが、おおよそどのぐらいのキャパシティがあるのかというところも教えてください。","respondent":"小林保育課長","answer":"基本的に、形態のあり方は別といたしましても、施設としては、０から５歳までの施設で、規模は、まだ詳細は未定ですけれども、１１０名から１５０名程度の規模を想定して、検討してまいりたいと考えております。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"今、規模、１１０名から１５０名ということで、かなり広くスペースが取れるということですね。そういったところで、中身的には、幼稚園がないところに新たにつくるということでは、周辺の私立幼稚園や何かとのかかわりも当然出てくるというところでは、既に調整というか、その辺の話し合いはされていらっしゃるんでしょうか。","respondent":"小林保育課長","answer":"その人数につきましては、地域需要に対応したものとしてまいりますので、基本的に、その結果、私立幼稚園に大きな影響が生じるということは想定しておりません。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"確認","question":"新たなタイプになる可能性があるのかなと、今のご答弁で受けとめたわけです。認定子ども園も視野に入れてということにおいては、民間保育園と民間の幼稚園の形であるということは確認できるんでしょうか。","respondent":"小林保育課長","answer":"そういった形態も含めて、今後、検討してまいりたいと思います。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"意見","question":"もう１点なんですけれども、ここの計画が出てきたわけですけれども、荏原西地区のところで、小中一貫校の中に、地盤の問題で入れなくなったというあたりでは、ちょっと飛ばされているところなんですけれども、その辺の進捗状況はとても地元の関心事なんで、そこら辺、どういう状況なのか、お聞かせください。","respondent":"小林保育課長","answer":"地元のご期待にこたえてまいりたいと思いますが、現段階で大きく変わっておりません。今後もその状況を把握しつつ、施設のあり方を検討してまいりたいと思います。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"７月１４日に企画財政課長が各会派を回られて、八潮のまちづくりのところのご報告があって、街づくり特別委員会には、２４日にご報告があると聞いたんですが、その中に、はば広いニーズに対応する高齢者福祉施設の整備というところにおいて、特別養護老人ホーム、認知症高齢者グループホーム、ショートステイ、介護予防拠点ほかと、こういう項目が入っているので、まちづくりのところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"今。街づくり特別委員会ではそうですが、所管にかかわる部分において、全く委員会で報告がなくて、質問もできないという状況では、今月、もう次にいってしまうことでは、厚生委員会のところだけ外れているという受けとめ方になってしまうんです。私どもとしても、ここの専門の部分において、地域に行けば、必ず質問が来るわけですよ。そういう報告はあってしかるべきと思いますが、それは間違いでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、街づくり特別委員会の中で１回報告がされた後に、例えば、次の厚生委員会でその報告の中身を詰めてくださいというのなら、流れがわかると思うんですけれども、現在、ここの委員会で担当部署からその答えをもらうというのは、流れが違うんじゃないかなと思います。委員長の判断になってくると思うんです。ですから、委員長同士で調整しなければ、ここでやってしまう話ではないと、私は考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その他のその他でもう一つお聞かせいただきたいんですけれども、先日、私は介護保険制度の推進委員会を傍聴させていただいたんですけれども、その中で、第４期の介護保険事業計画について、という報告の中で、特別養護老人ホームの整備をしていこうと、切り換えをして検討をしているということで、福祉高齢事業部長のほうからお話があって、それはもっと詳しく説明をしてほしいと、その委員から質問がされて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"阿部委員","kind":"意見","question":"その委員会の中でおっしゃったことが、委員会の中の限定のお話であれば、委員会で、ということになるかと思うんですけれども、そこでのご発言が区の福祉施策全体にかかわることであれば、簡単で構いませんので、お話しをいただけるとありがたいなと思うんですけれども。","respondent":"木下福祉高齢事業部長","answer":"考え方なんですけれども、施策の考え方ではなく、整理の仕方なんですが、特別養護老人ホームの問題については、既に本会議でお答えをしております。","id":"exchange-077"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"テーマについて、高齢者支援とか、子育て支援について、障害者のところも、柱のところは賛同するんですが、前回、資料も提出して、長野県で知的障害者の総合援護施設の西駒郷、子育て支援のところも、今までいろいろな施設は回っているんですが、長野県の下條村のまちを挙げての子育て支援、規模はいろいろ違うかと思いますけれども、精神とかどういうところを学んできたらいいのかというので、前回。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"阿部委員","kind":"意見","question":"テーマ自体は、高齢者支援、子育て支援、それに発達障害者まで入っていて、盛りだくさんでいいと思うんですけれども、それぞれ出てきている案というのはもう少しわからないと、例えば幼保小の連携指導プログラムをつくっている自治体は、もう日本の中にたくさんありますし、その他グループホームだって、全国でここ１カ所というわけではないですね。では、なぜここなのかというのが、もう少し。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"意見","question":"クレームをつけているわけではありませんよ。ちゃんと中身がわかるように。前回は、共産党は具体的な場所を出したわけですよ。やっぱり比較検討するのが大事だと思うんですけれども、今回、ぽんと委員長案ですって言われても、私は、正副委員長で調整していただくように希望します。","respondent":"大沢委員長","answer":"この件につきまして、早急に検討させていただいて、日程等、調整します。よろしいでしょうか。取り扱いにつきましては、時間的な制約がありますので、決まったときにはご理解をしていただきたいと思います。以上で、本日の予定はすべて終了いたしました。","id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/481603?Template=document&Id=3210#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":54958,"voices":195}},{"id":"h20-20080722-8","meetingId":"h20-cm07","date":"2008年7月22日","dateIso":"2008-07-22","committee":"建設委員会","time":"午後１時０３分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問","question":"それをお聞きしたいということと、それから２つ目としましては、品川区のほうでは、向こうの立会川のほうが非常にいい結果が出ているという広報等があるんですけれども、それは非常によかったことなんですが、目黒川と立会川は、かなり河川の規模といい、底の部分の形状も違いますので、その辺について特別なお考えがあるのかどうか、その２点を質問したいと思います。","respondent":"家壽田下水道河川課長","answer":"その辺を踏まえまして、高濃度酸素溶解水の効果、あるいは海水導水の効果などを踏まえて、どういった対策が目黒川に望ましいのかということは、近隣区であります目黒区、世田谷区あるいは東京都を含めて、しっかり議論し、今後検討してまいりたいと考えています。","id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"事情はわかりました。それから２つ目なんですけれども、これは当然、今ご説明いただいたとおり、８０倍ということなんですけれども、目黒区、世田谷区、この辺と関連して、当然東京都の問題もあるんですけれども、その辺について、もうちょっとご説明いただければと思います。","respondent":"家壽田下水道河川課長","answer":"その連絡会の中で、今回、水質改善の検討会を東京都も入れてやろうということになっておりまして、具体的な検討を広域自治体であります東京都としっかり技術的な議論を闘わせるということで考えております。","id":"exchange-002"},{"speaker":"三上委員","kind":"質問","question":"目黒川のしゅんせつというのは、どのぐらいの頻度でやっていらっしゃるんですか。","respondent":"家壽田下水道河川課長","answer":"しゅんせつは大きく２つあります。河川の水を流すために川底が埋まってしまったのを取ってしまうしゅんせつ、これが東京都建設局で行う大規模なものです。それから、護岸のフーチングと言っていますけれども、護岸の出っ張りのところにたまったヘドロを取る。","id":"exchange-003"},{"speaker":"三上委員","kind":"質問・要望","question":"品川区としては、１０年に１度という考え方というのは、果たしてそれで事足りていると思っているのか。東京都に対して、もう少し細かにやってもらいたいという要望をしているのか。そこらあたりはいかがですか。","respondent":"家壽田下水道河川課長","answer":"私の所感では、毎回、毎回、ヘドロが入れかわっているだろうと思っていますので、雨のたびに入れかわっているものを毎回やるのは、却ってそれは効率的ではないと思いますので、それであるならば、出ないようにする対策を都の下水道局のほうに要請するなり。","id":"exchange-004"},{"speaker":"三上委員","kind":"質問","question":"そういう行き来があるというのであれば、ある意味では、私はダムゲートみたいなものを目黒川の河口のほうに設置して、水かさが上がるという時には、ダムゲートの働きをして、上には上がってこないと。そういうようなことはやってはいけませんとかという考え方というのはあるんですか、どうなんですか。","respondent":"家壽田下水道河川課長","answer":"確かに河口のところで閉めてしまえば、海からの逆流はなくなるんですが、残念ながら、そこから上流側でも雨が降るたびに汚いものが今出てきているわけですけれども、それを逆に海のほうに押し流すことを止めてしまうことにも場合によってはなるかもしれませんので。","id":"exchange-005"},{"speaker":"三上委員","kind":"提案","question":"そこらあたりは本当にどうしていいかわからない。それは区の考え方一つになってくるのかわかりませんけれども、何かこちらが提案すると、いや、それは当初はいいけれども、しばらくたってからだめですよというようなケースが重なってくるようになってくるということではないかと心配しているので、そこらあたりをやっていってもらいたいなと考えています。","respondent":"岩田まちづくり事業部長","answer":"これは推測にしかすぎませんので、あくまで品川区は道理は通すと、協力するところは協力するという姿勢は崩さずに、毅然と対応していきたいと考えています。","id":"exchange-006"},{"speaker":"三上委員","kind":"質問・要望","question":"私も深く言いませんけれども、そこらあたりはやはりお互いの感情論がぶつかり合うということだけではなくて、それなりに誠実にお互い話し合いの頻度を高めていって、和解なり解決するような方向でしっかりやっていただきたいとお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ聞きたいんですけど、先ほど高濃度酸素溶解水の機械が立会川との関係で言うと１２台必要であるというお話でした。８０倍の違いがあるというんですね。だから、何か単純に考えて、ここで２台、倍の能力で設置したからといって、立会川と同じ、よい結果というのは出てくるかどうかというのは、そこのところが、よくわからないんです。他の区との関係とか、その辺、ちょっと教えてもらえますか。","respondent":"家壽田下水道河川課長","answer":"その上がってきている、掃除する要素がなかなか上流部分までは行き届いていない。そこのところが汚れているという要素でありますので、そんなことなんかもトータルで考慮しますと、８０対１ではなく、１２対１ぐらいになっているというふうにお考えいただければと思います。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"先ほど言っていた近隣区等と協力して、東京都と折衝していくという話がありましたけれども、ということは、この品川区で９台、目黒区で３台と、結果としてよければそれを目指すんですよという話なんですか。さっきの東京都との今後の交渉といいますと。","respondent":"家壽田下水道河川課長","answer":"ですから、その水を入れかえる効果であるとか、酸素を入れかえる効果、それともちろんお金も含めて、どれが一番効くのかというのはまさにこれから検証していった結果でわかってくると思いますので、今のところどちらが是か非かというところはまだ決め切れないところです。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"今の関連にもなってくるんですけれども、なかなか今のこの長期計画が見えないんですけど、今、ちょっとお話をされた部分をもう少し詳しくお話をいただきたいことと、ここについての今回の調査は、平成２１年３月までということで、経費の部分について詳細を教えていただきたい。","respondent":"家壽田下水道河川課長","answer":"平成２１年３月までの実験というご質問ですけれども、本年度につきましては、予算をつけていただきましたところ、契約になりましたのが４,３６４万円の金額で、これは単年度、単費の実験として執行する予定です。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうところで事業化について検討するということが、それだけで長期的にこの目黒川をどういうところまで持っていこうとされるのか、単費でこれだけお金をかけていくわけで、その費用対効果も含めて、区としてどこまでどういうふうに、それと関連して、立会川は５年のリースということで、その後どうなるのかというところもちょっとわからないんですけれども。","respondent":"岩田まちづくり事業部長","answer":"ちょっと分けて考えていただきたいんですが、まず立会川の場合は、もう実験ではなくて本格実施です。５年というのは、５年後には今東京都が行っております第二立会川幹線、こういった施設がおおむねできるだろう。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"その１０年後の水質をどうするかというのを今後検討していくというのは、どういうところでそれが進められていくのかということと、区としては先、どういうふうになるかわからないという中で、どのぐらいの費用をかけながら進めていこうとするのか、もう少し予算みたいなもの、来年また予算要求をしていく事業になると思うんですけれども、そういうところの予測というか、それをちょっと教えてください。","respondent":"岩田まちづくり事業部長","answer":"その協議の中で、さらに追加で検討するような事項が出れば、それは事業として出てくるかもしれませんけれども、大きな実験としては、今年度で一応終了という形になります。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"１つだけお聞きしたいんですけれども、整備の方針の中で、周辺環境に配慮ということで、今の説明の中で風環境について、いろいろ住民の方からの質問があったという話がありましたけれども、今、大きな問題になっている、この建物そのものからのＣＯ2の発生量というのはどういうふうに計算をされているのかというのを教えてもらいたい。","respondent":"青木都市開発課長","answer":"ただし、これにつきましては設備計画、具体的な設計が固まらないと、具体的な数字が出てこないということで、今回進めております都市計画手続きの中で、その具体的なＣＯ2の数字についてはあえて議論しておりませんので、今、ここで詳しい数値をご説明することはできません。","id":"exchange-013"},{"speaker":"菊地委員","kind":"提案","question":"詳しい数値はわからないということですけれども、実際には今、いろいろな研究の中で、数値そのものをどう抑えていくかという、その設備のあり方というのは、かなり明確になってきている部分もあるのかなと思いますけれども、都市計画決定ですから、その事業者に対する区としての考え方というのは提案をしているのかどうかというところもお聞かせください。","respondent":"青木都市開発課長","answer":"ですが、まさに国を挙げてのテーマですので、これが、地方公共団体での指導方針、あるいは削減の目標値などが定まってくれば、当然それを都市計画段階から何らか担保していくという方法論も検討の課題になってくると考えています。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"この表で、今回の変更というのは、６ページのところが変更されて、広場状空地の７号というのか、そういうものが確定をしてきたということで、あと建物の容積率と高さというものも今までなかったけれども、事業者の計画をつくる段階で、このようになったということでいいんでしょうか。","respondent":"青木都市開発課長","answer":"ご指摘のとおりです。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"そうすると、１４４ｍという高さの問題というところでは、隣のＤ地区は１２０ｍとあるんですけれども、ここはそういうふうな計画でどんどん高くなることは景観的にも望ましいとは思っていないので、そのところで１４４ｍというのは、どういう経過で、という、そこら辺、ちょっと教えてください。","respondent":"青木都市開発課長","answer":"そういった外枠からの上限が定められている中で、大崎駅周辺のデザインガイドラインというものを定めている中で、どういった建築計画をまとめていこうかというところで、これについては望ましくない、望ましいについては、ある程度主観もあるところですので。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、募集住宅の事業再建者向定期使用住宅ですか、これは３年か４年ぐらい前に新しくできた制度だと思うんですけれども、実際に区内で申し込みをされて入っていらっしゃる方とか、１年に１回これをやるんですけれども、そのたびに申し込みがあるのかどうか、ちょっとそこについて伺いたい。","respondent":"齋藤住宅課長","answer":"区内では今まで応募はなかったということです。要は、会社がつぶれて、５年間でその会社を再建しよう、その５年間は優先的に受け入れるというものです。","id":"exchange-017"},{"speaker":"菊地委員","kind":"意見","question":"ないんだけど、全都的にはあるという意味なのか。こういう人が入れますよという設定の仕方というのは、言ってみれば、数年前までは一般の方が入居可能だった住戸をこういう人たち向けにということの設定をするわけですね。だから、あまり利用度がないものをこうやって設定をしておくというのはよくわからないところがあるんですけれども、最後にそこだけ。","respondent":"齋藤住宅課長","answer":"東京都の都営住宅ですので、東京都の考えということで、私が代わりに言うということも難しいんですが、事業再建となりますと、家屋敷も全部売り払って、裸一貫で、もう一回自分の会社を立て直すということになってくる。住むところがなくなってしまうのでは困る。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"１つだけ聞きたいんですけれども、裏面にあるフローチャートということで、書類審査、ヒアリング審査、それから選定委員による選定委員会が審査をしていくということなんですけれども、この書類審査の書類の内容とか、それからヒアリング審査のヒアリングの内容とかいうのは申し込みをされた方に書類を渡すんでしょうけれども。","respondent":"齋藤住宅課長","answer":"今、委員からご指摘いただいたようなこと、手続きの開始の公示や募集要項、業務の仕様書、業務のどのようなことをお願いするかの一覧だとか、管理経験の実績、施設の平面図、植栽図、取り扱いの件数、あるいはどのような業務について出すか。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、そのヒアリングの部分だけは載せていないんだよという話ですが、ヒアリング部分というのは、そのヒアリング審査が終わった後に当然、議事録的に残っていくんでしょうから、そのほうは幾らでも載せることは可能なのではないでしょうか。","respondent":"齋藤住宅課長","answer":"規定がございまして、審査した中身については、議事録というのをとって、公表するということはしておりません。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"２つあります。１つは選定基準のところで、今回、新しくプロポーザルで、新たに指定管理者をやろうという、まず第一弾だと思うんですね。今の話で行くと、選考に漏れた事業者に対して、どういう説明をされているのか。通ったところはいいんですけれども、何だかわからないけど落ちてしまったというのではなくて、どういうふうに選考の結果をお知らせしているかというところを２つお願いします。","respondent":"齋藤住宅課長","answer":"経費ですけれども、この経費についてはなかなか難しゅうございまして、何が難しいかというと、住宅課職員、昔はもう７人ほど多かったんですが、指定管理者制度を導入することによってこの近年、人件費が縮減されたというふうに考えております。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"最初のほうで、この「適切な維持および管理ならびに管理に係る経費の縮減を図る」というのは、品川区の考え方としては、この文章というのは、私はそういうふうにとらえていなかったんですけれども、人件費削減がイコールここになるんですかということをもう１回質問したいということと、今の選考に漏れたところで。","respondent":"齋藤住宅課長","answer":"区が決めたんだから、信頼してくださいということではなくて、手続上の契約締結権がある区が選定したものについてご審議をいただいて、議会のほうでご議決いただく。これにつきましては十分対応しているというふうに考えております。","id":"exchange-022"},{"speaker":"井上委員","kind":"意見","question":"審議のところで、前回に提示資料ということで、モニタリングの評価のときに、すべて同じような項目で、特に別段違った項目が提示されていないということで、あの評価の文章、建設委員会にも示されたあの部分では、何ら変わりがなく、わかりにくいというのがこの委員会でも指摘をされていることだと思うんですけど、そんな中で、この指定管理者制度を導入するに当たって、資料提供というか。","respondent":"齋藤住宅課長","answer":"前年の委員会でのご審議について、私のほうで誤解しているかもしれませんけれども、選定した業者の過程の事由についてはご説明をしてご理解いただいたと思います。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問・要望","question":"それでもやはり、もう少し公になった部分で、民間の人たちが指定管理者の選考委員に入ったりとか、議事録というのが公開をされるというような、透明性のある選考の基準というものがほかの自治体ではあるということもあるので、もう少しそこのところは研究をして、まだ進んでいく話になりますので、ぜひ研究をしていただきたい、いくべきだということを意見としてお知らせしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/803869?Template=document&Id=3918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":24161,"voices":75}},{"id":"h20-20080722-9","meetingId":"h20-cm07","date":"2008年7月22日","dateIso":"2008-07-22","committee":"文教委員会","time":"午後１時０３分～午後３時４１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"荏原東地区小中一貫校の開設計画","agenda":"荏原東地区小中一貫校の開設計画","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今の小中一貫校の計画がよくわからないところがあったので、教えていただきたいと思います。そういうイメージなのか、それとも違うのか。それから、別途検討の話ですけれども、どういう課題と問題意識の検討を進めていくのか、隣だからという説明がありましたけれども、もう少し中身を教えていただきたいと思います。","respondent":"田村庶務課長","answer":"学校規模につきましては、今までの伊藤学園、日野学園を含めまして、やはり実績がある程度積みあがってきてありますので、今後の児童・生徒数の動向を見ても、先ほどの最大限の学級数で何とか対応できるかと、そのような考えです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明の中で、なぜ杜松小学校と荏原第四中学校を統合するかという理由の中で、周辺の影響と子どもの数を見てというご説明でしたけれども、どういうことなのかご説明いただきたいと思います。杜松小学校に入ったのに、卒業するときは杜松小学校ではなくなるわけですので、なぜそんなことをするのかということを説明いただきたいと思います。なぜ、そんなことをするのか。","respondent":"田村庶務課長","answer":"同様に、荏原第四中学校につきましても、今年は入学者数が若干伸びましたが、学年２学級の状態が継続しており、やはり住基人口からも私立等の進学者を除いた入学者の推計では、今後１０年以上にわたって２学級の状態が続くものと思われます。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、今まで小規模校を支援すると言っておきながら、みずから小中一貫校ができると廃校になってしまうから統廃合させるというのはおかしいと思うんですけれども、説明してほしいと思います。教育委員会で決定されたのが７月８日だというのは伺っているんですけれども、事務局の中でいつから検討していたのか、どういう会議体なのかわかりませんけれども、それを教えていただけますか。","respondent":"田村庶務課長","answer":"今回、特に情報提供を早目に行ったというのは、荏原西地区小中一貫校のときは、学校選択をした後に話をして保護者等に混乱が出たということなので、今回については既に予算のプレス発表で荏原東地区小中一貫校についてはお知らせしていますが。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは統廃合だと私は思います。教育環境についてもう少し伺いたいんですけれども、幾つか疑問を伺っているので、羅列してお伺いしたいと思います。耐震補強工事に幾らぐらいかかったのか、それをなぜ取り壊すのか教えてほしいと思います。意見を求めておきながら、自分たちが先に決めているわけです。これは後先どころか、全くおかしいと思うんですけれども、その点をお伺いしたいと思います。","respondent":"田村庶務課長","answer":"それ以外にご質問をいただいた制服の話だとかプールの利用の話あるいは防災避難所の話、選挙の投票所の話、区民まつりの扱いの話というのは、先ほども繰り返し申し上げていますが、今回、竣工するまでに５年、今後基本設計、実施設計、学校はそのまま使って。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言で言ってしまえば教育環境を整えるんだというご説明がありますけれども、伺いたいのは杜松小学校や荏原第四中学校にどんな教育環境上の問題があって、それが小中一貫校でなければ解決しないというのは、どういう意味なのか教えていただきたい。大規模化ゆえに学校運営上、難しくなっているという話をよく伺いますけれども、学校大規模化についてはどんなふうに思われているのか教えていただけますか。","respondent":"市川教育次長","answer":"２点目の学校の大規模化ということは、まずお答えしなければいけないのは、すべての学校を大規模校にしようという考えを持ってもおりませんし、またそういう説明をしたことはこれまで一切ございません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"国連のＷＨＯは学校は小さくなければならない、生徒は１００人を上回らないほうが望ましいという流れの中で、避けて通れないとおっしゃいましたけれども、例えば大間窪小学校と荏原第三中学校だけであれば７５１人、それに杜松小学校と荏原第四中学校をつけて１,０２３人になるわけです。今回、杜松小学校と荏原第四中学校が加わるとそれが変わるのか、その辺を教えていただけますか。","respondent":"市川教育次長","answer":"基本的に、今回計画しておりますものも、工事を実施するときにどういうメニューになってくるかわかりませんけれども、基本的にはこの補助メニューの適用に向けて検討しています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"補助金のところはよくわからなかったので、また私自身も調べて伺いたいと思います。杜松小学校と荏原第四中学校の統廃合は、品川区で６校目の小中一貫校になるのでしょうか、私は問題山積だと思っています。したがって、見直しが必要だと思います。組織の代表者だけではなくて、周辺住民の方々への事業説明会は当然やるべきだと思うんですけれども、どう思いますか。","respondent":"市川教育次長","answer":"そういうご意見も含めて、これからどのように計画を進めていくか、まず第一歩として、先ほど庶務課長から説明申し上げた荏原東地区小中一貫校開設準備連絡会をつくりますので、その場でいろいろ関係者のご意見を聞きながら事業を進めていくという考え方でおります。","id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"私は「そんなことを区長がおっしゃっていたんですか」と言ったら、「はい」と言っていましたから、その辺について教育委員会が、品川区立ですから、区長のご意見がどう伝わっているのか聞いておきたいと思います。ですから、６校構想で、ここまでは温水プール。しかし、温暖化の将来の問題はどうなんだろうという検討が、教育委員会の中でされていたのかどうかだけで結構ですから教えてください。","respondent":"和氣小中一貫教育担当課長、田村庶務課長","answer":"秋には１年生から４年生が中心の運動会をやり、５年生から９年生が応援をするという形態で、少しやり方を変えながら、子どもたちが運動会の場でいろいろ表現をし、保護者の方に見ていただくということで考えてあります。先ほど、立ち上げする懇談会の中で、やはり地域の方々のご意見を聞きながら、特に荏原西については温水プールではございませんので、小中一貫校イコール温水プールというわけではございませんので、やはり地域の声を聞きながら。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、ここもそうあるべきと思うんですけれども、例えばこちらが歴史が深いからこっちが上だとか、こちらは後からできのだから分校だとか、地域の方たちは結構そういう考えが根強いですから、そうではなくてやはり新小学校だ、新中学校だということを基本としてほしいし、やはり学校は年数が経てば歴史がありますけれども、それぞれの伝統というのはあると思いますから。","respondent":"田村庶務課長","answer":"３点ほどご質問をいただきました。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、それぞれお願いいたします。それを住民説明会という形になった途端に、反対者が集まって来て、それはだめだみたいな、建設的な意見交換だったらいいんですが、そうじゃないというところは、それはちょっと違うのではないかと思いますので、今後いろいろなところでかかわってくると思うんですが、住民説明会のあり方についていろいろ検討していただきたいと思っていますが、いかがでしょうか。","respondent":"市川教育次長","answer":"情報提供の方法によってカバーできるのであれば、私はニュースなりの方法で対応すべきものと考えておりますし、それではカバー仕切れない、どういうケースがあるのかということになろうかと思いますけれども、特にこの計画に着手した今の時点で。","id":"exchange-010"},{"speaker":"市川委員","kind":"質問・要望","question":"先ほど統合による新小学校とか新中学校の考え方の答弁の中で、地域人口が少ない、それから単学級が続いているとか、小中一貫校が建ったときに影響を受けるだろうと考える、これが今回の指針だと伺ったんですけれども、これが品川区の考える統合の基準と考えていいのか、確認をさせていただきたいと思います。","respondent":"市川教育次長","answer":"統合の基準に合致するかどうかということですけれども、荏原西地区あるいは八潮地区の小中一貫校のときに関係者の皆様方に説明してきた基準というのは、「教育環境のあり方としてどちらがいいかといったら、私どもは今見込まれる状況より。","id":"exchange-011"},{"speaker":"市川委員","kind":"質問・要望","question":"今回の杜松小学校、大間窪小学校の統合の新小学校、荏原第三中学校と荏原第四中学校の統合での一貫校建設というところでの、区が考えるデメリットは何なのか。メリットは今まで随分お聞かせいただきたいんですけれども、デメリットではどんなところを考えているのかお聞かせいただきたいと思います。","respondent":"市川教育次長","answer":"デメリットというのはどういうことを指して言われているのかわからないんですが、我々はどんな計画でもいいことばかり考えているようなことはありませんので、必ずメリット、デメリットということで表現をすれば、この計画によって得られることと。","id":"exchange-012"},{"speaker":"市川委員","kind":"質問・要望","question":"地域の中に小中一貫校があり、大規模校があり、小規模校があり、これをこういう形を目指しているんだということが学事制度審議会の中間答申に書いてあったんですけれども、区が考える小規模校の規模というのはどういうものなのか、そこだけお聞かせいただきたいと思います。","respondent":"河野指導課長","answer":"ただし、単級でも充分教育機能を果たしていることは事実ではあるけれども、極端な小人数になった場合、例えば１学級当たり数名というような状況では、やはり課題が多いというようなご意見をいただいているところです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えてください。地域で期待しているから余計聞きたい部分なんです。そういうことも踏まえて、頭を柔らかくしておいてほしいなと思うんだけれども、その辺の感覚というのを教えていただきたい。これからどこかの地域に行ってもそういう話があったら、先入観を植えつけるような話だから、それはちょっとと思ったんだけれども、その辺を教えていただきたい。","respondent":"市川教育次長","answer":"現状では、先ほどは庶務課長がわかりやすくということで、例として申し上げたんですが、これが話が固定化していくと、その意図が全く別のところに転じてしまうということ、今後充分気をつけて説明していきたいと考えています。","id":"exchange-014"}]},{"id":"topic-02","title":"品川地区小中一貫校基本設計","agenda":"品川地区小中一貫校基本設計","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"これは何人定員なんですか、教えていただけますか。それから、障害を持っている方とよくお話しすることがありまして、昔は障害者用トイレ、今はだれでもトイレになって、問題意識を持っていたんですけれども、だれでもトイレはどこになるんですか。プールは一般開放しますけれども、一番近いトイレというのはブリッジを越えないと行けないのか、その辺を教えていただけますか。","respondent":"市川教育次長","answer":"ただし、今日、厚生委員会でこの報告に対応する形で、幼保の計画について必要な報告をするというふうに聞いておりますので、詳細はそちらのほうで報告されていると思います。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"１ページ目のところの１階平面図で特別支援があるわけですが、普通学級との連携も必要な教育の一環ではないかと思うんですが、この図を見ると隔離されているような雰囲気が出てしまうんですが、その辺はいろいろ工夫されるのか、もう少し普通教室と近いほうがいいのではないかと思うんですけれども、その辺はどのようにするのでしょうか。","respondent":"田村庶務課長、和氣小中一貫教育担当課長","answer":"私から地盤の関係ですが、やはりこういう形状ということで、当然地質検査もしていますし、地盤検査もしますので、今回は、形状をうまく利用した形でということなので、その辺はご心配ないと考えております。特別支援教室の配置については、通常との交流ということで考えていきますけれども、ここにつきましても基本的に校庭に近いところに配置をしたいということと、ここは必ず子どもたちが通るところなので。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３新校舎完成とあります。それから、桜に気を使っていただいて、斜めに入っていくのをつくっていただいたんですが、そうなると１の仮校舎建設のところの下に逆ハの字のようになっているんだけれども、ここの間を抜けて既存校舎に入っていくという以外に、この形でいくと通路のところは使えないようだけれども、子どもたちはどこに入っていくのかということを教えていただきたい。","respondent":"和氣小中一貫教育担当課長、田村庶務課長","answer":"基本的には、こちらが通路で、城南中学校の生徒は真ん中あたりから左に入る、児童はその奥へ入っていくという動線になりまして、完全に工事用の車両とは区切りをつけた通路を確保しています。大体のスケジュールですが、３番の新校舎完成が、平成２３年３月上旬を予定しています。外構工事は、平成２３年７月まで予定しているです。","id":"exchange-017"},{"speaker":"山元委員","kind":"質問・要望","question":"私もあまりよくわからないんですが、エレベーターは子どもたちも使うような形になるのかということと、非常事態のときにどこに逃げていくのか教えていただきたいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"権現山公園のほうは一体的に使うということもありますけれども、こちらもセキュリティを考えてまいりたいと考えております。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"体験学習は１カ所になっているんですが、ファイナンス・パークとスチューデント・シティが入って、区分けはどんな形なんでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"体験学習棟は、ジュニア・アチーブメントと協議しまして、実際真っ直ぐ切るとかとはならないで、斜めに切ったりとか、ジグザグに切ったりとか、そんなことを考えておりまして、使いやすいようにこの１面を使ってスチューデントとファイナンスが分かれて。","id":"exchange-019"}]},{"id":"topic-03","title":"平成２１年度使用教科書採択結果一覧（特別支援学級用）","agenda":"平成２１年度使用教科書採択結果一覧（特別支援学級用）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"最後のほうの説明で、今まで学校で選んでいたシステムを変えて、教育委員会で選んだという、その辺の説明がよくわからなかったので、もう少し教えていただきたい。つまり、今まで学校で選んでいた理由と、今回変わった理由をもう少し詳しく教えていただけますか。","respondent":"河野指導課長","answer":"今回、学校ごとの採択ではなくて、品川区の特別支援学級がそれぞれこんな教科書を想定していますということで、かなり幅を持った教科書をこの一覧の中から採択できるようになりましたので、実際に入学してきた子どもがどのようなレベルなのかということについても。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"この仕組みは品川区の仕組みなんですね。東京都というか２３区というか、そこもあわせて教えていただけますか。","respondent":"河野指導課長","answer":"今年度、多少柔軟にしてもいいという通知がまいりましたので、品川区では早速取り入れたという状況です。まだ、他の区市で取り入れたかどうかということについては、特に確認をしておりません。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"この教科書を使う人は、特別支援学級に通学する子どもが対象ということですか。その場合、選択ですから親の選択になるので、通常学級を選択すれば、通常学級で使っている教科書を使うことになるんでしょうけれども、もしかしたらその子どもはこちらのほうを使って、特別な形で学んだほうがいいというような場合も出てくるのではないかと思うんですが、そういう使い方は難しいんでしょうか。","respondent":"河野指導課長","answer":"その場合には、同じ教科で検定本と１０７条本とダブルことはありませんが、教科ごとに検定本を使うのか、あるいは１０７条本を使うのかという選択は、当該の学級担任と保護者の間での相談によって、最終的には決定されるというふうに理解していただければと思います。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"特別支援学級に行くと、子どもの能力によって変えられる。特別支援学級に行かない子どもたちは、通常の採択した教科書を使わなければいけないということになるのでしょうか。就学相談のときには、保護者の方たちにどういう説明をされているんでしょうか。","respondent":"河野指導課長","answer":"就学相談では、特別支援学級でどういう指導をするのかという説明を行いますが、実際にこの子どもはこういう教科書を使いますという、個々の提示までは至っておりません。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、保護者の方がそれを知らないと、選択するときに通常学級に固持する親がおりますので、そうではなくて子どもの学びとか育ちということに対して、どういう手立てが必要なんだというときも、選択肢が広がるケースがあると思うんです。今後、そういう相談のときに、きちんと話をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。先ほどの図面でも特別支援の教室があって、これを今見させていただいて、非常に至れり尽くせりでしっかりやられているけれども、これは国のことも考えられるんですけれども、通常の小学生でも中学生でも、そこにかかる費用と、特別支援学級の子どもの費用で、漠然でもいいですが、５０倍ぐらい違うとか、何倍ぐらい違うのか教えていただけますか。","respondent":"河野指導課長","answer":"はっきり計算しておりませんので、漠然とした言い方しかできませんが、例えば１学級当たりの定数、通常学級の場合ですと現在４０名ですが、特別支援学級は８名で１学級、さらに１学級の人数が４名を超えると、副担任の扱いで１人教員が加わるということで。","id":"exchange-025"}]},{"id":"topic-04","title":"平成２０年度文化センター工事","agenda":"平成２０年度文化センター工事","exchanges":[{"speaker":"川西委員","kind":"質問","question":"工事に反対するわけではなくて、この機会に使い勝手の点で直したとか、直そうとしたという部分というのはあるんですか。今まで利用してきた人の意見とか、そこに従事している職員の皆さんのご意見を、使い勝手の悪い、あるいはこういうふうに直したほうがいいという意見を聞きながら、ここに取り入れられたというものはないんですか。","respondent":"堀越生涯学習課長","answer":"今回は大規模工事ということで、休館するような工事について、今年度を予定したというものです。","id":"exchange-026"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、例えば関係者、住民説明会とか、ご意見を聞く会とかというものを持たずに、今回老朽化の中で直されるようになったように思います。旗の台文化センターについても、年数は違いますけれども、そういうことでしょうか。","respondent":"堀越生涯学習課長","answer":"今回は内装の改修も行いますけれども、そのあたりもご説明して、その都度、ご意見をいただきながら行っているという状況にあります。","id":"exchange-027"},{"speaker":"川西委員","kind":"質問","question":"荏原文化センターについては、使用料がきゅりあんに比べて安いということで、借りにいく人がこちらのほうからもいるんですけれども、使用料については改修工事をしても変わらないのかどうか伺っておきたいと思います。","respondent":"堀越生涯学習課長","answer":"大体面積当たりですとか、そういったものから使用料を算出していますので、工事をやって使用料が上がるということは考えておりません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"五反田文化センター、荏原文化センター、旗の台文化センターのそれぞれの工事は必要なことだと思うんですけれども、時期を見ると７月、８月、９月、１０月に区内の三つの文化センターで一斉に工事が始まるわけです。それから、発表会にしろ、練習にしろ、代替の場所などはどのようにご案内しているのか教えていただけますか。","respondent":"堀越生涯学習課長","answer":"旗の台文化センターにつきましても、利用者協議会の方々には前々から説明をしていますし、今後もそういう形で対応をさせていただきたいと考えております。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"トイレの手すりなどはその都度やっているというお話ですけれども、今回工事する以外の改修というのは、今後何か考えていらっしゃるのか。備品などは随時だと思いますけれども、大規模と小規模と中規模の用語がわからないので申し訳ないですけれども、荏原文化センターでこれ以外で今後改修を考えていらっしゃるのか教えていただけますか。","respondent":"堀越生涯学習課長","answer":"ただ、今、ご報告をさせていただいたようなものについては、今後平成２１年度の予算編成の作業に入ってまいりますので、そういった中でこれまでお寄せいただいている要望等を勘案しながら、どのような改修が必要かというのは。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"どんな声があがっているか、どんなふうに受けとめているのか教えていただきたいんです。お芝居の勉強をされている方もいらっしゃるようですけれども、防音設備は必要ではないかと思うんですけれども、その点はどうでしょうか。音が割れるんです。そういうところの備品の管理は、既に利用者協議会で出ている話だと思いますので、ぜひ進めていただきたいと思うんですけれども、いかがですか。","respondent":"堀越生涯学習課長","answer":"備品の関係については、いろいろ要望をいただいたものについては、対応してまいりたいというふうに考えております。それから、防音関係は、五反田文化センターもありますので、スタジオですとか、そういったものをぜひご利用いただければと考えています。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用者協議会でも声が上がっていると思うので、届いていましたらご紹介していただければと思います。利用者団体同士でああだこうだと言ってもうまくいかないので、床なのか、壁なのか、技術的なことはわからないですけれども、何とか防音設備ができないものか、教えていただけますか。","respondent":"堀越生涯学習課長","answer":"いろいろな利用にあたって何か工夫ができるような、例えば構造上の問題ではなくて、例えばドアの入り口ですとか、いろいろなところで工夫できるようなものがあれば検討していきたい。中塚委員おっしゃるとおり、今後のあり方については研究させていただきたい。","id":"exchange-032"},{"speaker":"山内副委員長","kind":"質問・要望","question":"旗の台文化センターの耐震補強工事の説明がありましたけれども、３階のスポーツ室を中心とした補強工事ということだったんですけれども、全体はやっているのか、そこだけ確認させていただきたいと思います。","respondent":"堀越生涯学習課長","answer":"耐震補強工事の内容ですが、３階にスポーツ室がありますので、天井の部分に鉄骨の柱を入れるような形と、あとは３階のギャラリーの窓枠にブレスを入れるということと、あとは水平の補強ということで、園庭側に鉄骨の柱が出るような形になります。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど長期的なという話があったんですけれども、今、長期基本計画をやっていて、必ず区長も「長期基本計画ができたら」ということをいつも言われるから、あえて言っておきますけれども、文化センターそのものは、もちろんシルバーセンターも含めて、これからいろいろ考えるのであれば、これはこれとしていいですけれども、しっかり考えていただいて、二重投資にならないような考え方。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の報告で伺いたいんですけれども、まずＵＳＢメモリーですけれども、学校のものなのか、個人のものなのか、教えていただきたいと思います。それから、なぜＵＳＢメモリーの中に理科の成績が入っているのか。普段であれば、職員室のパソコンを使ってやる作業なのかもしれませんが、なぜＵＳＢメモリーにコピーされているのか、その辺がよくわからないので教えていただけますか。","respondent":"富田学務課長","answer":"成績書類等々につきましては、９月から稼働いたします校務システムの中では一体化して管理されていくもので、区役所におきます本体サーバーの中に格納するということで実施していくところですが、現時点ではまだ学校で集中管理をしているところと。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"自分のＵＳＢメモリーに成績も含めた情報があるわけですね。そこがよくわからないので、どういう状況なのか教えていただけますか。","respondent":"河野指導課長","answer":"ただ、処理されたデータの保存については、学校として保存する場合には教務が紙ベースで保管するところも多々ありますので、学校によっては教科担任としては成績を出すまではパソコンを使って出し、出し終わったものについては。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"今回は私物に入れたということですから、やはり学校の中で様々あると思うんです。自分のメモリーで仕事をやったりといろいろなケースがあると思うんですが、もちろんセキュリティについては完全にしていかないといけないと考えていますけれども、非常勤講師の方の処分はどうなるのか。忠告だけで終わりなのか。","respondent":"河野指導課長","answer":"身分が県費ではありませんが、このまま何もしないで無罪放免というわけにもいかないと思います。教育委員会の中で協議をして、適切に対応したいと考えています。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"危機管理の上では、今回は紛失ですから、多分大きな問題は忘れてしまったということ自体が問題かもしれませんが、非常勤講師を責める、もちろん責任を取っていただくことも必要かもしれないですが、ただ、学園の中から出ていないわけです。紛失したということだと思うんです。そこの問題が非常に大きな問題ではないかと思っているんですが、それはどのようにされるんでしょうか。","respondent":"市川教育次長","answer":"対マスコミに関しても同様です。特に、八潮学園の今後の児童・生徒への対応の仕方、今、西本委員が懸念されていたことも含めて配慮して対応ということで、ぜひご理解をいただければと思います。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ難しい問題が出てくるかと思うんです。その辺は全面解決に向けて、決して非常勤講師の方だけに責任を負わせるということがあってはならないと思うんです。一生懸命やっている方だと思うんです。辞めていただくとかということがないような形で、配慮しながら進めていただきたいと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"山元委員","kind":"質問・要望","question":"やはり、区として、どこかでうちに関しては大丈夫という安心感がなかったのかということと同時に、やはり事故が起こったことに対しては仕方がないという言い方は変なんですか、前向きにこれからどういうふうにすればこういうことが起きないかということを徹底して究明しながら、二度とこういうことが起きないように考えていただきたいと思います。","respondent":"富田学務課長","answer":"事件が多く発生する機会があるわけですけれども、そういった中でありながらもセキュリティを守っていくための手立てを検討しているところで、今年４月には学務課の中に校務情報安全対策担当というセクションを設けましたので、こういったところを中心にしながら。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"区独自採用の３の応募資格の3)に１年間任用教員とありますけれども、区独自採用の人は１年間の繰り返しの更新ということなのでしょうか、よくわからなかったので教えていただけますか。","respondent":"河野指導課長","answer":"現在、品川区内の小学校に１０名ほど、年間任用教員を配置しています。年間任用教員は非常勤講師、常勤講師のどちらにもあてはまらない、いわゆる臨時的任用という範疇に入りますので、それも該当するということで、こういう表記をさせていただいているところです。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"７月２０日の日本テレビのバンキシャという番組を見ましたが、二つほど、現状はどうなのかということがあったので、よろしいでしょうか。非常に先生方が忙しいという内容でした。子どもたちと接する時間がないというご意見をいただいていた。その現状はどうなっているのか。やることもいっぱいあるし、教育改革を進める品川区ですから忙しいと思うんですが、今の現状を聞きたいと思います。","respondent":"河野指導課長","answer":"小中一貫教育の検証に伴って、さまざまな視点で教員の意識調査も実施しております。その中で品川区の教員が多忙感をどう感じているのか、どの程度感じているのかということについてもアンケート調査を実施しております。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"意見","question":"珍しく私も見させていただきました。アンケートで７割以上賛成だとか、ほとんどいいということでした。これは品川区にとって、そういうことがあると、教育長はあと何年いるかわからないけれども、せっかくこの道が引けたのであれば、それは全員でその道をしっかり支えていくということだけはしてほしいなと、一言だけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"宮崎科学技術館について、大淀川学習館について、これは何で入ってきたんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"中塚委員","kind":"意見","question":"生涯学習、ここで先進的な何か取り組みがあるという話であれば必要かなと思うけれども、五反田文化センターのプラネタリウムというのは、小さいけど力があるではないけれども、昔から親しまれているもので、それとここの世界第３位の大きさのプラネタリウムと、比べるものが少し違うのかなと思います。もう工事が進んでいますから、あれですけれども、その辺は感じますね。","respondent":"市川教育次長","answer":"小さい、大きいで言えば、装置自体もそんなに大きくありませんし、施設そのものも今回は大体２学級が入れるぐらいの大きさを考えております。","id":"exchange-045"},{"speaker":"中塚委員","kind":"意見","question":"プラネタリウム、いわば自然と科学を身近に子どもたちに感じもらって、興味を持ったり、また新たな視点をつくるということで、そういう意味では大事な教材の一つだと思っているんです。理科教育離れの問題意識の中で、どんなふうに子どもたちの意識や意欲を引き出していくのか、そういう問題意識を持っていくことが大事なのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"意見","question":"市民科とかいろいろな話をしたわけですけれども、どちらかというと私も文教委員会に所属をさせていただいて逆取材もあったり、どうしても箱物で大きいのは仕方ないですけれども、それが品川区に向けて何ができるかというと、なかなか箱物だけではというのがあるけれども、そうするとソフトの部分で学んでくればという意味で、今、プラネタリウムの話があったけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/361184?Template=document&Id=4640#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":41882,"voices":130}}]);
